static __attribute__((unused)) lb_str lb_21sema_standard_sources_6text_4 = {"#==============================================================================================\n#\n#   ryu - The shortest digits of a float (float_text)\n#\n#   DESCRIPTION:\n#       Ryu's d2d and f2s over float_text's tables of powers of five: the fewest decimal\n#       digits, and their power of ten, that read back as a finite nonzero f64 or f32.\n#\n#==============================================================================================\n\n# mark: Ryu ====================================================================================\n\n## Ryu's d2d: the shortest decimal digits * 10^exponent of a finite, nonzero f64, given its\n## mantissa and exponent fields.\nfunc shortest64(ieee_mantissa: u64, ieee_exponent: u32) -> (u64, i32):\n    var e2: i32 = 0\n    var m2: u64 = 0\n    if ieee_exponent == 0:\n        e2 = 1 - 1023 - 52 - 2\n        m2 = ieee_mantissa\n    else:\n        e2 = (i32)ieee_exponent - 1023 - 52 - 2\n        m2 = ((u64)1 << 52) | ieee_mantissa\n    let accept_bounds = (m2 & 1) == 0\n    let mv = 4 * m2\n    let mm_shift: u64 = 1 if ieee_mantissa != 0 or ieee_exponent <= 1 else 0\n    var vr: u64 = 0\n    var vp: u64 = 0\n    var vm: u64 = 0\n    var e10: i32 = 0\n    var vm_trailing_zeros = false\n    var vr_trailing_zeros = false\n    if e2 >= 0:\n        let q = log10_pow2(e2) - (1 if e2 > 3 else 0)\n        e10 = q\n        let k = 125 + pow5_bits(q) - 1\n        let i = -e2 + q + k\n        let row = (usize)q * 2\n        vr = mul_shift64(4 * m2, pow5_inv_split[row], pow5_inv_split[row + 1], i)\n        vp = mul_shift64(4 * m2 + 2, pow5_inv_split[row], pow5_inv_split[row + 1], i)\n        vm = mul_shift64(4 * m2 - 1 - mm_shift, pow5_inv_split[row], pow5_inv_split[row + 1], i)\n        if q <= 21:\n            if mv % 5 == 0:\n                vr_trailing_zeros = pow5_factor(mv) >= (u32)q\n            elif accept_bounds:\n                vm_trailing_zeros = pow5_factor(mv - 1 - mm_shift) >= (u32)q\n            elif pow5_factor(mv + 2) >= (u32)q:\n                vp -= 1\n    else:\n        let q = log10_pow5(-e2) - (1 if -e2 > 1 else 0)\n        e10 = q + e2\n        let i = -e2 - q\n        let k = pow5_bits(i) - 125\n        let j = q - k\n        let row = (usize)i * 2\n        vr = mul_shift64(4 * m2, pow5_split[row], pow5_split[row + 1], j)\n        vp = mul_shift64(4 * m2 + 2, pow5_split[row], pow5_split[row + 1], j)\n        vm = mul_shift64(4 * m2 - 1 - mm_shift, pow5_split[row], pow5_split[row + 1], j)\n        if q <= 1:\n            vr_trailing_zeros = true\n            if accept_bounds:\n                vm_trailing_zeros = mm_shift == 1\n            else:\n                vp -= 1\n        elif q < 63:\n            vr_trailing_zeros = (mv & (((u64)1 << (u64)q) - 1)) == 0\n    return trimmed(vr, vp, vm, e10, accept_bounds, vm_trailing_zeros, vr_trailing_zeros, 0)\n\n## Ryu's digit removal, d2d's and f2s's alike: drop digits while the bounds still differ,\n## then round on the last digit removed (`start_last`, the one f2s's bounds computation\n## already dropped, or 0). Dropping two digits at once leaves their tens digit as the last.\nfunc trimmed(start_vr: u64, start_vp: u64, start_vm: u64, e10: i32, accept_bounds: bool, start_vm_zeros: bool, start_vr_zeros: bool, start_last: u64) -> (u64, i32):\n    var vr = start_vr\n    var vp = start_vp\n    var vm = start_vm\n    var vm_trailing_zeros = start_vm_zeros\n    var vr_trailing_zeros = start_vr_zeros\n    var removed: i32 = 0\n    var last_removed = start_last\n    if vm_trailing_zeros or vr_trailing_zeros:\n        while vp // 10 > vm // 10:\n            vm_trailing_zeros = vm_trailing_zeros and vm % 10 == 0\n            vr_trailing_zeros = vr_trailing_zeros and last_removed == 0\n            last_removed = vr % 10\n            vr = vr // 10\n            vp = vp // 10\n            vm = vm // 10\n            removed += 1\n        if vm_trailing_zeros:\n            while vm % 10 == 0:\n                vr_trailing_zeros = vr_trailing_zeros and last_removed == 0\n                last_removed = vr % 10\n                vr = vr // 10\n                vp = vp // 10\n                vm = vm // 10\n                removed += 1\n        if vr_trailing_zeros and last_removed == 5 and vr % 2 == 0:\n            last_removed = 4\n        let up = (vr == vm and (not accept_bounds or not vm_trailing_zeros)) or last_removed >= 5\n        return (vr + (1 if up else 0), e10 + removed)\n    if vp // 100 > vm // 100:\n        last_removed = (vr % 100) // 10\n        vr = vr // 100\n        vp = vp // 100\n        vm = vm // 100\n        removed += 2\n    while vp // 10 > vm // 10:\n        last_removed = vr % 10\n        vr = vr // 10\n        vp = vp // 10\n        vm = vm // 10\n        removed += 1\n    return (vr + (1 if vr == vm or last_removed >= 5 else 0), e10 + removed)\n\n## Ryu's f2s over the same tables: the shortest decimal digits * 10^exponent of a finite,\n## nonzero f32.\nfunc shortest32(ieee_mantissa: u32, ieee_exponent: u32) -> (u32, i32):\n    var e2: i32 = 0\n    var m2: u32 = 0\n    if ieee_exponent == 0:\n        e2 = 1 - 127 - 23 - 2\n        m2 = ieee_mantissa\n    else:\n        e2 = (i32)ieee_exponent - 127 - 23 - 2\n        m2 = ((u32)1 << 23) | ieee_mantissa\n    let accept_bounds = (m2 & 1) == 0\n    let mv = 4 * m2\n    let mp = 4 * m2 + 2\n    let mm_shift: u32 = 1 if ieee_mantissa != 0 or ieee_exponent <= 1 else 0\n    let mm = 4 * m2 - 1 - mm_shift\n    var vr: u32 = 0\n    var vp: u32 = 0\n    var vm: u32 = 0\n    var e10: i32 = 0\n    var vm_trailing_zeros = false\n    var vr_trailing_zeros = false\n    var last_removed: u32 = 0\n    if e2 >= 0:\n        let q = log10_pow2(e2)\n        e10 = q\n        let k = 61 + pow5_bits(q) - 1\n        let i = -e2 + q + k\n        vr = pow5_inv_div_pow2(mv, q, i)\n        vp = pow5_inv_div_pow2(mp, q, i)\n        vm = pow5_inv_div_pow2(mm, q, i)\n        if q != 0 and (vp - 1) // 10 <= vm // 10:\n            let l = 61 + pow5_bits(q - 1) - 1\n            last_removed = pow5_inv_div_pow2(mv, q - 1, -e2 + q - 1 + l) % 10\n        if q <= 9:\n            if mv % 5 == 0:\n                vr_trailing_zeros = pow5_factor((u64)mv) >= (u32)q\n            elif accept_bounds:\n                vm_trailing_zeros = pow5_factor((u64)mm) >= (u32)q\n            elif pow5_factor((u64)mp) >= (u32)q:\n                vp -= 1\n    else:\n        let q = log10_pow5(-e2)\n        e10 = q + e2\n        let i = -e2 - q\n        let k = pow5_bits(i) - 61\n        var j = q - k\n        vr = pow5_div_pow2(mv, i, j)\n        vp = pow5_div_pow2(mp, i, j)\n        vm = pow5_div_pow2(mm, i, j)\n        if q != 0 and (vp - 1) // 10 <= vm // 10:\n            j = q - 1 - (pow5_bits(i + 1) - 61)\n            last_removed = pow5_div_pow2(mv, i + 1, j) % 10\n        if q <= 1:\n            vr_trailing_zeros = true\n            if accept_bounds:\n                vm_trailing_zeros = mm_shift == 1\n            else:\n                vp -= 1\n        elif q < 31:\n            vr_trailing_zeros = (mv & (((u32)1 << (u32)(q - 1)) - 1)) == 0\n    let (digits, exponent) = trimmed((u64)vr, (u64)vp, (u64)vm, e10, accept_bounds, vm_trailing_zeros, vr_trailing_zeros, (u64)last_removed)\n    return (u32(digits), exponent)\n\n## floor(log2(5^e)) + 1 for 0 <= e <= 3528.\ninline func pow5_bits(e: i32) -> i32:\n    return (i32)((((u32)e) * 1217359) >> 19) + 1\n\n## floor(log10(2^e)) for 0 <= e <= 1650.\ninline func log10_pow2(e: i32) -> i32:\n    return (i32)((((u32)e) * 78913) >> 18)\n\n## floor(log10(5^e)) for 0 <= e <= 2620.\ninline func log10_pow5(e: i32) -> i32:\n    return (i32)((((u32)e) * 732923) >> 20)\n\n## How many times 5 divides `value` (nonzero).\nfunc pow5_factor(value: u64) -> u32:\n    var rest = value\n    var count: u32 = 0\n    while rest % 5 == 0:\n        rest = rest // 5\n        count += 1\n    return count\n\n## (m * (high:low)) >> j for Ryu's 125-bit multipliers.\ninline func mul_shift64(m: u64, low: u64, high: u64, j: i32) -> u64:\n    var b0_low: u64 = 0\n    let b0_high = product(m, low, &b0_low)\n    var b2_low: u64 = 0\n    var b2_high = product(m, high, &b2_low)\n    let sum_low = b2_low +% b0_high\n    if sum_low < b2_low:\n        b2_high += 1\n    let shift = (u64)(j - 64)\n    if shift == 0:\n        return sum_low\n    if shift >= 64:\n        return b2_high >> (shift - 64)\n    return (b2_high << (64 - shift)) | (sum_low >> shift)\n\ninline func mul_shift32(m: u32, factor: u64, shift: i32) -> u32:\n    let low = (u64)m * (factor & 0xFFFFFFFF)\n    let high = (u64)m * (factor >> 32)\n    let sum = (low >> 32) + high\n    return (u32)(sum >> (u64)(shift - 32))\n\ninline func pow5_inv_div_pow2(m: u32, q: i32, j: i32) -> u32:\n    return mul_shift32(m, pow5_inv_split[(usize)q * 2 + 1] + 1, j)\n\ninline func pow5_div_pow2(m: u32, i: i32, j: i32) -> u32:\n    return mul_shift32(m, pow5_split[(usize)i * 2 + 1], j)\n\n## The 128-bit product a * b: the high word, the low word stored in `low`. Ryu's\n## multiplications and strings' float parsing (Lemire's) both take it.\npub inline func product(a: u64, b: u64, low: u64*) -> u64:\n    let a0 = a & 0xFFFFFFFF\n    let a1 = a >> 32\n    let b0 = b & 0xFFFFFFFF\n    let b1 = b >> 32\n    let p00 = a0 * b0\n    let p01 = a0 * b1\n    let p10 = a1 * b0\n    let p11 = a1 * b1\n    let middle = (p00 >> 32) + (p01 & 0xFFFFFFFF) + (p10 & 0xFFFFFFFF)\n    *low = (middle << 32) | (p00 & 0xFFFFFFFF)\n    return p11 + (p01 >> 32) + (p10 >> 32) + (middle >> 32)\n", 9256};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_6text_5 = {"#==============================================================================================\n#\n#   numerals - Numbers and text laid out by a format specification\n#\n#   DESCRIPTION:\n#       What a formatted string's `{value:spec}` field does (base.md \302\2475.5), as Python's\n#       `format` does it: the specification read as CPython's\n#       parse_internal_render_format_spec reads it, a number laid out as calc_number_widths\n#       and fill_number lay it out, and a float's digits made exactly and rounded half to\n#       even, as David Gay's dtoa rounds them. The text goes to a `Sink` piece by piece, so\n#       nothing is allocated and nothing bounds a field but the sink. The compiler reads a\n#       field's specification with `read` and `misfit` and refuses one that does not fit;\n#       the program lays the field out with `lay_integer`, `lay_float` or `lay_text`. It is\n#       the one implementation: Luce lays out its fields and rounds `math.round` with it too,\n#       wording a misfit in its own terms from `misfit_of` (luce src/support/number_text.lucb),\n#       and the seed carries a copy of this file. It comes after `float_text` and before\n#       `core`, and needs nothing else.\n#\n#==============================================================================================\n\nimport float_text\n\n# mark: Specifications =========================================================================\n\n## A specification read: `[[fill]align][sign][z][#][0][width][grouping][.precision][type]`\n## (\302\2475.5). A part not written is `0`, `-1` or empty, so a default can still be told apart.\npub struct Spec:\n    ## The fill scalar, as written; empty when none was.\n    pub var fill: str\n    ## `<`, `>`, `^` or `=`; 0 when none was written.\n    pub var align: u8\n    ## `+`, `-` or a space; 0 when none was written.\n    pub var sign: u8\n    ## `z`: a negative zero, after rounding, shows as zero.\n    pub var no_negative_zero: bool\n    ## `#`: the alternate form, a base's prefix or a point always kept.\n    pub var alternate: bool\n    ## `0` before the width: zeros fill a number after its sign.\n    pub var zero: bool\n    ## The least width in scalars; -1 when none was written.\n    pub var width: i64\n    ## `,` or `_` between groups of digits; 0 when none was written.\n    pub var grouping: u8\n    ## The digits after the point, or the scalars a text keeps; -1 when none was written.\n    pub var precision: i64\n    ## The type letter; 0 when none was written.\n    pub var kind: u8\n\n## A specification read from its text, and what is wrong with it: empty when nothing is.\npub struct Reading:\n    ## The specification, meaningful when `problem` is empty.\n    pub var spec: Spec\n    ## Why the text is not a specification; empty when it is one.\n    pub var problem: str\n\n## What a field shows: an integer, a float, or text (a `str`, a `char`, a `bool`).\npub enum Category:\n    integer\n    floating\n    text\n\nfunc is_align(byte: u8) -> bool:\n    return byte == '<' or byte == '>' or byte == '^' or byte == '='\n\n## The byte length of the UTF-8 scalar starting with `lead`.\nfunc scalar_bytes(lead: u8) -> usize:\n    if lead < 0x80:\n        return 1\n    if lead < 0xE0:\n        return 2\n    if lead < 0xF0:\n        return 3\n    return 4\n\n## The scalars of UTF-8 `text`.\npub func scalar_count(text: const u8[]) -> i64:\n    var n: i64 = 0\n    for b in text:\n        if (b & 0xC0) != 0x80:\n            n += 1\n    return n\n\n## Digits read from `at` as a width or a precision; how many there were, -1 when too many.\nfunc read_count(b: const u8[], at: usize*, value: i64*) -> i64:\n    var n: i64 = 0\n    var total: i64 = 0\n    while *at < b.length and b[*at] >= '0' and b[*at] <= '9':\n        total = total * 10 + (i64)(b[*at] - '0')\n        if total > 1000000000:\n            return -1\n        n += 1\n        *at += 1\n    *value = total\n    return n\n\n## Read `text` as CPython's parse_internal_render_format_spec reads a specification.\npub func read(text: str) -> Reading:\n    var spec = Spec(fill = \"\", align = 0, sign = 0, no_negative_zero = false, alternate = false, zero = false, width = -1, grouping = 0, precision = -1, kind = 0)\n    let b = text.bytes\n    var at: usize = 0\n    var first: usize = 0\n    if b.length > 0:\n        first = scalar_bytes(b[0])\n    if b.length > first and is_align(b[first]):\n        spec.fill = (str)b[..<first]\n        spec.align = b[first]\n        at = first + 1\n    elif b.length > 0 and is_align(b[0]):\n        spec.align = b[0]\n        at = 1\n    if at < b.length and (b[at] == '+' or b[at] == '-' or b[at] == ' '):\n        spec.sign = b[at]\n        at += 1\n    if at < b.length and b[at] == 'z':\n        spec.no_negative_zero = true\n        at += 1\n    if at < b.length and b[at] == '#':\n        spec.alternate = true\n        at += 1\n    if spec.fill.length == 0 and at < b.length and b[at] == '0':\n        spec.zero = true\n        at += 1\n    var width: i64 = 0\n    let digits = read_count(b, &at, &width)\n    if digits < 0:\n        return Reading(spec = spec, problem = \"its width is too large\")\n    if digits > 0:\n        spec.width = width\n    if at < b.length and (b[at] == ',' or b[at] == '_'):\n        spec.grouping = b[at]\n        at += 1\n        if at < b.length and (b[at] == ',' or b[at] == '_'):\n            return Reading(spec = spec, problem = \"it groups digits with both `,` and `_`\")\n    if at < b.length and b[at] == '.':\n        at += 1\n        var precision: i64 = 0\n        let n = read_count(b, &at, &precision)\n        if n < 0:\n            return Reading(spec = spec, problem = \"its precision is too large\")\n        if n == 0:\n            return Reading(spec = spec, problem = \"a `.` is followed by the precision's digits\")\n        spec.precision = precision\n    if b.length - at > 1:\n        return Reading(spec = spec, problem = \"it is not `[[fill]align][sign][z][#][0][width][grouping][.precision][type]`\")\n    if at < b.length:\n        spec.kind = b[at]\n    return Reading(spec = spec, problem = \"\")\n\n## Why a specification does not fit a value of its category, for its caller to word.\npub enum Misfit:\n    ## It fits.\n    fits\n    ## An integer with `e`, `f`, `g`, `%` or their upper cases.\n    float_type_of_integer\n    ## An integer with a type letter of no number.\n    integer_type\n    ## An integer with a precision.\n    integer_precision\n    ## An integer with `z`.\n    integer_z\n    ## A `c` with a sign.\n    scalar_sign\n    ## A `c` with `#`.\n    scalar_alternate\n    ## `,` with `b`, `o`, `x` or `X`.\n    comma_grouping\n    ## A `c` with `_`.\n    scalar_grouping\n    ## A float with a type letter of no float.\n    float_type\n    ## Text with a type letter other than `s`.\n    text_type\n    ## Text with a sign.\n    text_sign\n    ## Text with `z`.\n    text_z\n    ## Text with `#`.\n    text_alternate\n    ## Text aligned with `=`.\n    text_after_sign\n    ## Text with grouping.\n    text_grouping\n\n## Why `spec` does not fit a value of `category`, or `fits` (\302\2475.5).\npub func misfit_of(spec: Spec, category: Category) -> Misfit:\n    let k = spec.kind\n    match category:\n        .integer:\n            if k == 'e' or k == 'E' or k == 'f' or k == 'F' or k == 'g' or k == 'G' or k == '%':\n                return Misfit.float_type_of_integer\n            if k != 0 and k != 'd' and k != 'b' and k != 'o' and k != 'x' and k != 'X' and k != 'c':\n                return Misfit.integer_type\n            if spec.precision >= 0:\n                return Misfit.integer_precision\n            if spec.no_negative_zero:\n                return Misfit.integer_z\n            if k == 'c' and spec.sign != 0:\n                return Misfit.scalar_sign\n            if k == 'c' and spec.alternate:\n                return Misfit.scalar_alternate\n            if spec.grouping == ',' and k != 0 and k != 'd':\n                return Misfit.comma_grouping\n            if spec.grouping == '_' and k == 'c':\n                return Misfit.scalar_grouping\n        .floating:\n            if k != 0 and k != 'e' and k != 'E' and k != 'f' and k != 'F' and k != 'g' and k != 'G' and k != '%':\n                return Misfit.float_type\n        .text:\n            if k != 0 and k != 's':\n                return Misfit.text_type\n            if spec.sign != 0:\n                return Misfit.text_sign\n            if spec.no_negative_zero:\n                return Misfit.text_z\n            if spec.alternate:\n                return Misfit.text_alternate\n            if spec.align == '=':\n                return Misfit.text_after_sign\n            if spec.grouping != 0:\n                return Misfit.text_grouping\n    return Misfit.fits\n\n## What is wrong with `spec` for a value of `category`, in Base's terms: empty when it\n## fits (\302\2475.5).\npub func misfit(spec: Spec, category: Category) -> str:\n    match misfit_of(spec, category):\n        .fits:\n            return \"\"\n        .float_type_of_integer:\n            return \"its type letter formats a float; convert the integer with `f64(...)` first\"\n        .integer_type:\n            return \"an integer is formatted with `d`, `b`, `o`, `x`, `X` or `c`\"\n        .integer_precision:\n            return \"an integer takes no precision\"\n        .integer_z, .text_z:\n            return \"`z` belongs to a float\"\n        .scalar_sign:\n            return \"`c` takes no sign\"\n        .scalar_alternate:\n            return \"`c` takes no `#`\"\n        .comma_grouping:\n            return \"`,` groups decimal digits; `_` groups `b`, `o`, `x` and `X`\"\n        .scalar_grouping:\n            return \"`c` takes no grouping\"\n        .float_type:\n            return \"a float is formatted with `e`, `E`, `f`, `F`, `g`, `G` or `%`\"\n        .text_type:\n            return \"text is formatted with `s` or no type\"\n        .text_sign:\n            return \"a sign belongs to a number\"\n        .text_alternate:\n            return \"`#` belongs to a number\"\n        .text_after_sign:\n            return \"`=` aligns a number after its sign\"\n        .text_grouping:\n            return \"grouping belongs to a number\"\n\n## The fill and alignment a field uses: the written ones, else the defaults, a number to\n## the right and text to the left, and `0` before the width filling with zeros after the\n## sign (CPython's backwards-compatible special case).\nfunc settle(spec: Spec, numeric: bool) -> Spec:\n    var out = spec\n    if spec.zero:\n        out.fill = \"0\"\n        if spec.align == 0 and numeric:\n            out.align = '='\n    if out.fill.length == 0:\n        out.fill = \" \"\n    if out.align == 0:\n        out.align = '>' if numeric else '<'\n    return out\n\n## The settled specification of `specification`, which the compiler has read and fitted.\nfunc settled(specification: str, numeric: bool) -> Spec:\n    let reading = read(specification)\n    if reading.problem.length > 0:\n        trap(\"a formatted field's specification is not one; the compiler refuses it\")\n    return settle(reading.spec, numeric)\n\n# mark: Output =================================================================================\n\n## Where laid-out text goes: `write` appends `bytes` to `context`, answering false when\n## they did not all fit, which ends the layout.\npub struct Sink:\n    ## What the text is written into, handed to `write`.\n    pub var context: void*\n    ## Append the bytes; false when they did not all fit.\n    pub var write: func(void*, const u8[]) -> bool\n\nfunc put(sink: Sink, bytes: const u8[]) -> bool:\n    let write = sink.write\n    return bytes.length == 0 or write(sink.context, bytes)\n\nfunc put_byte(sink: Sink, byte: u8) -> bool:\n    let one: u8[1] = [byte]\n    return put(sink, one)\n\n## `text` `n` times.\nfunc repeat(sink: Sink, text: str, n: i64) -> bool:\n    var i: i64 = 0\n    while i < n:\n        if not put(sink, text.bytes):\n            return false\n        i += 1\n    return true\n\n## `text` with its lower-case letters in upper case when `upper`.\nfunc put_cased(sink: Sink, text: const u8[], upper: bool) -> bool:\n    if not upper:\n        return put(sink, text)\n    for c in text:\n        if not put_byte(sink, c - 32 if c >= 'a' and c <= 'z' else c):\n            return false\n    return true\n\n## Padding before and after `n` scalars to `width`, by the alignment (CPython's calc_padding).\nfunc padding(n: i64, width: i64, align: u8) -> (i64, i64):\n    let total = width if width > n else n\n    var left: i64 = 0\n    if align == '>':\n        left = total - n\n    elif align == '^':\n        left = (total - n) // 2\n    return (left, total - n - left)\n\nfunc smaller(a: i64, b: i64) -> i64:\n    return a if a < b else b\n\nfunc larger(a: i64, b: i64) -> i64:\n    return a if a > b else b\n\n# mark: Digits =================================================================================\n\n## Digits, a virtual `0` outside `[0, count)`: an integer's in its base, or the exact\n## decimal digits of a float's magnitude, `0.d1d2d3... \303\227 10^point`, at most 767 significant\n## digits for any finite f64 and no trailing zero.\npub struct Decimal:\n    ## The digits, as ASCII; the first `count` are meaningful.\n    pub var digits: u8[800]\n    ## How many digits there are; 0 is zero.\n    pub var count: usize\n    ## Where the point stands: before `digits[point]`, a negative `point` that many zeros\n    ## earlier.\n    pub var point: i64\n\n    ## The digit at virtual index `i`.\n    pub func at(i: i64) -> u8:\n        return self.digits[(usize)i] if i >= 0 and i < (i64)self.count else '0'\n\n## The digits of `magnitude` in `base` (2, 8, 10 or 16), lower case.\nfunc integer_digits(magnitude: u64, base: u64) -> Decimal:\n    var d: Decimal = ---\n    var reversed: u8[64] = ---\n    var n: usize = 0\n    var v = magnitude\n    while true:\n        let digit = (u8)(v % base)\n        reversed[n] = '0' + digit if digit < 10 else 'a' + digit - 10\n        n += 1\n        v = v // base\n        if v == 0:\n            break\n    d.count = n\n    d.point = (i64)n\n    var i: usize = 0\n    while i < n:\n        d.digits[i] = reversed[n - 1 - i]\n        i += 1\n    return d\n\n## The digits of |value|, finite: the significand times a power of two, made decimal in\n## limbs of 10^9 exactly (multiplying by 2^k, or by 5^k for a negative exponent).\nfunc exact(value: f64) -> Decimal:\n    var d: Decimal = ---\n    d.count = 0\n    d.point = 0\n    let bits = value.bits()\n    let exponent_bits = (i64)((bits >> 52) & 0x7FF)\n    var significand = bits & 0xFFFFFFFFFFFFF\n    var exponent: i64 = -1074\n    if exponent_bits != 0:\n        significand = significand | 0x10000000000000\n        exponent = exponent_bits - 1075\n    if significand == 0:\n        d.digits[0] = '0'\n        d.count = 1\n        d.point = 1\n        return d\n    var limbs: u64[100] = ---\n    limbs[0] = significand % 1000000000\n    limbs[1] = significand // 1000000000\n    var used: usize = 2 if limbs[1] != 0 else 1\n    if exponent >= 0:\n        var left = exponent\n        while left > 0:\n            let shift = left if left < 30 else 30\n            used = multiply(limbs, used, (u64)1 << (u64)shift)\n            left -= shift\n    else:\n        var left = -exponent\n        while left > 0:\n            let step = left if left < 13 else 13\n            var factor: u64 = 1\n            for _ in 0..<step:\n                factor *= 5\n            used = multiply(limbs, used, factor)\n            left -= step\n    # the top limb without leading zeros, every other one as nine digits\n    var top: u8[9] = ---\n    var n: usize = 0\n    var high = limbs[used - 1]\n    while high > 0:\n        top[n] = '0' + (u8)(high % 10)\n        high = high // 10\n        n += 1\n    while n > 0:\n        n -= 1\n        d.digits[d.count] = top[n]\n        d.count += 1\n    var i = used - 1\n    while i > 0:\n        i -= 1\n        var limb = limbs[i]\n        var k: usize = 9\n        while k > 0:\n            k -= 1\n            d.digits[d.count + k] = '0' + (u8)(limb % 10)\n            limb = limb // 10\n        d.count += 9\n    d.point = (i64)d.count + (exponent if exponent < 0 else 0)\n    trim_zeros(&d)\n    return d\n\n## `limbs[..<used] *= factor`, factor at most 2^30; the limbs now used.\nfunc multiply(limbs: u64[], used: usize, factor: u64) -> usize:\n    var carry: u64 = 0\n    var i: usize = 0\n    while i < used:\n        let product = limbs[i] * factor + carry\n        limbs[i] = product % 1000000000\n        carry = product // 1000000000\n        i += 1\n    var n = used\n    while carry > 0:\n        limbs[n] = carry % 1000000000\n        carry = carry // 1000000000\n        n += 1\n    return n\n\nfunc trim_zeros(d: Decimal*):\n    while d.count > 1 and d.digits[d.count - 1] == '0':\n        d.count -= 1\n\n## Keep the first `keep` digits, rounding half to even on the exact value; `keep` may be 0\n## or less, which leaves zero (`count` 0) or one digit carried up.\nfunc round_to(d: Decimal*, keep: i64):\n    if keep >= (i64)d.count:\n        return\n    var up = false\n    if keep >= 0:\n        let next = d.digits[(usize)keep]\n        var beyond = false\n        var i = (usize)keep + 1\n        while i < d.count:\n            if d.digits[i] != '0':\n                beyond = true\n            i += 1\n        let odd = keep > 0 and ((d.digits[(usize)keep - 1] - '0') % 2) == 1\n        up = next > '5' or (next == '5' and (beyond or odd))\n    if keep <= 0:\n        d.count = 0\n        if up:\n            d.digits[0] = '1'\n            d.count = 1\n            d.point += 1\n        return\n    d.count = (usize)keep\n    if up:\n        var i = d.count\n        var carried = true\n        while carried and i > 0:\n            i -= 1\n            if d.digits[i] == '9':\n                d.digits[i] = '0'\n            else:\n                d.digits[i] += 1\n                carried = false\n        if carried:\n            # every kept digit was 9: one digit, a 1, a place higher\n            d.digits[0] = '1'\n            d.count = 1\n            d.point += 1\n    trim_zeros(d)\n    if d.count == 1 and d.digits[0] == '0':\n        d.count = 0\n\n## The exact decimal digits of finite |value| rounded half to even to `places` after the\n## point (before it, for a negative `places`), as dtoa's mode 3 makes them for Python's\n## `round(x, places)`: no trailing zero, zero as `0` at point 1, and no digit at all, at\n## point `-places`, when the rounding leaves nothing.\npub func decimal_places(value: f64, places: i64) -> Decimal:\n    return digits_of(value, 3, places)\n\n## dtoa's mode 2 (`n` significant digits) or mode 3 (`n` digits after the point, any sign)\n## of a finite |value|: rounded half to even, no trailing zero, zero as `0` at point 1, and\n## nothing left at point `-n` when mode 3 rounds it all away.\nfunc digits_of(value: f64, mode: u8, n: i64) -> Decimal:\n    var d = exact(value)\n    if d.count == 1 and d.digits[0] == '0':\n        return d\n    if mode == 2:\n        round_to(&d, n if n > 1 else 1)\n    else:\n        round_to(&d, d.point + n)\n        if d.count == 0:\n            d.point = -n\n    return d\n\n# mark: Numbers ================================================================================\n\n## A number to lay out: its sign, a base's prefix, the digits `[first, last)` of `digits`\n## with the point before index `point` (shown when `dot`), and what follows them, an\n## exponent, `%`, or the scalar a `c` field names.\nstruct Number:\n    var negative: bool\n    var prefix: str\n    var digits: Decimal\n    var first: i64\n    var point: i64\n    var last: i64\n    var dot: bool\n    var rest: u8[8]\n    var rest_length: usize\n\n## The digits a group of `interval` with zeros reaching `least` scalars make, CPython's\n## _PyUnicode_InsertThousandsGrouping: `n` digits, at least as many as reach `least` with a\n## separator between each group; no groups when `interval` is 0.\nfunc padded_digits(n: i64, least: i64, interval: i64) -> i64:\n    var count = n if n > 0 else 1\n    if interval == 0:\n        return larger(count, least)\n    while count + (count - 1) // interval < least:\n        count += 1\n    return count\n\n## A number laid out as CPython's calc_number_widths and fill_number lay it out:\n## `[padding] sign prefix [padding] grouped-digits [point] rest [padding]`. `spec` is settled.\nfunc lay_number(sink: Sink, n: Number*, spec: Spec, upper: bool) -> bool:\n    var sign: u8 = 0\n    if spec.sign == '+':\n        sign = '-' if n.negative else '+'\n    elif spec.sign == ' ':\n        sign = '-' if n.negative else ' '\n    elif n.negative:\n        sign = '-'\n    let rest = n.rest[..<n.rest_length]\n    let fraction = n.last - n.point if n.last > n.point else 0\n    let fixed = (1 if sign != 0 else 0) + (i64)n.prefix.length + (1 if n.dot else 0) + fraction + scalar_count(rest)\n    let least = spec.width - fixed if spec.fill == \"0\" and spec.align == '=' else 0\n    let interval: i64 = 0 if spec.grouping == 0 else (4 if spec.kind == 'b' or spec.kind == 'o' or spec.kind == 'x' or spec.kind == 'X' else 3)\n    let whole = n.point - n.first\n    # a `c` field has no digits, only the scalar it names\n    let count = padded_digits(whole, least, interval) if whole > 0 or n.rest_length == 0 or n.dot else 0\n    let body = count + ((count - 1) // interval if interval > 0 and count > 0 else 0)\n    let spare = spec.width - (fixed + body)\n    var before: i64 = 0\n    var between: i64 = 0\n    var after: i64 = 0\n    if spare > 0:\n        if spec.align == '<':\n            after = spare\n        elif spec.align == '^':\n            before = spare // 2\n            after = spare - before\n        elif spec.align == '=':\n            between = spare\n        else:\n            before = spare\n    if not repeat(sink, spec.fill, before):\n        return false\n    if sign != 0 and not put_byte(sink, sign):\n        return false\n    if not put_cased(sink, n.prefix.bytes, upper) or not repeat(sink, spec.fill, between):\n        return false\n    # the whole part's digits, the leftmost `count - whole` of them padding zeros\n    var k: i64 = 0\n    while k < count:\n        if interval > 0 and k > 0 and (count - k) % interval == 0 and not put_byte(sink, spec.grouping):\n            return false\n        let digit = n.digits.at(n.point - count + k) if k >= count - whole else '0'\n        if not put_byte(sink, digit - 32 if upper and digit >= 'a' and digit <= 'z' else digit):\n            return false\n        k += 1\n    if n.dot and not put_byte(sink, '.'):\n        return false\n    var i = n.point\n    while i < n.last:\n        if not put_byte(sink, n.digits.at(i)):\n            return false\n        i += 1\n    return put_cased(sink, rest, upper) and repeat(sink, spec.fill, after)\n\n## A number with no digits yet: positive, no prefix, nothing after.\nfunc number(digits: Decimal) -> Number:\n    return Number(negative = false, prefix = \"\", digits = digits, first = 0, point = digits.point, last = digits.point, dot = false, rest = [0, 0, 0, 0, 0, 0, 0, 0], rest_length = 0)\n\n## `bytes` after the digits of `n`.\nfunc add_rest(n: Number*, bytes: const u8[]):\n    for b in bytes:\n        if n.rest_length < 8:\n            n.rest[n.rest_length] = b\n            n.rest_length += 1\n\n## An integer field `{value:spec}`, its sign apart from its magnitude, laid out by\n## `specification`. A `c` field of a number that names no Unicode scalar traps.\npub func lay_integer(sink: Sink, negative: bool, magnitude: u64, specification: str) -> bool:\n    let spec = settled(specification, true)\n    if spec.kind == 'c':\n        if not is_scalar(negative, magnitude):\n            trap(\"a `c` field's number names no Unicode scalar\")\n        var n = number(integer_digits(0, 10))\n        n.first = n.point\n        var buffer: u8[4]\n        add_rest(&n, encode_scalar((u32)magnitude, buffer))\n        return lay_number(sink, &n, spec, false)\n    var base: u64 = 10\n    var prefix = \"\"\n    if spec.kind == 'b':\n        base = 2\n        prefix = \"0b\"\n    elif spec.kind == 'o':\n        base = 8\n        prefix = \"0o\"\n    elif spec.kind == 'x' or spec.kind == 'X':\n        base = 16\n        prefix = \"0x\"\n    var n = number(integer_digits(magnitude, base))\n    n.negative = negative\n    if spec.alternate:\n        n.prefix = prefix\n    return lay_number(sink, &n, spec, spec.kind == 'X')\n\n## Whether the integer of `negative` and `magnitude` names a Unicode scalar, as a `c`\n## field's number must: from 0 to U+10FFFF, not a surrogate. A caller that must not trap\n## asks before laying a `c` field out.\npub func is_scalar(negative: bool, magnitude: u64) -> bool:\n    return not negative and magnitude <= 0x10FFFF and (magnitude < 0xD800 or magnitude > 0xDFFF)\n\n## The UTF-8 of scalar `value` in `buffer`, which holds four bytes.\npub func encode_scalar(value: u32, buffer: u8[]) -> const u8[]:\n    if value < 0x80:\n        buffer[0] = (u8)value\n        return buffer[..<1]\n    if value < 0x800:\n        buffer[0] = (u8)(0xC0 | (value >> 6))\n        buffer[1] = (u8)(0x80 | (value & 0x3F))\n        return buffer[..<2]\n    if value < 0x10000:\n        buffer[0] = (u8)(0xE0 | (value >> 12))\n        buffer[1] = (u8)(0x80 | ((value >> 6) & 0x3F))\n        buffer[2] = (u8)(0x80 | (value & 0x3F))\n        return buffer[..<3]\n    buffer[0] = (u8)(0xF0 | (value >> 18))\n    buffer[1] = (u8)(0x80 | ((value >> 12) & 0x3F))\n    buffer[2] = (u8)(0x80 | ((value >> 6) & 0x3F))\n    buffer[3] = (u8)(0x80 | (value & 0x3F))\n    return buffer[..<4]\n\n# mark: Floats =================================================================================\n\n## A float field `{value:spec}` laid out by `specification`; `single` when the\n## value is an `f32` (or an `f16`), whose display is its own shortest digits. With neither a\n## type nor a precision a field shows the value's display, where Python shows its repr.\npub func lay_float(sink: Sink, value: f64, single: bool, specification: str) -> bool:\n    let spec = settled(specification, true)\n    var x = value\n    var kind = spec.kind\n    var percent = false\n    if kind == '%':\n        x = x * 100.0\n        kind = 'f'\n        percent = true\n    var n = number(integer_digits(0, 10))\n    if kind == 0 and spec.precision < 0:\n        displayed(&n, x, single, spec.no_negative_zero)\n    else:\n        short(&n, x, kind, spec.precision if spec.precision >= 0 else 6, spec.alternate, spec.no_negative_zero)\n    if percent:\n        add_rest(&n, \"%\".bytes)\n    return lay_number(sink, &n, spec, kind == 'E' or kind == 'F' or kind == 'G')\n\n## The display of `value` (\302\24714.4) as a number to lay out: its digits up to the point, the\n## point, and the rest (more digits, an exponent) as they are.\nfunc displayed(n: Number*, value: f64, single: bool, no_negative_zero: bool):\n    var shown: u8[40] = ---\n    let length = float_text.display_f32((f32)value, shown) if single else float_text.display_f64(value, shown)\n    var at: usize = 0\n    if shown[0] == '-':\n        n.negative = not (no_negative_zero and value == 0.0)\n        at = 1\n    var d: Decimal = ---\n    d.count = 0\n    while at < length and shown[at] >= '0' and shown[at] <= '9':\n        d.digits[d.count] = shown[at]\n        d.count += 1\n        at += 1\n    d.point = (i64)d.count\n    if at < length and shown[at] == '.':\n        at += 1\n        while at < length and shown[at] >= '0' and shown[at] <= '9':\n            d.digits[d.count] = shown[at]\n            d.count += 1\n            at += 1\n        n.dot = true\n    n.digits = d\n    n.first = 0\n    n.point = d.point\n    n.last = (i64)d.count\n    # `inf`, `nan` and an exponent follow the digits as they are\n    add_rest(n, shown[at..<length])\n\n## `e`, `f`, `g` (and the upper ones) of `value` with `precision`, as CPython's\n## PyOS_double_to_string and format_float_short write them: `-` for a negative value,\n## `inf` and `nan` for the specials.\nfunc short(n: Number*, value: f64, kind: u8, precision: i64, alternate: bool, no_negative_zero: bool):\n    let upper = kind == 'E' or kind == 'F' or kind == 'G'\n    var code = kind + 32 if upper else kind\n    var add_dot = false\n    var p = precision\n    if code == 0:\n        # a precision without a type: `g`, a point always kept (CPython's 'r' with one)\n        code = 'g'\n        add_dot = true\n    var negative = value < 0.0 or (value == 0.0 and (value.bits() >> 63) != 0)\n    if value != value or infinite(value):\n        n.negative = negative and value == value\n        n.first = n.point\n        add_rest(n, \"nan\".bytes if value != value else \"inf\".bytes)\n        return\n    var mode: u8 = 2\n    if code == 'e':\n        p += 1\n    elif code == 'f':\n        mode = 3\n    elif p == 0:\n        p = 1\n    let d = digits_of(value, mode, p)\n    if no_negative_zero and (d.count == 0 or (d.count == 1 and d.digits[0] == '0')):\n        negative = false\n    var point = d.point\n    var end = (i64)d.count\n    var use_exponent = false\n    if code == 'e':\n        use_exponent = true\n        end = p\n    elif code == 'f':\n        end = point + p\n    else:\n        if point <= -4 or point > (p - 1 if add_dot else p):\n            use_exponent = true\n        if alternate:\n            end = p\n    var exponent: i64 = 0\n    if use_exponent:\n        exponent = point - 1\n        point = 1\n    let start = point - 1 if point <= 0 else 0\n    if not use_exponent and add_dot:\n        end = end if end > point else point + 1\n    else:\n        end = end if end > point else point\n    n.negative = negative\n    n.digits = d\n    n.first = start\n    n.point = point\n    n.last = end\n    n.dot = point < end or alternate\n    if use_exponent:\n        add_rest(n, \"e\".bytes)\n        add_rest(n, \"-\".bytes if exponent < 0 else \"+\".bytes)\n        let magnitude = (u64)(-exponent if exponent < 0 else exponent)\n        let e = integer_digits(magnitude, 10)\n        if magnitude < 10:\n            add_rest(n, \"0\".bytes)\n        add_rest(n, e.digits[..<e.count])\n\n## Whether `x` is an infinity (a NaN is told apart by `x != x`).\nfunc infinite(x: f64) -> bool:\n    return x == x and ((x.bits() >> 52) & 0x7FF) == 0x7FF\n\n# mark: Text ===================================================================================\n\n## A text field `{value:spec}`, `shown` being its display, laid out by `specification`: precision keeps that many scalars, and the width pads it (CPython's\n## format_string_internal).\npub func lay_text(sink: Sink, shown: str, specification: str) -> bool:\n    let spec = settled(specification, false)\n    var view = shown.bytes\n    var n = scalar_count(view)\n    if spec.precision >= 0 and n > spec.precision:\n        view = scalar_prefix(view, spec.precision)\n        n = spec.precision\n    let (before, after) = padding(n, spec.width, spec.align)\n    return repeat(sink, spec.fill, before) and put(sink, view) and repeat(sink, spec.fill, after)\n\n## The first `n` scalars of `bytes`, viewing them.\nfunc scalar_prefix(bytes: const u8[], n: i64) -> const u8[]:\n    var seen: i64 = 0\n    var i: usize = 0\n    while i < bytes.length:\n        if (bytes[i] & 0xC0) != 0x80:\n            if seen == n:\n                return bytes[..<i]\n            seen += 1\n        i += 1\n    return bytes\n", 30689};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_6text_6 = {"#==============================================================================================\n#\n#   core - The compiler's runtime support\n#\n#   DESCRIPTION:\n#       The runtime the compiler emits calls to: startup and thread identity, the `format` and\n#       f-string buffer, integer and boolean formatting, hashing, and the checked, saturating\n#       and converting integer arithmetic.\n#\n#==============================================================================================\n\nfrom windows_abi import WideCharToMultiByte\nimport c\nimport float_text\nimport platform\nimport memory\nimport strings\nextern func set_binary_mode as \"_setmode\"(descriptor: i32, mode: i32) -> i32\nextern func GetCurrentThreadId() -> u32\nvar initial_thread: u32\n\n## Whether the caller is the process's initial thread.\npub func on_initial_thread() -> bool:\n    if platform.windows:\n        return initial_thread != 0 and GetCurrentThreadId() == initial_thread\n    return false\n\n## Standard streams carry language bytes, including LF, without CRT text translation.\npub func process_start():\n    if platform.windows:\n        initial_thread = GetCurrentThreadId()\n        _ = set_binary_mode(0, 32768)\n        _ = set_binary_mode(1, 32768)\n        _ = set_binary_mode(2, 32768)\n\nextern func posix_write as \"write\"(descriptor: i32, buffer: const void*, count: usize) -> isize\nextern func windows_write as \"_write\"(descriptor: i32, buffer: const void*, count: u32) -> i32\n\nfunc write(descriptor: i32, buffer: const void*, count: usize) -> isize:\n    if platform.windows:\n        return (isize)windows_write(descriptor, buffer, (u32)(count if count < 2147483647 else 2147483647))\n    return posix_write(descriptor, buffer, count)\n\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func malloc(size: usize) -> void*\?\nextern func realloc(block: void*\?, size: usize) -> void*\?\nextern func c_free as \"free\"(block: void*\?)\nextern func memcpy(target: void*, source: const void*, count: usize) -> void*\nextern func memmove(target: void*, source: const void*, count: usize) -> void*\nextern func memcmp(a: const void*, b: const void*, count: usize) -> i32\nextern func strlen(text: c.str) -> usize\n\n## Stop the program with its reason on stderr (\302\2478.7).\npub func trap(message: c.str) -> never:\n    begin_trap()\n    write_diagnostic(\"trap: \".bytes)\n    write_diagnostic(((str)message).bytes)\n    write_diagnostic(\"\\n\".bytes)\n    finish_trap()\n\n## `trap: file:line:column: message`: a trap naming the statement it stopped at (\302\24711.5).\npub func trap_at(position: c.str, message: c.str) -> never:\n    diagnostic_location(position)\n    write_diagnostic(((str)message).bytes)\n    write_diagnostic(\"\\n\".bytes)\n    finish_trap()\n\n## Positioned diagnostic with NUL-terminated C strings. Base assertions use\n## trap_detail_at so their message spans retain their explicit lengths.\npub func trap_two_at(position: c.str, message: c.str, detail: c.str) -> never:\n    diagnostic_location(position)\n    write_diagnostic(((str)message).bytes)\n    write_diagnostic(\": \".bytes)\n    write_diagnostic(((str)detail).bytes)\n    write_diagnostic(\"\\n\".bytes)\n    finish_trap()\n\n## Unpositioned diagnostic with NUL-terminated C strings.\npub func trap_two(message: c.str, detail: c.str) -> never:\n    begin_trap()\n    write_diagnostic(\"trap: \".bytes)\n    write_diagnostic(((str)message).bytes)\n    write_diagnostic(\": \".bytes)\n    write_diagnostic(((str)detail).bytes)\n    write_diagnostic(\"\\n\".bytes)\n    finish_trap()\n\n## Fatal diagnostic for a Base string. Its explicit byte length permits slices,\n## empty values and embedded NUL; no byte beyond the view is read.\npub func trap_text_at(position: c.str, message: str) -> never:\n    diagnostic_location(position)\n    write_diagnostic(message.bytes)\n    write_diagnostic(\"\\n\".bytes)\n    finish_trap()\n\n## `trap(f\"...\")` streams its message (`stream_put`), so a message longer than a format\n## buffer is whole: the location first, then the message to descriptor 2, then `trap_end`.\npub func trap_begin_at(position: c.str):\n    diagnostic_location(position)\n\n## The end of a streamed trap message, whose newline the stream wrote: the report, and\n## the exit.\npub func trap_end() -> never:\n    finish_trap()\n\n## Assertion prefix plus a Base string detail, preserving the detail's length.\npub func trap_detail_at(position: c.str, message: c.str, detail: str) -> never:\n    diagnostic_location(position)\n    let prefix = (str)message\n    write_diagnostic(prefix.bytes)\n    write_diagnostic(\": \".bytes)\n    write_diagnostic(detail.bytes)\n    write_diagnostic(\"\\n\".bytes)\n    finish_trap()\n\n## A trap at a position given as Base text, none when it is empty: how the value\n## language's runtime and its interpreter stop.\npub func trap_located(position: str, message: str) -> never:\n    begin_trap()\n    write_diagnostic(\"trap: \".bytes)\n    if position.length > 0:\n        write_diagnostic(position.bytes)\n        write_diagnostic(\": \".bytes)\n    write_diagnostic(message.bytes)\n    write_diagnostic(\"\\n\".bytes)\n    finish_trap()\n\n## `trap: file:line:column: `, or `trap: ` when the position is empty (a C build's code\n## before its first statement).\nfunc diagnostic_location(position: c.str):\n    begin_trap()\n    write_diagnostic(\"trap: \".bytes)\n    let location = (str)position\n    if location.length > 0:\n        write_diagnostic(location.bytes)\n        write_diagnostic(\": \".bytes)\n\n## Panic reporting cannot raise another language error. The diagnostic goes to\n## stderr and, when crash reports are on, to the report as well.\nfunc write_diagnostic(data: const u8[]):\n    write_all(2, data)\n    if crash_file >= 0:\n        write_all(crash_file, data)\n\n## Retry interruptions and short writes; stop on a terminal write failure or lack of progress.\nfunc write_all(descriptor: i32, data: const u8[]):\n    var written: usize = 0\n    while written < data.length:\n        let remaining = data.length - written\n        let count = remaining if remaining < 1073741824 else 1073741824\n        let result = write(descriptor, data[written..].data, count)\n        if result < 0 and c.errno() == c.interrupted:\n            continue\n        if result <= 0:\n            return\n        written += (usize)result\n\n# mark: Crash reports ==========================================================================\n\nextern func posix_open as \"open\"(path: c.str, flags: i32, ...) -> i32\nextern func windows_open as \"_open\"(path: c.str, flags: i32, ...) -> i32\nextern func posix_close as \"close\"(descriptor: i32) -> i32\nextern func windows_close as \"_close\"(descriptor: i32) -> i32\nextern func backtrace(frames: void**, size: i32) -> i32\nextern func backtrace_symbols_fd(frames: const void**, size: i32, descriptor: i32)\nextern func RtlCaptureStackBackTrace(skip: u32, count: u32, frames: void**, hash: u32*\?) -> u16\nextern func GetModuleHandleExA(flags: u32, address: const void*, module: void**) -> i32\nextern func GetModuleFileNameA(module: void*, name: u8*, size: u32) -> u32\nextern func c_quick_exit as \"_exit\"(code: i32) -> never\nextern func dladdr(address: const void*, info: DlInfo*) -> i32\nextern func getcontext(context: void*) -> i32\nextern func RtlLookupFunctionEntry(pc: u64, image_base: u64*, history: void*\?) -> void*\?\nextern func RtlVirtualUnwind(kind: u32, image_base: u64, pc: u64, entry: void*, context: void*, handler_data: void**, establisher: u64*, pointers: void*\?) -> void*\?\n\n## `Dl_info`: the module and nearest symbol `dladdr` finds for an address.\nextern struct DlInfo:\n    file: c.str\?\n    base: usize\n    symbol: c.str\?\n    start: usize\n\n## Where a crash report goes, NUL-terminated, and what it starts with; empty when\n## reports are off. `std.crash` fills them; a trap or fatal signal writes them.\nvar crash_path: u8[1024]\nvar crash_header: u8[1024]\nvar crash_header_length: usize = 0\nvar crash_file: i32 = -1\n## Set while a report walks frame pointers: a fault then is the walk's own, at a\n## frame it could not read, and the report ends there.\nvar crash_walking: bool = false\n## Where `getcontext` puts the registers of a trap on Linux: more than any\n## `ucontext_t` needs, as words so it is aligned.\nvar crash_registers: usize[1024]\n## A Windows fault's CONTEXT, copied so it can be unwound in place: 1232 bytes\n## that must start on 16, with room to move them there.\nvar crash_windows_context: u8[1280]\n## The interrupted context of the fatal signal being reported, when there is one.\nvar crash_context: const void*\? = none\n## Whether this process has written a report: a later trap, one in a crash handler,\n## is added to it rather than replacing it.\nvar crash_reported: bool = false\n## What runs once a report is written, before the process ends (`set_crash_handler`).\nvar crash_handler: (func(i32) -> unit)\? = none\n\n## Turn crash reports on: a trap from now on also writes `header` and the trap\n## to the file at `path` (created then, replaced if present), with a native\n## stack where the platform gives one. Paths or headers too long are cut.\npub func set_crash_report(path: str, header: str):\n    let length = path.length if path.length < crash_path.length - 1 else crash_path.length - 1\n    for index in 0..<length:\n        crash_path[index] = path.bytes[index]\n    crash_path[length] = 0\n    let header_length = header.length if header.length < crash_header.length else crash_header.length\n    for index in 0..<header_length:\n        crash_header[index] = header.bytes[index]\n    crash_header_length = header_length\n\n## Whether crash reports are on.\npub func crash_reports_enabled() -> bool:\n    return crash_path[0] != 0\n\n## Run `handler` once a crash report is written, before the process ends: with 0 after\n## a trap, on the thread that trapped, where the program may still do ordinary work;\n## with the signal's number after a fatal signal, inside the signal handler, where only\n## async-signal-safe calls are allowed. The process ends when the handler returns. A\n## trap inside the handler is added to the report and runs the handler again.\npub func set_crash_handler(handler: (func(i32) -> unit)\?):\n    crash_handler = handler\n\n## Open the report, if reports are on and it is not open yet, and write its header.\n## The start of every trap and fatal signal: the running test, if any, named as failed\n## (\302\24716.5), then the crash report opened.\nfunc begin_trap():\n    if test_running.length > 0:\n        write_all(1, \"FAIL  \".bytes)\n        write_all(1, test_running.bytes)\n        write_all(1, \"\\n\".bytes)\n    begin_crash_report()\n\n## The end of a trap or fatal signal inside a test: the test counted as failed and the\n## tally of the tests run so far printed, since the run ends here (\302\24716.5).\nfunc end_trapped_test():\n    if test_running.length == 0:\n        return\n    test_running = \"\"\n    tests_failed += 1\n    _ = test_summary()\n\nfunc begin_crash_report():\n    if crash_file >= 0 or crash_path[0] == 0:\n        return\n    let path = (c.str)&crash_path[0]\n    # write, create, and truncate the first time; append after\n    if platform.windows:\n        crash_file = windows_open(path, 1 | 256 | (8 if crash_reported else 512) | 32768, 420)\n    elif platform.macos:\n        crash_file = posix_open(path, 1 | 512 | (8 if crash_reported else 1024), 420)\n    else:\n        crash_file = posix_open(path, 1 | 64 | (1024 if crash_reported else 512), 420)\n    if crash_file < 0:\n        return\n    if crash_reported:\n        write_all(crash_file, \"\\n(and while the program handled that crash)\\n\".bytes)\n    else:\n        write_all(crash_file, crash_header[..<crash_header_length])\n    crash_reported = true\n\n## Finish a trap: the stack into the report, close it, the crash handler, and exit.\nfunc finish_trap() -> never:\n    end_trapped_test()\n    finish_crash_report(trap_registers())\n    if let handler = crash_handler:\n        handler(0)\n    c_exit(1)\n\n## Where a fault left the program: its instruction, its frame pointer and, on\n## arm64, its link register; zeros where they are not known.\npub struct FaultRegisters:\n    ## The faulting instruction.\n    pub var pc: usize = 0\n    ## The frame pointer at the fault: the start of the frame chain.\n    pub var fp: usize = 0\n    ## The link register (arm64): the caller of a function that made no frame.\n    pub var lr: usize = 0\n\n## Write the stack into the report and close it: walked from `at` when it has a\n## frame pointer, else as the platform's own backtrace gives it.\nfunc finish_crash_report(at: FaultRegisters):\n    if crash_file < 0:\n        return\n    write_all(crash_file, \"\\nstack:\\n\".bytes)\n    var unwound = false\n    if platform.windows:\n        if let context = crash_context:\n            write_windows_unwound(crash_file, context)\n            unwound = true\n    if unwound:\n        close_crash_report()\n        return\n    if at.fp != 0:\n        write_walked_stack(crash_file, at)\n    elif platform.posix:\n        # Pointer-sized slots: the addresses backtrace fills in.\n        var frames: usize[64]\n        let depth = backtrace((void**)&frames[0], 64)\n        if depth > 0:\n            backtrace_symbols_fd((const void**)&frames[0], depth, crash_file)\n    elif platform.windows:\n        write_windows_stack(crash_file)\n    close_crash_report()\n\nfunc close_crash_report():\n    if platform.windows:\n        _ = windows_close(crash_file)\n    else:\n        _ = posix_close(crash_file)\n    crash_file = -1\n\n## A trap's own registers on Linux, where `backtrace` needs unwind tables the\n## native backend leaves out of release builds; zeros elsewhere (macOS's\n## backtrace follows frame pointers, Windows' the SEH tables).\nfunc trap_registers() -> FaultRegisters:\n    if platform.linux:\n        if getcontext((void*)&crash_registers[0]) != 0:\n            return FaultRegisters()\n        return context_registers((const void*)&crash_registers[0])\n    else:\n        return FaultRegisters()\n\n# mark: Walking frame pointers =================================================================\n\n## The registers in a signal's `ucontext_t` (or `getcontext`'s), or in a Windows\n## `CONTEXT` record. Offsets are each platform's C layout.\nfunc context_registers(context: const void*) -> FaultRegisters:\n    let base = (const u8*)context\n    if platform.windows:\n        return FaultRegisters(pc = word_at(base, 248), fp = word_at(base, 160))\n    elif platform.linux and platform.x86_64:\n        # uc_mcontext.gregs at 40: RIP is register 16, RBP 10.\n        return FaultRegisters(pc = word_at(base, 168), fp = word_at(base, 120))\n    elif platform.macos:\n        # uc_mcontext is a pointer at 48, to the exception state (16 bytes) and the thread state.\n        let machine = (const u8*)(const void*)word_at(base, 48)\n        if platform.arm64:\n            return FaultRegisters(pc = word_at(machine, 272), fp = word_at(machine, 248), lr = word_at(machine, 256))\n        else:\n            return FaultRegisters(pc = word_at(machine, 144), fp = word_at(machine, 64))\n    else:\n        return FaultRegisters()\n\nfunc word_at(base: const u8*, offset: usize) -> usize:\n    return ((const usize*)(const void*)(base + offset))[0]\n\n## Every frame from `at`: the faulting instruction, the link register on arm64\n## (a leaf keeps its caller there), then each saved return address up the\n## chain of frame records, which the native backend keeps in every function.\n## A record that does not climb the stack ends the walk; one that cannot be\n## read faults, and `report_fatal_signal_in` ends the report there.\nfunc write_walked_stack(file: i32, at: FaultRegisters):\n    var frames: usize[64] = ---\n    var depth: usize = 0\n    if at.pc != 0:\n        frames[0] = at.pc\n        depth = 1\n    # The link register is the caller only when the faulting function made no\n    # frame of its own; otherwise it is a stale return inside it. Marked so.\n    var link: usize = 64\n    if at.lr != 0 and at.lr != at.pc:\n        link = depth\n        frames[depth] = at.lr\n        depth += 1\n    var frame = at.fp\n    crash_walking = true\n    while depth < 64 and frame != 0 and frame % 8 == 0:\n        let record = (const usize*)(const void*)frame\n        let caller = record[1]\n        let next = record[0]\n        if caller == 0:\n            break\n        if depth == 0 or caller != frames[depth - 1]:\n            frames[depth] = caller\n            depth += 1\n        if next <= frame or next - frame > 16777216:\n            break\n        frame = next\n    crash_walking = false\n    for index in 0..<depth:\n        write_frame(file, index, frames[index], index == link)\n\n## Windows: unwind a copy of the fault's CONTEXT a frame at a time through the\n## SEH tables the native backend emits (its frame pointer sits below each\n## frame's locals, so there are no frame records to follow). A function with no\n## table entry is a leaf, whose return address is at the stack pointer.\nfunc write_windows_unwound(file: i32, context: const void*):\n    if platform.windows:\n        let start = (usize)(const void*)&crash_windows_context[0]\n        let copy = &crash_windows_context[(16 - start % 16) % 16]\n        _ = memcpy(copy, context, 1232)\n        var frames: usize[64] = ---\n        var depth: usize = 0\n        crash_walking = true\n        while depth < 64:\n            let pc = word_at(copy, 248)\n            let sp = word_at(copy, 152)\n            if pc == 0:\n                break\n            frames[depth] = pc\n            depth += 1\n            var base: u64 = 0\n            if let entry = RtlLookupFunctionEntry((u64)pc, &base, none):\n                var data: void* = ---\n                var establisher: u64 = 0\n                _ = RtlVirtualUnwind(0, base, (u64)pc, entry, (void*)copy, &data, &establisher, none)\n            else:\n                put_word(copy, 248, ((const usize*)(const void*)sp)[0])\n                put_word(copy, 152, sp + 8)\n            if word_at(copy, 152) <= sp:\n                break\n        crash_walking = false\n        for index in 0..<depth:\n            write_frame(file, index, frames[index], false)\n\nfunc put_word(base: u8*, offset: usize, value: usize):\n    ((usize*)(void*)(base + offset))[0] = value\n\n## One frame's line: its number, address, module and offset in it (for\n## addr2line or atos), and the nearest symbol where the platform names one.\nfunc write_frame(file: i32, index: usize, address: usize, link: bool):\n    var line: u8[640] = ---\n    var used: usize = 0\n    line[0] = '#'\n    used = put_decimal(line, 1, index)\n    line[used] = ' '\n    if link:\n        used = put_text(line, used + 1, \"lr\")\n        line[used] = ' '\n    used = put_hex(line, used + 1, address)\n    line[used] = ' '\n    used += 1\n    if platform.windows:\n        used = put_windows_module(line, used, address)\n    elif platform.posix:\n        var info: DlInfo = ---\n        info.file = none\n        info.symbol = none\n        if dladdr((const void*)address, &info) != 0:\n            if let file_name = info.file:\n                used = put_base_name(line, used, (str)file_name)\n            line[used] = '+'\n            used = put_hex(line, used + 1, address - info.base)\n            if let symbol = info.symbol:\n                line[used] = ' '\n                used = put_text(line, used + 1, (str)symbol)\n                line[used] = '+'\n                used = put_hex(line, used + 1, address - info.start)\n        else:\n            line[used] = '\?'\n            used += 1\n    line[used] = '\\n'\n    write_all(file, (const u8[])line[..<used + 1])\n\n## The module holding `address` on Windows, as `name+0xoffset`, into `line` at `used`.\nfunc put_windows_module(line: u8[], used: usize, address: usize) -> usize:\n    if platform.windows:\n        var module: void* = ---\n        var name: u8[260] = ---\n        # 4: from an address; 2: without changing the module's reference count\n        if GetModuleHandleExA(6, (const void*)address, (void**)&module) == 0:\n            line[used] = '\?'\n            return used + 1\n        let length = GetModuleFileNameA(module, &name[0], 260)\n        let at = put_base_name(line, used, (str)name[..<length])\n        line[at] = '+'\n        return put_hex(line, at + 1, address - (usize)module)\n    else:\n        return used\n\n## The last component of `path` into `line` at `used`, cut to fit.\nfunc put_base_name(line: u8[], used: usize, path: str) -> usize:\n    var start: usize = 0\n    for index in 0..<path.length:\n        if path.bytes[index] == '/' or path.bytes[index] == '\\\\':\n            start = index + 1\n    return put_text(line, used, (str)path.bytes[start..])\n\n## `text` into `line` at `used`, leaving room for what follows it.\nfunc put_text(line: u8[], used: usize, text: str) -> usize:\n    var at = used\n    for byte in text.bytes:\n        if at + 40 >= line.length:\n            break\n        line[at] = byte\n        at += 1\n    return at\n\n## `value` in decimal into `line` at `used`; the new length.\nfunc put_decimal(line: u8[], used: usize, value: usize) -> usize:\n    var digits: u8[24] = ---\n    var count: usize = 0\n    var rest = value\n    while true:\n        digits[count] = (u8)('0' + (u8)(rest % 10))\n        count += 1\n        rest = rest // 10\n        if rest == 0:\n            break\n    var at = used\n    while count > 0:\n        count -= 1\n        line[at] = digits[count]\n        at += 1\n    return at\n\n## The native stack on Windows, a frame a line as `module+0xoffset`, which a debugger or\n## addr2line resolves against the build. Nothing here allocates.\nfunc write_windows_stack(file: i32):\n    # One branch on the platform around everything, which the C backend folds away\n    # elsewhere: the Windows symbols then appear in no other platform's build.\n    if platform.windows:\n        write_all(file, \"(the reporter's frames and Windows' exception dispatch come first; the fault is the\\n first program frame after ntdll.dll. Offsets are from each module's load address;\\n add the image base, 0x140000000 by default for a 64-bit program, for addr2line.)\\n\".bytes)\n        var frames: usize[64]\n        let depth = (usize)RtlCaptureStackBackTrace(0, 64, (void**)&frames[0], none)\n        for index in 0..<depth:\n            let address = frames[index]\n            var line: u8[400] = ---\n            var used: usize = 0\n            var module: void* = ---\n            var base: usize = 0\n            var name: u8[260] = ---\n            var length: u32 = 0\n            # 4: from an address; 2: without changing the module's reference count\n            if GetModuleHandleExA(6, (const void*)address, (void**)&module) != 0:\n                base = (usize)module\n                length = GetModuleFileNameA(module, &name[0], 260)\n            var start: u32 = 0\n            for at in 0..<length:\n                if name[at] == '\\\\' or name[at] == '/': start = at + 1\n            for at in start..<length:\n                if used < 300:\n                    line[used] = name[at]\n                    used += 1\n            if length == 0:\n                line[used] = '\?'\n                used += 1\n            line[used] = '+'\n            used += 1\n            used = put_hex(line, used, address - base)\n            line[used] = '\\n'\n            used += 1\n            write_all(file, (const u8[])line[..<used])\n\n## `value` as `0x` and lowercase hex digits into `line` at `used`; the new length.\nfunc put_hex(line: u8[], used: usize, value: usize) -> usize:\n    var at = used\n    line[at] = '0'\n    line[at + 1] = 'x'\n    at += 2\n    var shift: usize = 60\n    var started = false\n    while true:\n        let digit = (value >> shift) & 15\n        if digit != 0 or started or shift == 0:\n            started = true\n            line[at] = \"0123456789abcdef\".bytes[digit]\n            at += 1\n        if shift == 0:\n            break\n        shift -= 4\n    return at\n\n## A fatal signal: report it as a trap would, then end with the signal's exit\n## status. Only async-signal-safe calls are made from here on.\npub func report_fatal_signal(name: str, number: i32) -> never:\n    report_fatal_signal_in(name, number, none)\n\n## A fatal signal whose handler has the interrupted context (a POSIX\n## `ucontext_t`, or a Windows `CONTEXT`): the stack is walked from where the\n## fault happened rather than from the handler. A fault while the stack is\n## walked ends the report at the frame that could not be read.\npub func report_fatal_signal_in(name: str, number: i32, context: const void*\?) -> never:\n    if crash_walking:\n        crash_walking = false\n        if crash_file >= 0:\n            write_all(crash_file, \"(the walk stopped at a frame it could not read)\\n\".bytes)\n            close_crash_report()\n        c_quick_exit(128 + number)\n    begin_trap()\n    write_diagnostic(\"trap: fatal signal \".bytes)\n    write_diagnostic(name.bytes)\n    write_diagnostic(\"\\n\".bytes)\n    end_trapped_test()\n    crash_context = context\n    if let interrupted = context:\n        finish_crash_report(context_registers(interrupted))\n    else:\n        finish_crash_report(FaultRegisters())\n    if let handler = crash_handler:\n        handler(number)\n    c_quick_exit(128 + number)\n\n## The buffer `format` and f\"...\" fill: the bytes, their capacity, and the count used.\npub struct FormatBuffer:\n    ## The buffer's bytes.\n    pub var data: u8*\n    ## The buffer's capacity in bytes.\n    pub var capacity: usize\n    ## The number of bytes used.\n    pub var used: usize\n    ## What text past the capacity does: `format_fixed`, it is cut; `format_grows`, the\n    ## text moves to the heap and goes on there; `format_grown`, it is on the heap.\n    pub var growth: usize = 0\n\n## A buffer of the caller's, as `format` fills: text past its capacity is cut.\npub let format_fixed: usize = 0\n## A buffer the compiler made for a formatted argument (\302\2475.5): it starts on the stack, moves\n## to the heap when the text outgrows it, and is released once the call it feeds returns.\npub let format_grows: usize = 1\n## A growing buffer whose text is on the heap, which `format_release` frees.\npub let format_grown: usize = 2\n\n## Append `count` bytes; 1 when they do not fit: the bytes that fit are kept, and the buffer\n## is then over capacity, which `format` reports and `format_finish` marks. A growing\n## buffer makes room instead, and fails only when the heap has none.\npub func format_put(b: FormatBuffer*, text: const void*\?, count: usize) -> i32:\n    if b.used > b.capacity:\n        return 1\n    if count > b.capacity - b.used and not (b.growth != format_fixed and format_grow(b, b.used + count)):\n        if let source = text:\n            if b.capacity > b.used:\n                _ = memcpy(&b.data[b.used], source, b.capacity - b.used)\n        b.used = b.capacity +% 1\n        return 1\n    if let source = text:\n        if count > 0:\n            _ = memcpy(&b.data[b.used], source, count)\n    b.used += count\n    return 0\n\n## Make room in a growing buffer for `need` bytes and the NUL `format_finish` puts after\n## them, at least doubling it; false when the heap has no room.\nfunc format_grow(b: FormatBuffer*, need: usize) -> bool:\n    var size = b.capacity * 2\n    if size <= need:\n        size = need + 1\n    if b.growth == format_grown:\n        let moved = realloc(b.data, size) else return false\n        b.data = (u8*)moved\n    else:\n        let fresh = malloc(size) else return false\n        _ = memcpy(fresh, b.data, b.used)\n        b.data = (u8*)fresh\n        b.growth = format_grown\n    b.capacity = size\n    return true\n\n## Free what a growing buffer took from the heap; its text is gone with it.\npub func format_release(b: FormatBuffer*):\n    if b.growth == format_grown:\n        c_free(b.data)\n        b.growth = format_grows\n        b.capacity = 0\n        b.used = 0\n\n## Append the decimal `value` to `b`; the bytes written.\npub func format_u64(b: FormatBuffer*, value: u64) -> i32:\n    var digits: u8[24] = ---\n    var n: usize = 0\n    var v = value\n    if v == 0:\n        digits[23] = 48\n        n = 1\n    while v != 0:\n        n += 1\n        digits[24 - n] = (u8)(48 + v % 10)\n        v = v // 10\n    return format_put(b, &digits[24 - n], n)\n\n## Append the decimal `value` to `b`; the bytes written.\npub func format_i64(b: FormatBuffer*, value: i64) -> i32:\n    if value < 0:\n        let minus = \"-\"\n        if format_put(b, minus.bytes.data, 1) != 0:\n            return 1\n        return format_u64(b, 0 -% (u64)value)\n    return format_u64(b, (u64)value)\n\n## A float field (base.md \302\24714): the shortest decimal that reads back as `value`, a `.0`\n## after digits with no point (float_text.display_f64); both backends call this.\npub func format_f64(b: FormatBuffer*, value: f64) -> i32:\n    var text: u8[40] = ---\n    let n = float_text.display_f64(value, text[0..])\n    return format_put(b, &text[0], n)\n\n## format_f64 for an f32 (or an f16, widened): the f32's own shortest digits.\npub func format_f32(b: FormatBuffer*, value: f32) -> i32:\n    var text: u8[40] = ---\n    let n = float_text.display_f32(value, text[0..])\n    return format_put(b, &text[0], n)\n\n## Append `true` or `false` to `b`; the bytes written.\npub func format_bool(b: FormatBuffer*, value: bool) -> i32:\n    let word = \"true\" if value else \"false\"\n    return format_put(b, word.bytes.data, word.length)\n\n## A `char` displays as itself, in UTF-8 (\302\24714.4).\npub func format_char(b: FormatBuffer*, value: char) -> i32:\n    let cp = u32(value)\n    var out: u8[4]\n    var n: usize = 0\n    if cp < 0x80:\n        out[0] = u8(cp)\n        n = 1\n    elif cp < 0x800:\n        out[0] = u8(0xC0 | (cp >> 6))\n        out[1] = u8(0x80 | (cp & 0x3F))\n        n = 2\n    elif cp < 0x10000:\n        out[0] = u8(0xE0 | (cp >> 12))\n        out[1] = u8(0x80 | ((cp >> 6) & 0x3F))\n        out[2] = u8(0x80 | (cp & 0x3F))\n        n = 3\n    else:\n        out[0] = u8(0xF0 | (cp >> 18))\n        out[1] = u8(0x80 | ((cp >> 12) & 0x3F))\n        out[2] = u8(0x80 | ((cp >> 6) & 0x3F))\n        out[3] = u8(0x80 | (cp & 0x3F))\n        n = 4\n    return format_put(b, (const void*)&out, n)\n\n## The text so far, NUL-terminated when there is room. Text over capacity is cut at a\n## character boundary and ends in `...`, so a long f\"...\" is never silently empty.\npub func format_finish(b: FormatBuffer*) -> str:\n    if b.used < b.capacity:\n        b.data[b.used] = 0\n    if b.used > b.capacity:\n        if b.capacity < 3:\n            return \"\"\n        var end = b.capacity - 3\n        while end > 0 and (b.data[end] & 0xC0) == 0x80:\n            end -= 1\n        b.data[end] = 46\n        b.data[end + 1] = 46\n        b.data[end + 2] = 46\n        return (str)u8[](b.data, end + 3)\n    return (str)u8[](b.data, b.used)\n\n## The startup shim's pieces: the argument vector as `str[]` (checked) or `c.str[]`.\npub func arguments(count: i32, vector: c.str*) -> str[]:\n    let raw = raw_arguments(count, vector)\n    let n = raw.length\n    let block = malloc((n if n > 0 else 1) * memory.size_of(str)) else trap(\"memory.exhausted\")\n    let items = (str*)block\n    var i: usize = 0\n    while i < n:\n        let text = (str)raw[i]\n        if not utf8_ok(text.bytes.data, text.length):\n            trap(\"invalid_utf8\")\n        items[i] = text\n        i += 1\n    return str[](items, n)\n\n## The process's arguments as a span of C strings.\npub func raw_arguments(count: i32, vector: c.str*) -> c.str[]:\n    if platform.windows:\n        return windows_arguments()\n    return c.str[](vector, (usize)count)\n\nextern func GetCommandLineW() -> u16*\nextern func CommandLineToArgvW(command: u16*, count: i32*) -> u16**\?\nextern func LocalFree(block: void*) -> void*\?\nextern func atexit(callback: func() -> unit) -> i32\nvar windows_argument_vector: c.str[]\n\nfunc free_windows_arguments():\n    for text in windows_argument_vector:\n        c_free((void*)text)\n    c_free((void*)windows_argument_vector.data)\n\n## The wide command line preserves names the Windows ANSI code page cannot encode.\nfunc windows_arguments() -> c.str[]:\n    if platform.windows:\n        if windows_argument_vector.length > 0:\n            return windows_argument_vector\n        var count: i32 = 0\n        let wide = CommandLineToArgvW(GetCommandLineW(), &count) else trap(\"could not read the Windows command line\")\n        defer _ = LocalFree((void*)wide)\n        let block = malloc((usize)count * memory.size_of(c.str)) else trap(\"memory.exhausted\")\n        let items = (c.str*)block\n        for index in 0..<(usize)count:\n            let size = WideCharToMultiByte(65001, 128, wide[index], -1, none, 0, none, none)\n            if size <= 0: trap(\"the command line contains invalid UTF-16\")\n            let text = malloc((usize)size) else trap(\"memory.exhausted\")\n            if WideCharToMultiByte(65001, 128, wide[index], -1, (u8*)text, size, none, none) != size:\n                trap(\"could not encode the command line as UTF-8\")\n            items[index] = (c.str)text\n        windows_argument_vector = c.str[](items, (usize)count)\n        if atexit(free_windows_arguments) != 0:\n            trap(\"could not register command line cleanup\")\n        return windows_argument_vector\n    return c.str[]((c.str*)0, 0)\n\n## The error of the fallible call that failed last on this thread, as the native backends\n## pass it: a failing function leaves its error here and returns its flag set, and `try`\n## passes the flag up with the error left where it is (\302\24711.2's representation).\npub local var failure: Error\n\n# mark: Messages in flight ==================================================================\n#\n# `error(code, message)` copies a message that is not a literal here, so the message stays\n# readable after the cleanup the failure runs has freed what it was made from (\302\24711.3). The\n# room is a stack: a handler that finishes gives back its error's message and everything\n# raised after it (`message_handled`), and a failure that leaves a handler takes the place of\n# the handled message (`message_raised`'s `replaces`). A message that does not fit above the\n# top starts the room again at its beginning, so the room never grows and never allocates.\n\n## The room for the messages of the errors in flight on this thread, and its first free byte.\nlocal var raised_room: u8[16384]\nlocal var raised_top: usize = 0\n\n## The longest message the room keeps: a longer one is cut at a character and ends in `\342\200\246`.\nlet raised_most: usize = 4096\n\n## Where `text` starts in this thread's room, or `none` when it lies elsewhere.\nfunc in_room(text: str) -> usize\?:\n    let base = (usize)&raised_room[0]\n    let at = (usize)text.bytes.data\n    if at < base or at > base + raised_room.length or text.length > base + raised_room.length - at:\n        return none\n    return at - base\n\n## The message of an error being raised, copied into this thread's room: a copy that lives\n## until the handler that catches the error finishes (\302\24711.3). `replaces` is the message of the\n## error a handler is passing on a failure from, or empty: its place is reused when it is in\n## the room, the new message copied before the old one is given up, so a new message made\n## from the old one reads it whole.\npub func message_raised(message: str, replaces: str) -> str:\n    var length = message.length\n    var cut = false\n    if length > raised_most:\n        length = raised_most - 3\n        while length > 0 and (message.bytes[length] & 0xC0) == 0x80:\n            length -= 1\n        cut = true\n    let total = length + (3 if cut else 0)\n    var at = raised_top\n    if let start = in_room(replaces):\n        if start <= raised_top and start + total <= raised_room.length:\n            at = start\n    if at + total > raised_room.length:\n        at = 0\n    let room = u8[](&raised_room[at], total)\n    if length > 0:\n        _ = memmove(room.data, message.bytes.data, length)\n    if cut:\n        room[length] = 0xE2\n        room[length + 1] = 0x80\n        room[length + 2] = 0xA6\n    raised_top = at + total\n    return (str)room\n\n## A handler finished with the error whose message is `message`: its place in the room and\n## everything raised after it are free again. A message elsewhere, a literal, frees nothing.\npub func message_handled(message: str):\n    if let start = in_room(message):\n        if start < raised_top:\n            raised_top = start\n\n## A failed `main`: its error on stderr, `error: message (code n)`, exit status 1. The code\n## shown is the package's own number, `n` of `ErrorCode.package(n)`; the package identity\n## above it (\302\24711.3) tells packages apart and means nothing to a reader.\npub func main_failed(code: i32, message: str) -> i32:\n    var bytes: u8[1024] = ---\n    let line = strings.format(bytes, f\"error: {message} (code {(u32)code & 0xFFFF})\\n\") catch:\n        return 1\n    _ = write(2, line.bytes.data, line.length)\n    return 1\n\n## The failure of a test whose `assert` was false (\302\24716.5).\npub let assert_failed: ErrorCode = ErrorCode.package(60)\n\n## Where the `assert` that failed the running test stands, empty while none has, and the\n## room its message is written in, which the failure views until the test is reported.\nvar assert_position: c.str = \"\"\nvar assert_message: u8[1024]\n\n## A false `assert` in a test's own body (\302\24716.5): the test fails with `text`, `assert failed:`\n## and the condition, and `detail` after it when there is one, and is reported at `position`,\n## the assert's.\npub func test_assert(position: c.str, text: c.str, detail: str, detailed: bool) -> !:\n    assert_position = position\n    let condition = (str)text\n    let message = strings.format(assert_message, f\"{condition}: {detail}\" if detailed else f\"{condition}\") catch:\n        recover condition\n    error(assert_failed, message)\n\n## The test the runner is running, empty between tests, and the tally so far: a trap or\n## fatal signal in a test names it as failed and prints the tally before the run ends.\nvar test_running: str = \"\"\nvar tests_passed: i32 = 0\nvar tests_failed: i32 = 0\n\n## The runner starts the test named `name`.\npub func test_start(name: str):\n    test_running = name\n\n## The test runner's report line for the test that ran: `ok`, or `FAIL` with the place and\n## the message on the next line, the place being the failed `assert`'s or else the test's\n## own, `at` (\302\24716.5).\npub func test_report(failed: bool, at: c.str, message: str):\n    let place = (str)(assert_position if ((str)assert_position).length > 0 else at)\n    assert_position = \"\"\n    test_result(failed, place, message)\n\n## Report the test that ran and count it: `ok    name`, or `FAIL  name` and the indented\n## `place: message`. Luce's runners report through here too, so every runner prints alike.\npub func test_result(failed: bool, place: str, message: str):\n    let name = test_running\n    test_running = \"\"\n    if failed:\n        tests_failed += 1\n    else:\n        tests_passed += 1\n    if not failed:\n        write_all(1, \"ok    \".bytes)\n        write_all(1, name.bytes)\n        write_all(1, \"\\n\".bytes)\n        return\n    write_all(1, \"FAIL  \".bytes)\n    write_all(1, name.bytes)\n    write_all(1, \"\\n      \".bytes)\n    write_all(1, place.bytes)\n    write_all(1, \": \".bytes)\n    write_all(1, message.bytes)\n    write_all(1, \"\\n\".bytes)\n\n## Print the tally of the tests run, the failures counted when there are any; the process\n## exit status. Formats without the heap or `strings`, since a trap may print it.\npub func test_summary() -> i32:\n    var line: u8[128] = ---\n    var used = put_decimal(line, 0, (usize)tests_passed)\n    used = put_text(line, used, \" passed\\n\")\n    if tests_failed > 0:\n        used = put_decimal(line, used, (usize)tests_failed)\n        used = put_text(line, used, \" failed\\n\")\n    write_all(1, line[..<used])\n    return 0 if tests_failed == 0 else 1\n\n## `print`: the text and a newline on stdout; `answer()` programs print their number.\npub func print_str(text: str):\n    _ = write(1, text.bytes.data, text.length)\n    let newline = \"\\n\"\n    _ = write(1, newline.bytes.data, 1)\n\n# mark: Streamed text =========================================================================\n\n## `print(f\"...\")` and `trap(f\"...\")` fill a format buffer and write it out to `descriptor`\n## (1, standard output; 2, the diagnostic) as it fills, so no buffer bounds the text and a\n## short line is one write. Append `count` bytes at `data` and leave at least half the\n## buffer free, which is room for the fields the compiler displays into it between pieces;\n## a field that displays itself longer than that is cut, as `format_finish` marks.\npub func stream_put(b: FormatBuffer*, data: const u8*, count: usize, descriptor: i32):\n    if b.used > b.capacity or count > b.capacity - b.used:\n        stream_flush(b, descriptor)\n    if count >= b.capacity:\n        stream_write(descriptor, u8[]((u8*)data, count))\n        return\n    _ = format_put(b, data, count)\n    if b.used > b.capacity // 2:\n        stream_flush(b, descriptor)\n\n## Write out the buffer's text and empty it: the end of a streamed text.\npub func stream_flush(b: FormatBuffer*, descriptor: i32):\n    if b.used > 0:\n        stream_write(descriptor, format_finish(b).bytes)\n    b.used = 0\n\nfunc stream_write(descriptor: i32, data: const u8[]):\n    if descriptor == 2:\n        write_diagnostic(data)\n    else:\n        write_all(descriptor, data)\n\n## Print `value` followed by a newline.\npub func print_i64(value: i64):\n    var bytes: u8[32] = ---\n    let all: u8[] = bytes\n    var b = FormatBuffer(data = all.data, capacity = 32, used = 0)\n    _ = format_i64(&b, value)\n    _ = write(1, all.data, b.used)\n    let newline = \"\\n\"\n    _ = write(1, newline.bytes.data, 1)\n\n## Ordering of text: bytewise, then by length (\302\2477.4).\npub func str_compare(a: str, b: str) -> i32:\n    let n = a.length if a.length < b.length else b.length\n    var order: i32 = 0\n    if n > 0:\n        order = memcmp(a.bytes.data, b.bytes.data, n)\n    if order != 0:\n        return -1 if order < 0 else 1\n    if a.length < b.length:\n        return -1\n    return 1 if a.length > b.length else 0\n\n## The scalar starting at byte `index` of `count` bytes of valid UTF-8, its width left in\n## `width`: what `for character in text` steps by (\302\2475.5).\npub func utf8_scalar(text: const u8*, count: usize, index: usize, width: usize*) -> char:\n    let byte = text[index]\n    var w: usize = 1\n    var cp: u32 = (u32)byte\n    if byte >= 240:\n        w = 4\n        cp = (u32)(byte & 7)\n    elif byte >= 224:\n        w = 3\n        cp = (u32)(byte & 15)\n    elif byte >= 192:\n        w = 2\n        cp = (u32)(byte & 31)\n    if index + w > count:\n        w = count - index\n    var k: usize = 1\n    while k < w:\n        cp = (cp << 6) | (u32)(text[index + k] & 63)\n        k += 1\n    *width = w\n    return char(cp)\n\n## Whether `count` bytes are well-formed UTF-8: no overlong forms, no surrogates, nothing past U+10FFFF.\npub func utf8_ok(text: const u8*\?, count: usize) -> bool:\n    let s = text else return count == 0\n    var i: usize = 0\n    while i < count:\n        # eight ASCII bytes at a time: source text is mostly ASCII\n        while i + 8 <= count:\n            var word: u64 = 0\n            _ = memcpy(&word, &s[i], 8)\n            if (word & 0x8080808080808080) != 0:\n                break\n            i += 8\n        if i >= count:\n            break\n        let byte = s[i]\n        var w: usize = 1\n        var cp: u32 = 0\n        if byte < 128:\n            cp = (u32)byte\n        elif (byte & 224) == 192:\n            w = 2\n            cp = (u32)(byte & 31)\n        elif (byte & 240) == 224:\n            w = 3\n            cp = (u32)(byte & 15)\n        elif (byte & 248) == 240:\n            w = 4\n            cp = (u32)(byte & 7)\n        else:\n            return false\n        if i + w > count:\n            return false\n        var k: usize = 1\n        while k < w:\n            let x = s[i + k]\n            if (x & 192) != 128:\n                return false\n            cp = (cp << 6) | (u32)(x & 63)\n            k += 1\n        if w == 2 and cp < 128:\n            return false\n        if w == 3 and cp < 2048:\n            return false\n        if w == 4 and cp < 65536:\n            return false\n        if cp >= 55296 and cp <= 57343:\n            return false\n        if cp > 1114111:\n            return false\n        i += w\n    return true\n\n## `hash`: a per-process seed and a multiplicative mixer (\302\2477.4).\nvar hash_seed_value: u64\nvar hash_seeded: bool\n\n## A per-process seed for the collection hashers.\n# mark: Hashing ===============================================================================\n\n## The process's per-run hash seed, chosen once from the address space.\npub func hash_seed() -> u64:\n    if not hash_seeded:\n        hash_seed_value = 11400714819323198485 ^ (u64)(usize)&hash_seed_value\n        hash_seeded = true\n    return hash_seed_value\n\n## Mix `x` into the running hash `h`.\npub func hash_mix(h: u64, x: u64) -> u64:\n    var r = h ^ x\n    r = r *% 11400714819323198485\n    r = r ^ (r >> 32)\n    return r\n\n## Mix `count` bytes at `data` into the running hash `h`.\npub func hash_bytes(h: u64, data: const void*\?, count: usize) -> u64:\n    var r = h\n    if let p = data:\n        let bytes = (const u8*)p\n        var i: usize = 0\n        while i < count:\n            r = hash_mix(r, (u64)bytes[i])\n            i += 1\n    return hash_mix(r, (u64)count)\n\n## Integer conversions between widths: `bits` of `value` as a 64-bit word.\nfunc mask_of(bits: i32) -> u64:\n    if bits >= 64:\n        return 18446744073709551615\n    return (1 << (u64)bits) - 1\n\nfunc sign_extend(value: i64, bits: i32) -> i64:\n    if bits >= 64:\n        return value\n    let m = mask_of(bits)\n    let x = (u64)value & m\n    if (x & (1 << (u64)(bits - 1))) != 0:\n        return (i64)(x | ~m)\n    return (i64)x\n\nfunc zero_extend(value: u64, bits: i32) -> u64:\n    return value & mask_of(bits)\n\nfunc signed_min(bits: i32) -> i64:\n    if bits >= 64:\n        return -9223372036854775807 - 1\n    return 0 -% (1 << (i64)(bits - 1))\n\nfunc signed_max(bits: i32) -> i64:\n    if bits >= 64:\n        return 9223372036854775807\n    return (1 << (i64)(bits - 1)) - 1\n\nfunc fits_signed(value: i64, bits: i32) -> bool:\n    return value >= signed_min(bits) and value <= signed_max(bits)\n\nfunc fits_unsigned(value: u64, bits: i32) -> bool:\n    return value <= mask_of(bits)\n\n## The source of an integer conversion as a sign and a magnitude, so a `u64` above\n## `i64.max` stays itself.\nstruct Magnitude:\n    var negative: bool\n    var bits: u64\n\nfunc magnitude(value: u64, from_bits: i32, from_signed: i32) -> Magnitude:\n    if from_signed != 0:\n        let v = sign_extend((i64)value, from_bits)\n        return Magnitude(negative = v < 0, bits = (u64)v)\n    return Magnitude(negative = false, bits = zero_extend(value, from_bits))\n\n## A checked conversion's result as bits: outside the destination's range traps (\302\2477.5),\n## naming the statement at `at`.\nfunc checked_bits(m: Magnitude, to_bits: i32, to_signed: i32, at: c.str) -> u64:\n    var bad = false\n    if to_signed != 0:\n        bad = (i64)m.bits < signed_min(to_bits) if m.negative else m.bits > (u64)signed_max(to_bits)\n    else:\n        bad = m.negative or not fits_unsigned(m.bits, to_bits)\n    if bad:\n        trap_at(at, \"integer conversion out of range\")\n    return m.bits\n\n## `T(x)` between integers (`mode` 0, checked) and `(T)x` (`mode` 1, truncating).\npub func conv_s(value: i64, from_bits: i32, from_signed: i32, to_bits: i32, to_signed: i32, mode: i32, at: c.str) -> i64:\n    let m = magnitude((u64)value, from_bits, from_signed)\n    if mode == 0:\n        return (i64)checked_bits(m, to_bits, to_signed, at)\n    let bits = m.bits & mask_of(to_bits)\n    if to_signed != 0:\n        return sign_extend((i64)bits, to_bits)\n    return (i64)bits\n\n## Convert an unsigned value between integer widths and signedness; `mode` chooses checked or wrapping.\npub func conv_u(value: u64, from_bits: i32, from_signed: i32, to_bits: i32, to_signed: i32, mode: i32, at: c.str) -> u64:\n    let m = magnitude(value, from_bits, from_signed)\n    if mode == 0:\n        return checked_bits(m, to_bits, to_signed, at)\n    return zero_extend(m.bits, to_bits)\n\n## A `char` from an integer's bits: a scalar value, or a trap when checked (`mode` 0).\npub func to_char(value: u64, mode: i32, at: c.str) -> u64:\n    let bad = value > 1114111 or (value >= 55296 and value <= 57343)\n    if bad and mode == 0:\n        trap_at(at, \"integer conversion out of range\")\n    return value & 4294967295\n\nfunc is_finite(value: f64) -> bool:\n    return value - value == 0.0\n\n## `2^(bits-1)` and `2^bits` as floats: exact, where `(f64)signed_max(64)` rounds up to `2^63`.\nfunc float_bound_s(bits: i32) -> f64:\n    return (f64)((u64)1 << (u64)(bits - 1))\n\nfunc float_bound_u(bits: i32) -> f64:\n    return float_bound_s(bits) * 2.0\n\n## Float to integer: checked (`mode` 0) or saturating (`mode` 1); the cast inside is the target's own.\npub func f_to_s(value: f64, bits: i32, mode: i32, at: c.str) -> i64:\n    let high = float_bound_s(bits)\n    let low = 0.0 - high\n    if mode == 0:\n        if not is_finite(value) or value < low or value >= high:\n            trap_at(at, \"integer conversion out of range\")\n        return (i64)value\n    if value != value:\n        return 0\n    if value <= low:\n        return signed_min(bits)\n    if value >= high:\n        return signed_max(bits)\n    return (i64)value\n\n## Convert a float to an unsigned integer of `bits`; `mode` checks the range.\npub func f_to_u(value: f64, bits: i32, mode: i32, at: c.str) -> u64:\n    let high = float_bound_u(bits)\n    if mode == 0:\n        if not is_finite(value) or value < 0.0 or value >= high:\n            trap_at(at, \"integer conversion out of range\")\n        return (u64)value\n    if value != value or value < 0.0:\n        return 0\n    if value >= high:\n        return mask_of(bits)\n    return (u64)value\n\n## Saturating arithmetic (`+|`, `-|`, `*|`) on `bits`-wide operands in 64-bit words.\nfunc add_overflows_s(a: i64, b: i64, r: i64) -> bool:\n    return ((a ^ r) & (b ^ r)) < 0\n\nfunc sub_overflows_s(a: i64, b: i64, r: i64) -> bool:\n    return ((a ^ b) & (a ^ r)) < 0\n\nfunc mul_overflows_s(a: i64, b: i64) -> bool:\n    if a == 0 or b == 0:\n        return false\n    if a == -1:\n        return b == signed_min(64)\n    if b == -1:\n        return a == signed_min(64)\n    return (a *% b) // b != a\n\n## Saturating signed addition at `bits`.\n# mark: Saturating and checked arithmetic =====================================================\n\n## Saturating signed addition of `x` and `y` at `bits` bits.\npub func adds_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a +% b\n    if add_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return signed_min(bits) if a < 0 else signed_max(bits)\n    return r\n\n## Saturating unsigned addition at `bits`.\npub func adds_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    let r = a +% b\n    if r < a or not fits_unsigned(r, bits):\n        return mask_of(bits)\n    return r\n\n## Saturating signed subtraction at `bits`.\npub func subs_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a -% b\n    if sub_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return signed_min(bits) if a < 0 else signed_max(bits)\n    return r\n\n## Saturating unsigned subtraction at `bits`.\npub func subs_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if a < b:\n        return 0\n    return a - b\n\n## Saturating signed multiplication at `bits`.\npub func muls_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    if mul_overflows_s(a, b) or not fits_signed(a *% b, bits):\n        return signed_min(bits) if (a < 0) != (b < 0) else signed_max(bits)\n    return a *% b\n\n## Saturating unsigned multiplication at `bits`.\npub func muls_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if b != 0 and a > mask_of(bits) // b:\n        return mask_of(bits)\n    return zero_extend(a *% b, bits)\n\n## Checked-to-optional arithmetic (`+\?`, `-\?`, `*\?`): the result through `out`, whether it fit.\npub func qadd_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a +% b\n    if add_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return false\n    *out = r\n    return true\n\n## Checked unsigned addition through `out`; whether it fit.\npub func qadd_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    let r = a +% b\n    if r < a or not fits_unsigned(r, bits):\n        return false\n    *out = r\n    return true\n\n## Checked signed subtraction through `out`; whether it fit.\npub func qsub_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a -% b\n    if sub_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return false\n    *out = r\n    return true\n\n## Checked unsigned subtraction through `out`; whether it fit.\npub func qsub_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if a < b:\n        return false\n    *out = a - b\n    return true\n\n## Checked signed multiplication through `out`; whether it fit.\npub func qmul_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    if mul_overflows_s(a, b) or not fits_signed(a *% b, bits):\n        return false\n    *out = a *% b\n    return true\n\n## Checked unsigned multiplication through `out`; whether it fit.\npub func qmul_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if b != 0 and a > mask_of(bits) // b:\n        return false\n    *out = a *% b\n    return true\n\n## Terminate the process through the minimal runtime layer.\npub func exit(code: i32) -> never:\n    c_exit(code)\n", 53653};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_6text_7 = {"#==============================================================================================\n#\n#   memory - Allocators and byte primitives\n#\n#   DESCRIPTION:\n#       The allocators of \302\24712, the thread's current-allocator convention, the diagnostic\n#       records of an allocation failure, and the byte copy, move, set, read and write helpers.\n#\n#==============================================================================================\n\nfrom windows_abi import SystemInfo\nfrom windows_abi import GetSystemInfo\nimport platform\nextern func malloc(size: usize) -> void*\?\nextern func c_free as \"free\"(block: void*)\nextern func posix_memalign(memptr: void*\?*, alignment: usize, size: usize) -> i32\nextern func aligned_malloc as \"_aligned_malloc\"(size: usize, alignment: usize) -> void*\?\nextern func aligned_free as \"_aligned_free\"(block: void*)\nextern func memcpy(target: void*, source: const void*, count: usize) -> void*\nextern func memmove(target: void*, source: const void*, count: usize) -> void*\nextern func memset(target: void*, value: i32, count: usize) -> void*\n\n## What every allocator offers: blocks of bytes at an alignment, optionally\n## resized in place, and given back (\302\24712.4). Zero alignment means one. A nonempty\n## block must meet the requested alignment; an allocator may refuse an unsupported\n## alignment. Bump allocators support every positive alignment, not only powers of two.\npub interface Allocator:\n    func allocate(size: usize, alignment: usize) -> u8[]\?\n\n    func resize(block: u8[], size: usize) -> bool\n\n    func release(block: u8[])\n\n## A bump allocator over a caller's bytes. Only the last block can be resized or\n## released; everything goes away together when the buffer does.\npub struct FixedBuffer: Allocator:\n    var data: u8[]\n    var used: usize\n\n    ## An allocator handing out `buffer`'s bytes; only the last block resizes.\n    pub static func over(buffer: u8[]) -> FixedBuffer:\n        return FixedBuffer(data = buffer, used = 0)\n\n    ## Allocate `size` bytes at `alignment`, or none when it cannot.\n    pub func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return self.data[..<0]\n        let align = alignment if alignment > 0 else 1\n        let start = aligned_offset(self.data, self.used, align) else return none\n        if start > self.data.length or size > self.data.length - start:\n            return none\n        self.used = start + size\n        return self.data[start..<self.used]\n\n    ## Try to resize `block` to `size` in place; whether it worked.\n    pub func resize(block: u8[], size: usize) -> bool:\n        if size == block.length:\n            return true\n        if block.length == 0:\n            return false\n        let start = (usize)block.data -\? (usize)self.data.data else return false\n        if start > self.used or block.length != self.used - start:\n            return false\n        if start > self.data.length or size > self.data.length - start:\n            return false\n        self.used = start + size\n        return true\n\n    ## Free `block`.\n    pub func release(block: u8[]):\n        if block.length == 0:\n            return\n        if diagnostic:\n            _ = memset(block.data, 221, block.length)  # a fixed buffer releases all at once\n        let start = (usize)block.data - (usize)self.data.data\n        if start + block.length == self.used:\n            self.used = start\n\n## Align the address inside a bounded span, without rounding an addition past\n## usize's range. The remainder works for arbitrary positive byte alignments.\nfunc aligned_offset(storage: u8[], used: usize, alignment: usize) -> usize\?:\n    if used > storage.length:\n        return none\n    let address = (usize)storage.data +\? used else return none\n    let remainder = address % alignment\n    let padding = 0 if remainder == 0 else alignment - remainder\n    if padding > storage.length - used:\n        return none\n    return used + padding\n\n## The C library's heap.\npub struct CAllocator: Allocator:\n    var unused: u8\n\n    ## Allocate `size` bytes at `alignment`, or none when it cannot.\n    pub func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return u8[]((u8*)8, 0)\n        if alignment != 0 and (alignment & (alignment - 1)) != 0:\n            return none\n        let align = alignment if alignment > 8 else 8\n        var p: void*\? = none\n        if platform.windows:\n            p = aligned_malloc(size, align)\n        elif posix_memalign(&p, align, size) != 0:\n            return none\n        let block = p else return none\n        return u8[]((u8*)block, size)\n\n    ## Try to resize `block` to `size` in place; whether it worked.\n    pub func resize(block: u8[], size: usize) -> bool:\n        return size <= block.length\n\n    ## Free `block`.\n    pub func release(block: u8[]):\n        if block.length == 0:\n            return\n        if not diagnostic:\n            release_heap(block.data)\n            return\n        # the diagnostic profile (\302\24719.4): the block is filled with a pattern and held back, so\n        # a use after release reads the pattern rather than the next allocation; releasing\n        # it again, or writing it while it is held, is reported\n        lock(&records_lock)\n        if already_held(quarantine, block):\n            unlock(&records_lock)\n            trap(\"double free: a block was released twice\")\n        _ = memset(block.data, (i32)released_fill, block.length)\n        let slot = quarantine_next % quarantine.length\n        if let old = quarantine[slot]:\n            if not still_released(old):\n                unlock(&records_lock)\n                trap(\"use after free: a released block was written after its release\")\n            release_heap(old.data)\n        quarantine[slot] = block\n        quarantine_next += 1\n        unlock(&records_lock)\n\nfunc release_heap(block: void*):\n    if platform.windows:\n        aligned_free(block)\n    else:\n        c_free(block)\n\n## Bump allocation over a parent allocator, released all at once by `reset` or `destroy`\n## (\302\24712.4, \302\24724.3). One thread at a time.\npub struct Arena: Allocator:\n    var parent: Allocator\n    var block: u8[]\n    var used: usize\n\n    ## An arena of `capacity` bytes over `parent`, released all at once.\n    pub static func over(parent: Allocator, capacity: usize) -> Arena!:\n        let block = parent.allocate(capacity, 16) else error(exhausted, \"memory.exhausted\")\n        return Arena(parent = parent, block = block, used = 0)\n\n    ## Allocate `size` bytes at `alignment`, or none when it cannot.\n    pub func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return self.block[..<0]\n        let align = alignment if alignment > 0 else 1\n        let start = aligned_offset(self.block, self.used, align) else return none\n        let end = start +\? size else return none\n        if end > self.block.length:\n            return none\n        self.used = end\n        return self.block[start..<end]\n\n    ## Try to resize `block` to `size` in place; whether it worked.\n    pub func resize(block: u8[], size: usize) -> bool:\n        if size == block.length:\n            return true\n        if block.length == 0:\n            return false\n        # the last block may grow or shrink in place\n        let start = (usize)block.data -\? (usize)self.block.data else return false\n        if start > self.used or block.length != self.used - start:\n            return false\n        if start > self.block.length or size > self.block.length - start:\n            return false\n        self.used = start + size\n        return true\n\n    ## Free `block`.\n    pub func release(block: u8[]):\n        if diagnostic and block.length > 0:\n            _ = memset(block.data, 221, block.length)  # an arena releases all at once\n\n    ## What has been handed out since the last reset, and what the arena holds in all.\n    pub func in_use() -> usize:\n        return self.used\n\n    ## The arena's total capacity in bytes.\n    pub func capacity() -> usize:\n        return self.block.length\n\n    ## Forget every allocation; the storage is reused from its start.\n    pub func reset():\n        self.used = 0\n\n    ## Give the storage back to the parent; the arena is empty afterwards.\n    pub func destroy():\n        self.parent.release(self.block)\n        self.block = self.block[..<0]\n        self.used = 0\n\n## Whole pages from the host, each block its own mapping (\302\24712.4). Safe from several threads.\npub struct PageAllocator: Allocator:\n    var unused: u8\n\n    ## Allocate `size` bytes at `alignment`, or none when it cannot.\n    pub func allocate(size: usize, alignment: usize) -> u8[]\?:\n        if size == 0:\n            return u8[]((u8*)8, 0)\n        let page = page_size()\n        if alignment > page or (alignment != 0 and page % alignment != 0):\n            return none\n        let padded = size +\? (page - 1) else return none\n        let rounded = padded // page * page\n        let mapped = map_pages(rounded) else return none\n        if (usize)mapped == ~(usize)0:\n            return none\n        return u8[]((u8*)mapped, rounded)\n\n    ## Try to resize `block` to `size` in place; whether it worked.\n    pub func resize(block: u8[], size: usize) -> bool:\n        return size <= block.length\n\n    ## Free `block`.\n    pub func release(block: u8[]):\n        if block.length == 0:\n            return\n        if not diagnostic:\n            unmap_pages(block)\n            return\n        # the diagnostic profile (\302\24719.4): the mapping is filled and kept for a while, so a\n        # use after release reads the pattern rather than faulting or reading a new mapping\n        lock(&records_lock)\n        if already_held(held_pages, block):\n            unlock(&records_lock)\n            trap(\"double free: pages were released twice\")\n        _ = memset(block.data, (i32)released_fill, block.length)\n        let slot = held_next % held_pages.length\n        if let old = held_pages[slot]:\n            if not still_released(old):\n                unlock(&records_lock)\n                trap(\"use after free: released pages were written after their release\")\n            unmap_pages(old)\n        held_pages[slot] = block\n        held_next += 1\n        unlock(&records_lock)\n\nextern func mmap(address: void*\?, length: usize, protection: i32, flags: i32, descriptor: i32, offset: i64) -> void*\?\n## `MAP_PRIVATE | MAP_ANON`: `MAP_ANON` is 0x1000 on macOS and 0x20 on Linux; the\n## protection `PROT_READ | PROT_WRITE` is 3 on both.\nlet private_anonymous: i32 = 4098 if platform.macos else 34\nextern func munmap(address: void*, length: usize) -> i32\nextern func getpagesize() -> i32\nextern func VirtualAlloc(address: void*\?, size: usize, kind: u32, protection: u32) -> void*\?\nextern func VirtualFree(address: void*, size: usize, kind: u32) -> i32\n\n## The host's memory page size in bytes: the one query `os.page_size` and the threads'\n## stack sizes use too.\npub func page_size() -> usize:\n    if platform.windows:\n        var info: SystemInfo = ---\n        GetSystemInfo(&info)\n        return (usize)info.page_size\n    return (usize)getpagesize()\n\nfunc map_pages(size: usize) -> void*\?:\n    if platform.windows:\n        return VirtualAlloc(none, size, 12288, 4)\n    return mmap(none, size, 3, private_anonymous, -1, 0)\n\nfunc unmap_pages(block: u8[]):\n    if platform.windows:\n        _ = VirtualFree(block.data, 0, 32768)\n    else:\n        _ = munmap(block.data, block.length)\n\n## `--profile diagnostic`: set by the startup shim before `startup` runs.\npub var diagnostic: bool\n\n## An allocation the diagnostic profile recorded (\302\24719.4): the block, its size, and where.\npub struct Site:\n    ## The block's address, or none for a failed request.\n    pub var address: void*\?\n    ## The requested size in bytes.\n    pub var size: usize\n    ## The function that requested it.\n    pub var function: str\n    ## The source line of the request.\n    pub var line: u32\n\nvar sites: Site[256]\nvar site_next: usize\n\n## The diagnostic profile's records are shared by every thread: a short spin lock guards\n## each update, on the atomic `@bool` alone, since this module is below `sync`.\nvar records_lock: @bool\n\nfunc lock(flag: (@bool)*):\n    while true:\n        let (exchanged, observed) = flag.cas(false, true)\n        _ = observed\n        if exchanged:\n            return\n\nfunc unlock(flag: (@bool)*):\n    flag.store(false)\n\n## Called by the compiled program after each allocation under `--profile diagnostic`.\n## The record keeps the most recent 256 allocations, oldest first: once full, the oldest\n## goes and the newest takes the last place.\npub func note_site(address: void*\?, size: usize, function: str, line: u32):\n    lock(&records_lock)\n    if site_next < sites.length:\n        sites[site_next] = Site(address = address, size = size, function = function, line = line)\n    else:\n        var i: usize = 1\n        while i < sites.length:\n            sites[i - 1] = sites[i]\n            i += 1\n        sites[sites.length - 1] = Site(address = address, size = size, function = function, line = line)\n    site_next += 1\n    unlock(&records_lock)\n\n## The allocations recorded so far, the most recent 256 at most, oldest first. A view of\n## the record: read it while no other thread allocates.\npub func allocation_sites() -> const Site[]:\n    let held = site_next if site_next < sites.length else sites.length\n    return sites[..<held]\n\n## The released blocks the diagnostic profile still holds, oldest freed first.\nvar quarantine: (u8[]\?)[256]\nvar quarantine_next: usize\n## The released mappings the diagnostic profile still holds, oldest first.\nvar held_pages: (u8[]\?)[8]\nvar held_next: usize\n## The byte a released block is filled with under the diagnostic profile.\nlet released_fill: u8 = 221\n## The byte unwritten storage is filled with under the diagnostic profile: `---` storage,\n## `memory.allocate` and `memory.frame`; the compiler writes the same byte, 0xAA.\nlet unwritten_fill: u8 = 170\n\n## Whether `block` is among the released blocks still `held`: releasing it again is a\n## double free.\nfunc already_held(blocks: const (u8[]\?)[], block: u8[]) -> bool:\n    for entry in blocks:\n        if let kept = entry:\n            if kept.data == block.data:\n                return true\n    return false\n\n## Whether every byte of a held block is still the fill it was given at release: a write\n## through a dangling pointer changes one.\nfunc still_released(block: const u8[]) -> bool:\n    for byte in block:\n        if byte != released_fill:\n            return false\n    return true\n\n## Allocation failed: out of memory.\n# mark: Diagnostics and heap ==================================================================\n\n## Allocation failed because memory is exhausted.\npub let exhausted: ErrorCode = ErrorCode.package(1)\n## No allocator is current (\302\24712.3).\npub let unset: ErrorCode = ErrorCode.package(2)\n\nvar c_allocator: CAllocator\n## The current allocator of this thread (\302\24712.3) and the process's initial one.\npub local var allocator: Allocator\n## The process's C heap allocator.\npub var heap: Allocator\n\n## Run by the startup shim before `main`, and by `thread.spawn` in a new thread.\npub func startup():\n    heap = &c_allocator\n    allocator = heap\n\n## Copy `count` elements from `source` to `target` (no overlap).\n# mark: Byte primitives =======================================================================\n\n## Copy `count` elements from `source` into `target`.\npub func copy[T](target: T[], source: const T[], count: usize):\n    if count > target.length or count > source.length:\n        trap(\"index out of bounds\")\n    if count > 0:\n        _ = memcpy(target.data, source.data, count * size_of(T))\n\n## Copy `count` elements, allowing `source` and `target` to overlap.\npub func move[T](target: T[], source: const T[], count: usize):\n    if count > target.length or count > source.length:\n        trap(\"index out of bounds\")\n    if count > 0:\n        _ = memmove(target.data, source.data, count * size_of(T))\n\n## Set every byte of `target` to `value`.\npub func set(target: u8[], value: u8):\n    if target.length > 0:\n        _ = memset(target.data, (i32)value, target.length)\n\n## Read a `T` from `address`, which may be unaligned.\npub func read[T](address: const void*) -> T:\n    var value: T = ---\n    _ = memcpy(&value, address, size_of(T))\n    return value\n\n## Write `value` to `address`, which may be unaligned.\npub func write[T](address: void*, value: T):\n    var copy_of = value\n    _ = memcpy(address, &copy_of, size_of(T))\n\n## `count` uninitialised elements of `T` in the frame of the function that calls this, at\n## most `most` (a constant; `most * size_of(T)` at most 4096 bytes), freed when that function\n## returns (\302\24712.7). The compiler takes the storage at the call, so this body never runs.\npub func frame[T](count: usize, most: usize) -> T[]:\n    trap(\"memory.frame is answered where it is called\")\n\n## `size` unwritten bytes aligned to `alignment`, from the current allocator: storage a\n## structure lays out itself (\302\24712.2), given back with `free`; the diagnostic profile fills\n## them with 0xAA (\302\24719.4). Fails with `memory.exhausted`.\npub func allocate(size: usize, alignment: usize) -> u8[]!:\n    let block = allocator.allocate(size, alignment) else error(exhausted, \"memory.exhausted\")\n    if diagnostic:\n        _ = memset(block.data, (i32)unwritten_fill, block.length)\n    return block\n\n## `block` with `size` bytes: in place when the current allocator can, else a\n## new block with the old bytes copied and the old block released. The bytes past the\n## old ones are unwritten, 0xAA under the diagnostic profile.\npub func grow(block: u8[], size: usize) -> u8[]!:\n    var grown: u8[] = ---\n    if allocator.resize(block, size):\n        grown = u8[](block.data, size)\n    else:\n        grown = allocator.allocate(size, 8) else error(exhausted, \"memory.exhausted\")\n        let keep = block.length if block.length < size else size\n        if keep > 0:\n            _ = memcpy(grown.data, block.data, keep)\n        allocator.release(block)\n    if diagnostic and size > block.length:\n        _ = memset(&grown[block.length], (i32)unwritten_fill, size - block.length)\n    return grown\n", 18121};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_6text_8 = {"#==============================================================================================\n#\n#   windows_text - Allocating Windows text conversions\n#\n#   DESCRIPTION:\n#       Returned storage belongs to the current allocator and includes a NUL terminator.\n#       Callers select their API's error code.\n#\n#==============================================================================================\n\nimport c\nimport memory\nimport windows_abi\n\n## UTF-8 `text` to a NUL-terminated UTF-16 buffer, `invalid` on malformed input.\npub func wide(text: c.str, invalid: ErrorCode) -> u16[]!:\n    let count = windows_abi.MultiByteToWideChar(windows_abi.utf8_page, windows_abi.reject_invalid_utf8, text, -1, none, 0)\n    if count <= 0:\n        error(invalid, \"OS text is not valid UTF-8\")\n    let result = try new u16[(usize)count] ---\n    errdefer free(result)\n    if windows_abi.MultiByteToWideChar(windows_abi.utf8_page, windows_abi.reject_invalid_utf8, text, -1, result.data, count) != count:\n        error(invalid, \"OS text could not be converted to UTF-16\")\n    return result\n\n## UTF-16 `text` to a NUL-terminated UTF-8 string, `invalid` on malformed input.\npub func narrow(text: const u16[], invalid: ErrorCode) -> str!:\n    if text.length > 2147483647:\n        error(invalid, \"OS text exceeds the conversion limit\")\n    let count = windows_abi.WideCharToMultiByte(windows_abi.utf8_page, windows_abi.reject_invalid_utf16, text.data, (i32)text.length, none, 0, none, none)\n    if count == 0 and text.length > 0:\n        error(invalid, \"OS text is not valid UTF-16\")\n    let result = try new u8[(usize)count + 1] ---\n    errdefer free(result)\n    if count > 0 and windows_abi.WideCharToMultiByte(windows_abi.utf8_page, windows_abi.reject_invalid_utf16, text.data, (i32)text.length, result.data, count, none, none) != count:\n        error(invalid, \"OS text could not be converted to UTF-8\")\n    result[(usize)count] = 0\n    return (str)result[..<(usize)count]\n", 1959};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_6text_9 = {"#==============================================================================================\n#\n#   os - The operating system's view of the process\n#\n#   DESCRIPTION:\n#       Its environment, working directory, identity and host (\302\24716.6). Text comes back as `str`\n#       views of C storage that the system owns; copy what must outlive the next call.\n#\n#==============================================================================================\nimport c\nimport memory\nimport windows_text\nimport platform\nextern func getenv(variable: c.str) -> c.str\?\nextern func setenv(variable: c.str, value: c.str, overwrite: i32) -> i32\nextern func unsetenv(variable: c.str) -> i32\nextern func getcwd(buffer: u8*, size: usize) -> c.str\?\nextern func readlink(path: c.str, buffer: void*, capacity: usize) -> isize\nextern func mac_executable_path as \"_NSGetExecutablePath\"(buffer: u8*, size: u32*) -> i32\nextern func chdir(path: c.str) -> i32\nextern func getpid() -> i32\nextern func getppid() -> i32\nextern func gethostname(buffer: u8*, size: usize) -> i32\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func sysconf(option: i32) -> i64\nextern func getentropy(buffer: void*, count: usize) -> i32\nextern func BCryptGenRandom(algorithm: void*\?, buffer: u8*, count: u32, flags: u32) -> i32\n\n## Fill bytes from the operating system's cryptographic random generator.\n## A failure is reported; weak process IDs or timestamps are never substituted.\npub func random_bytes(buffer: u8[]) -> !:\n    var offset: usize = 0\n    while offset < buffer.length:\n        let count = buffer.length - offset if buffer.length - offset < 256 else 256\n        var result: i32 = 0\n        if platform.windows:\n            result = BCryptGenRandom(none, &buffer[offset], (u32)count, 2)\n        else:\n            result = getentropy(&buffer[offset], count)\n        if result != 0:\n            error(failed, \"operating system randomness is unavailable\")\n        offset += count\n\n## An operating-system call failed.\npub let failed: ErrorCode = ErrorCode.package(12)\n\n## The target, as constants a program branches on: `if os.arm64:`, `if os.linux and\n## os.x86_64:` (\302\24719.5); the compiler decides them from `--target`, so the branch a target\n## rules out is pruned (\302\24719.6).\npub let arm64: bool = platform.arm64\n## Whether the target architecture is x86-64.\npub let x86_64: bool = platform.x86_64\n## Whether the target operating system is macOS.\npub let macos: bool = platform.macos\n## Whether the target operating system is Linux.\npub let linux: bool = platform.linux\n## Whether the target operating system is Windows.\npub let windows: bool = platform.windows\n## Whether the target is a POSIX system.\npub let posix: bool = platform.posix\n## The width of a pointer on the target, in bits.\npub let pointer_bits: u32 = platform.pointer_bits\n## The target triple.\npub let name: str = platform.name\n## The instruction-set level the program was compiled for (`--cpu`, \302\24719.5): on x86-64, 1\n## to 4 for x86-64-v1 to v4; on arm64, 1 for NEON, 2 for SVE.\npub let cpu_level: u32 = platform.cpu_level\n\n## The instruction-set level of the processor this program runs on, in the same scale:\n## what it may dispatch to at run time. On x86-64 `cpuid` answers; on arm64 the level is\n## NEON until the system reports SVE.\n# mark: Machine and process ===================================================================\n\n## The microarchitecture level (\302\24719.5) the CPU running this process supports.\npub func cpu_level_running() -> u32:\n    if platform.x86_64:\n        return x86_level()\n    return 1\n\n## x86-64: SSE4.2 and POPCNT make v2; AVX2, FMA, and BMI2 make v3; AVX-512F makes v4.\nfunc x86_level() -> u32:\n    var c1: u32 = 0\n    var b7: u32 = 0\n    asm x86_64 (in(\"eax\") 1u32, out(\"ecx\") c1, out(\"eax\") _, out(\"ebx\") _, out(\"edx\") _, options(nostack)):\n        cpuid\n    asm x86_64 (in(\"eax\") 7u32, in(\"ecx\") 0u32, out(\"ebx\") b7, out(\"eax\") _, out(\"ecx\") _, out(\"edx\") _, options(nostack)):\n        cpuid\n    let sse42 = (c1 & (1 << 20)) != 0\n    let popcnt = (c1 & (1 << 23)) != 0\n    let fma = (c1 & (1 << 12)) != 0\n    # the operating system saves the wide registers only with `OSXSAVE` set\n    let osxsave = (c1 & (1 << 27)) != 0\n    let avx2 = (b7 & (1 << 5)) != 0\n    let bmi2 = (b7 & (1 << 8)) != 0\n    let avx512f = (b7 & (1 << 16)) != 0\n    if not (sse42 and popcnt):\n        return 1\n    if not (avx2 and fma and bmi2 and osxsave):\n        return 2\n    return 4 if avx512f else 3\n\n## `_SC_NPROCESSORS_ONLN`: 58 on macOS, 84 on Linux.\nlet processors_online: i32 = 58 if platform.macos else 84\n\n## The processors available to this process, at least one.\npub func cpus() -> u32:\n    if platform.windows:\n        let count = GetActiveProcessorCount(65535)\n        return count if count > 0 else 1\n    let n = sysconf(processors_online)\n    return (u32)n if n > 0 else 1\n\n## The host's memory page size in bytes.\npub func page_size() -> usize:\n    return memory.page_size()\n\n## The value of an environment variable, or none when it is not set. Copy a view\n## that must survive another env call on this thread or an environment mutation.\npub func env(variable: c.str) -> str\?:\n    if platform.windows:\n        return windows_env(variable)\n    let value = getenv(variable) else return none\n    return (str)value\n\n## Set an environment variable for this process and the ones it starts.\npub func set_env(variable: c.str, value: c.str) -> !:\n    if platform.windows:\n        let key = try windows_text.wide(variable, failed)\n        defer free(key)\n        let text = try windows_text.wide(value, failed)\n        defer free(text)\n        if SetEnvironmentVariableW(key.data, text.data) == 0:\n            error(failed, \"the environment variable cannot be set\")\n        return\n    if setenv(variable, value, 1) != 0:\n        error(failed, \"the environment variable cannot be set\")\n\n## Remove environment variable `variable`.\npub func unset_env(variable: c.str) -> !:\n    if platform.windows:\n        let key = try windows_text.wide(variable, failed)\n        defer free(key)\n        if SetEnvironmentVariableW(key.data, none) == 0 and GetLastError() != 203:\n            error(failed, \"the environment variable cannot be unset\")\n        return\n    if unsetenv(variable) != 0:\n        error(failed, \"the environment variable cannot be unset\")\n\n## The working directory, in storage from the current allocator.\npub func cwd() -> str!:\n    if platform.windows:\n        return try windows_cwd()\n    let buffer = try new u8[4096] ---\n    errdefer free(buffer)\n    let found = getcwd(buffer.data, buffer.length)\n    if found == none:\n        error(failed, \"the working directory cannot be read\")\n    let path = found else trap(\"unreachable\")\n    return (str)path\n\n## The path of this program's executable as the loader saw it, in an allocation of the\n## current allocator, NUL-terminated for the C calls a path goes to.\npub func executable() -> str!:\n    if platform.windows:\n        return try windows_executable()\n    let buffer = try new u8[4096] ---\n    errdefer free(buffer)\n    var count: usize = 0\n    if platform.macos:\n        var size: u32 = 4096\n        if mac_executable_path(buffer.data, &size) != 0:\n            error(failed, \"the executable path cannot be read\")\n        while count < buffer.length and buffer[count] != 0:\n            count += 1\n    else:\n        let read = readlink(\"/proc/self/exe\", buffer.data, buffer.length - 1)\n        if read < 0:\n            error(failed, \"the executable path cannot be read\")\n        count = (usize)read\n    buffer[count] = 0\n    return (str)buffer[..<count]\n\n## Change the process's working directory to `path`.\npub func change_dir(path: c.str) -> !:\n    if platform.windows:\n        let text = try windows_text.wide(path, failed)\n        defer free(text)\n        if SetCurrentDirectoryW(text.data) == 0:\n            error(failed, \"the directory cannot be entered\")\n        return\n    if chdir(path) != 0:\n        error(failed, \"the directory cannot be entered\")\n\n## The process identifier.\npub func pid() -> i32:\n    if platform.windows:\n        return (i32)GetCurrentProcessId()\n    return getpid()\n\n## The parent process's identifier.\npub func parent_pid() -> i32:\n    if platform.windows:\n        return windows_parent_pid()\n    return getppid()\n\n## The host's name, in storage from the current allocator.\npub func hostname() -> str!:\n    if platform.windows:\n        var host_text: u16[256]\n        var count: u32 = 256\n        if GetComputerNameW(&host_text[0], &count) == 0:\n            error(failed, \"the host name cannot be read\")\n        return try windows_text.narrow(host_text[..<(usize)count], failed)\n    let buffer = try new u8[256] ---\n    errdefer free(buffer)\n    if gethostname(buffer.data, buffer.length) != 0:\n        error(failed, \"the host name cannot be read\")\n    var n: usize = 0\n    while n < buffer.length and buffer[n] != 0:\n        n += 1\n    return (str)buffer[..<n]\n\n## Stop the process with `code`, running no deferred work.\npub func exit(code: i32) -> never:\n    c_exit(code)\n", 9017};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_10 = {"#==============================================================================================\n#\n#   windows - The os module's native Windows calls\n#\n#   DESCRIPTION:\n#       Native Windows calls stay behind the portable `os` interface. Public text is UTF-8.\n#\n#==============================================================================================\n\nfrom windows_abi import MultiByteToWideChar, WideCharToMultiByte, GetLastError, SetLastError, CloseHandle, GetCurrentProcessId, GetEnvironmentVariableW, SetEnvironmentVariableW, GetCurrentDirectoryW, SetCurrentDirectoryW\nextern func GetComputerNameW(output: u16*, capacity: u32*) -> i32\nextern func GetModuleFileNameW(module: void*\?, output: u16*, capacity: u32) -> u32\nextern func GetActiveProcessorCount(group: u16) -> u32\nextern func CreateToolhelp32Snapshot(flags: u32, process: u32) -> void*\nextern func Process32FirstW(snapshot: void*, entry: WinProcessEntry*) -> i32\nextern func Process32NextW(snapshot: void*, entry: WinProcessEntry*) -> i32\n\nextern struct WinProcessEntry:\n    size: u32\n    usage: u32\n    pid: u32\n    heap: usize\n    module: u32\n    threads: u32\n    parent: u32\n    priority: i32\n    flags: u32\n    executable: u16[260]\n\n# Environment views last until the next env call on this thread. Fixed bounds are\n# the Windows environment limit, independent of the caller's current allocator.\nlocal var environment_wide: u16[32768]\nlocal var environment_utf8: u8[131073]\nlocal var environment_key: u16[32768]\n\nfunc windows_env(variable: c.str) -> str\?:\n    if MultiByteToWideChar(65001, 8, variable, -1, &environment_key[0], 32768) == 0:\n        return none\n    SetLastError(0)\n    let count = GetEnvironmentVariableW(&environment_key[0], &environment_wide[0], 32768)\n    if count >= 32768 or (count == 0 and GetLastError() != 0):\n        return none\n    var size: i32 = 0\n    if count > 0:\n        size = WideCharToMultiByte(65001, 128, &environment_wide[0], (i32)count, &environment_utf8[0], 131072, none, none)\n        if size == 0:\n            return none\n    environment_utf8[(usize)size] = 0\n    return (str)environment_utf8[..<(usize)size]\n\nfunc windows_cwd() -> str!:\n    var attempt: usize = 0\n    while attempt < 8:\n        let capacity = GetCurrentDirectoryW(0, none)\n        if capacity == 0:\n            break\n        let text = try new u16[(usize)capacity] ---\n        defer free(text)\n        let count = GetCurrentDirectoryW(capacity, text.data)\n        if count == 0:\n            break\n        if count < capacity:\n            return try windows_text.narrow(text[..<(usize)count], failed)\n        attempt += 1\n    error(failed, \"the working directory cannot be read\")\n\n## The module path grows until the call answers a length below the capacity: a full\n## buffer is a truncated path.\nfunc windows_executable() -> str!:\n    var capacity: usize = 260\n    while capacity <= 32768:\n        let text = try new u16[capacity] ---\n        defer free(text)\n        let count = GetModuleFileNameW(none, text.data, (u32)capacity)\n        if count == 0:\n            break\n        if (usize)count < capacity:\n            return try windows_text.narrow(text[..<(usize)count], failed)\n        capacity *= 4\n    error(failed, \"the executable path cannot be read\")\n\nfunc windows_parent_pid() -> i32:\n    let snapshot = CreateToolhelp32Snapshot(2, 0)\n    if (usize)snapshot == ~(usize)0:\n        return 0\n    defer _ = CloseHandle(snapshot)\n    var entry: WinProcessEntry\n    entry.size = (u32)memory.size_of(WinProcessEntry)\n    var found = Process32FirstW(snapshot, &entry)\n    let current = GetCurrentProcessId()\n    while found != 0:\n        if entry.pid == current:\n            return (i32)entry.parent\n        found = Process32NextW(snapshot, &entry)\n    return 0\n", 3745};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_11 = {"#==============================================================================================\n#\n#   io - Byte streams\n#\n#   DESCRIPTION:\n#       Readers and writers over bytes, buffered wrappers, the standard output and error\n#       streams, the user's home directory, and the stream error codes.\n#\n#==============================================================================================\n\nimport c\nimport core\nimport memory\nimport platform\nimport os\nimport strings\nextern func fwrite(data: const void*, size: usize, count: usize, stream: void*) -> usize\nextern func fflush(stream: void*\?) -> i32\nextern func flockfile(stream: void*)\nextern func funlockfile(stream: void*)\nextern func win_lock_file as \"_lock_file\"(stream: void*)\nextern func win_unlock_file as \"_unlock_file\"(stream: void*)\nextern func posix_read as \"read\"(descriptor: i32, buffer: void*, count: usize) -> isize\nextern func windows_read as \"_read\"(descriptor: i32, buffer: void*, count: u32) -> i32\n\nfunc c_read(descriptor: i32, buffer: void*, count: usize) -> isize:\n    if platform.windows:\n        return (isize)windows_read(descriptor, buffer, (u32)(count if count < 2147483647 else 2147483647))\n    return posix_read(descriptor, buffer, count)\n\n## A borrowed byte source. A successful read returns at most the buffer length;\n## zero for a nonempty buffer means EOF. Empty reads return zero without consuming\n## input. Errors are distinct from EOF. The implementing object owns its lifetime.\npub interface Reader:\n    func read(buffer: u8[]) -> usize!\n\n## A borrowed byte sink (\302\24714.4). A write may accept fewer bytes than supplied;\n## callers needing the whole payload use `write_all`. Empty writes return zero.\n## A failure may follow earlier successful writes; the view never owns the sink.\npub interface Writer:\n    func write(data: const u8[]) -> usize!\n\n## A stream ended before the expected bytes arrived.\npub let unexpected_eof: ErrorCode = ErrorCode.package(14)\n## A stream made no progress and cannot continue.\npub let no_progress: ErrorCode = ErrorCode.package(15)\n## A read or write was asked for an invalid count.\npub let invalid_count: ErrorCode = ErrorCode.package(16)\n## A read or write was given an invalid buffer.\npub let invalid_buffer: ErrorCode = ErrorCode.package(17)\n\n## Fill `buffer`, or fail at EOF or on a source error. Optional `transferred` is\n## reset to zero on entry and updated after each successful read, including before\n## a later failure. It must not overlap the buffer or the source's state. No call\n## reaches the source for an empty buffer. The source remains borrowed and open.\npub func read_exact(source: Reader, buffer: u8[], transferred: usize*\? = none) -> !:\n    var done: usize = 0\n    if let progress = transferred:\n        *progress = 0\n    while done < buffer.length:\n        let count = try source.read(buffer[done..])\n        if count > buffer.length - done:\n            error(invalid_count, \"the reader returned more bytes than requested\")\n        if count == 0:\n            error(unexpected_eof, \"the reader ended before the buffer was filled\")\n        done += count\n        if let progress = transferred:\n            *progress = done\n\n## Write all bytes, preserving confirmed progress through `transferred` on error.\n## The progress pointer must not overlap the data or sink state. A zero-length\n## successful write on nonempty input fails with `no_progress` instead of spinning.\n## This does not flush or close the borrowed sink. Empty input makes no sink call.\npub func write_all(destination: Writer, data: const u8[], transferred: usize*\? = none) -> !:\n    var done: usize = 0\n    if let progress = transferred:\n        *progress = 0\n    while done < data.length:\n        let count = try destination.write(data[done..])\n        if count > data.length - done:\n            error(invalid_count, \"the writer returned more bytes than supplied\")\n        if count == 0:\n            error(no_progress, \"the writer accepted no bytes\")\n        done += count\n        if let progress = transferred:\n            *progress = done\n\n## Copy at most `limit` bytes through caller-owned scratch storage; stop earlier\n## at EOF. Reads never consume beyond the limit. `transferred` counts confirmed\n## destination bytes, including before a failure; source consumption can be ahead\n## by one scratch buffer if writing fails. Scratch and progress must not overlap\n## either endpoint's state/data or each other. No allocation, flush or close occurs.\npub func copy_limit(source: Reader, destination: Writer, buffer: u8[], limit: usize, transferred: usize*\? = none) -> usize!:\n    var done: usize = 0\n    if let progress = transferred:\n        *progress = 0\n    if limit == 0:\n        return 0\n    if buffer.length == 0:\n        error(invalid_buffer, \"copying requires a nonempty scratch buffer\")\n    while done < limit:\n        let available = limit - done\n        let requested = buffer.length if buffer.length < available else available\n        let count = try source.read(buffer[..<requested])\n        if count > requested:\n            error(invalid_count, \"the reader returned more bytes than requested\")\n        if count == 0:\n            break\n        var written: usize = 0\n        write_all(destination, buffer[..<count], &written) catch failure:\n            if let progress = transferred:\n                *progress = done + written\n            error(failure.code, failure.message)\n        done += written\n        if let progress = transferred:\n            *progress = done\n    return done\n\n## A cursor over borrowed bytes. Copying the reader copies its position, not its\n## data. The backing storage must outlive the reader and every read using it.\npub struct SliceReader: Reader:\n    var data: const u8[]\n    var position: usize\n\n    ## A reader over `data`.\n    pub static func over(data: const u8[]) -> SliceReader:\n        return SliceReader(data = data, position = 0)\n\n    ## The number of bytes not yet read.\n    pub func remaining() -> usize:\n        return self.data.length - self.position\n\n    ## Copy up to the buffer length; zero means no bytes remain (or an empty read).\n    pub func read(buffer: u8[]) -> usize!:\n        let left = self.remaining()\n        let count = buffer.length if buffer.length < left else left\n        memory.move(buffer, self.data[self.position..], count)\n        self.position += count\n        return count\n\n## A writer into fixed borrowed storage. Copying it copies the cursor and aliases\n## storage. Writes may be short; once full, a nonempty write fails with `full`.\npub struct SliceWriter: Writer:\n    var data: u8[]\n    var used: usize\n\n    ## A writer into `data`.\n    pub static func over(data: u8[]) -> SliceWriter:\n        return SliceWriter(data = data, used = 0)\n\n    ## View of confirmed written bytes, borrowed from the caller's storage.\n    pub func written() -> const u8[]:\n        return self.data[..<self.used]\n\n    ## Write `data`; the number of bytes written.\n    pub func write(data: const u8[]) -> usize!:\n        if data.length == 0:\n            return 0\n        let left = self.data.length - self.used\n        if left == 0:\n            error(full, \"the destination buffer is full\")\n        let count = data.length if data.length < left else left\n        memory.move(self.data[self.used..], data, count)\n        self.used += count\n        return count\n\n## Buffered input over a borrowed source and nonempty caller-owned storage. Both\n## must outlive this adapter. Storage must not overlap source state or read buffers.\n## Construct with `over`; serialize access and do not use copied adapters together.\n## Reads may prefetch beyond the requested bytes. The adapter never closes its source.\npub struct BufferedReader: Reader:\n    var source: Reader\n    var storage: u8[]\n    var position: usize\n    var used: usize\n\n    ## A buffered reader over `source`, using `storage`.\n    pub static func over(source: Reader, storage: u8[]) -> BufferedReader!:\n        if storage.length == 0:\n            error(invalid_buffer, \"buffered input requires nonempty storage\")\n        return BufferedReader(source = source, storage = storage, position = 0, used = 0)\n\n    ## Unread bytes already fetched. No source operation occurs.\n    pub func buffered() -> usize:\n        return self.used - self.position\n\n    ## Return buffered bytes first, otherwise perform one source read. Empty reads\n    ## do not call the source. EOF is not cached, allowing a growing source to resume.\n    pub func read(buffer: u8[]) -> usize!:\n        if buffer.length == 0:\n            return 0\n        if self.position == self.used:\n            let count = try self.source.read(self.storage)\n            if count > self.storage.length:\n                error(invalid_count, \"the reader returned more bytes than requested\")\n            self.position = 0\n            self.used = count\n        let available = self.buffered()\n        let count = buffer.length if buffer.length < available else available\n        memory.copy(buffer, self.storage[self.position..], count)\n        self.position += count\n        return count\n\n## Buffered output over a borrowed sink and nonempty caller-owned storage. Both\n## must outlive this adapter; storage must not overlap sink state or write input.\n## Construct with `over`; serialize access and do not use copied adapters together.\n## Explicitly flush before discarding the adapter. There is no implicit flush/close.\npub struct BufferedWriter: Writer:\n    var destination: Writer\n    var storage: u8[]\n    var used: usize\n\n    ## A buffered writer over `destination`, using `storage`.\n    pub static func over(destination: Writer, storage: u8[]) -> BufferedWriter!:\n        if storage.length == 0:\n            error(invalid_buffer, \"buffered output requires nonempty storage\")\n        return BufferedWriter(destination = destination, storage = storage, used = 0)\n\n    ## Bytes accepted by this adapter but not yet confirmed by the destination.\n    pub func buffered() -> usize:\n        return self.used\n\n    ## Drain this buffer, preserving the unconfirmed suffix if the sink fails.\n    ## Retrying does not resend bytes confirmed by earlier successful sink writes.\n    ## This neither flushes downstream buffers nor requests filesystem durability.\n    pub func flush() -> !:\n        var written: usize = 0\n        write_all(self.destination, self.storage[..<self.used], &written) catch failure:\n            self.used -= written\n            memory.move(self.storage, self.storage[written..], self.used)\n            error(failure.code, failure.message)\n        self.used = 0\n\n    ## Accept up to the remaining capacity. A full buffer is drained before any\n    ## new input is accepted; a failure accepts none of this call's input. Empty\n    ## writes do not drain the buffer. Use write_all to accept an entire payload.\n    pub func write(data: const u8[]) -> usize!:\n        if data.length == 0:\n            return 0\n        if self.used == self.storage.length:\n            try self.flush()\n        let available = self.storage.length - self.used\n        let count = data.length if data.length < available else available\n        memory.copy(self.storage[self.used..], data, count)\n        self.used += count\n        return count\n\n## A compile-time source position, the value of `luce.location`.\npub struct Location:\n    ## The source file of the location.\n    pub var file: str\n    ## The source line of the location.\n    pub var line: u32\n    ## The enclosing function of the location.\n    pub var function: str\n\n## The stream is closed.\npub let closed: ErrorCode = ErrorCode.package(3)\n## The underlying stream operation failed.\npub let failed: ErrorCode = ErrorCode.package(24)\n## A non-blocking stream has no data ready.\npub let would_block: ErrorCode = ErrorCode.package(28)\n\n## Borrowed standard output stream. Each nonempty write uses the existing libc\n## stream and flushes only that stream, making completed output visible before a\n## following print. The libc stream lock serializes each write with other libc\n## users; concurrent direct descriptor writes may interleave. No stream is created\n## or owned here. A write/flush failure can follow partial output.\npub struct File: Writer:\n    var descriptor: i32\n\n    func stream() -> void*!:\n        if self.descriptor == 1:\n            return c.stdout()\n        if self.descriptor == 2:\n            return c.stderr()\n        error(closed, \"the standard output stream is unavailable\")\n\n    ## Flush this C stream, without closing it or requesting filesystem durability.\n    pub func flush() -> !:\n        let stream = try self.stream()\n        if fflush(stream) != 0:\n            error(closed, \"the stream could not be flushed\")\n\n    ## Write `data`; the number of bytes written.\n    pub func write(data: const u8[]) -> usize!:\n        if data.length == 0:\n            return 0\n        let stream = try self.stream()\n        lock_stream(stream)\n        defer unlock_stream(stream)\n        let written = fwrite(data.data, 1, data.length, stream)\n        let flushed = fflush(stream)\n        if written != data.length or flushed != 0:\n            error(closed, \"the stream refused the bytes\")\n        return written\n\nfunc lock_stream(stream: void*):\n    if platform.windows:\n        win_lock_file(stream)\n    else:\n        flockfile(stream)\n\nfunc unlock_stream(stream: void*):\n    if platform.windows:\n        win_unlock_file(stream)\n    else:\n        funlockfile(stream)\n\nvar out_file: File = File(descriptor = 1)\nvar err_file: File = File(descriptor = 2)\n\n## Unbuffered input borrows descriptor zero. It retries interrupted calls, reports\n## would-block separately, and never owns or closes the process's descriptor.\nstruct StandardInput: Reader:\n    var descriptor: i32\n\n    ## Read into `buffer`; the number of bytes read.\n    pub func read(buffer: u8[]) -> usize!:\n        if buffer.length == 0:\n            return 0\n        let requested = 1073741824 if buffer.length > 1073741824 else buffer.length\n        while true:\n            let count = c_read(self.descriptor, buffer.data, requested)\n            if count >= 0:\n                return (usize)count\n            let number = c.errno()\n            if number == c.interrupted:\n                continue\n            if number == (35 if platform.macos else 11):\n                error(would_block, \"standard input would block\")\n            if number == 9:\n                error(closed, \"standard input is closed\")\n            error(failed, \"standard input could not be read\")\n\nvar in_file: StandardInput = StandardInput(descriptor = 0)\n\n## Borrowed unbuffered standard input. Reads may block; concurrent readers compete\n## for bytes. Do not mix with buffered C stdin reads, which may have prefetched data.\npub func stdin() -> Reader:\n    return &in_file\n\n## The process's standard output stream.\n# mark: Standard streams ======================================================================\n\n## A writer over the process's standard output.\npub func stdout() -> Writer:\n    return &out_file\n\n## The process's standard error stream.\npub func stderr() -> Writer:\n    return &err_file\n\n## Explicitly flush C stdout, including bytes written through C interop.\npub func flush_stdout() -> !:\n    try out_file.flush()\n\n## Explicitly flush C stderr, including bytes written through C interop.\npub func flush_stderr() -> !:\n    try err_file.flush()\n\n## A fixed writer has no room left.\npub let full: ErrorCode = ErrorCode.package(4)\n\n## The sink a formatted string offers a `Display` value (\302\24714.4): it appends to the buffer\n## the compiler is filling, and fails once that buffer is full, as `format` then does.\npub struct FormatSink: Writer:\n    var buffer: core.FormatBuffer*\n\n    ## Write `data`; the number of bytes written.\n    pub func write(data: const u8[]) -> usize!:\n        if core.format_put(self.buffer, data.data, data.length) != 0:\n            error(full, \"the buffer is full\")\n        return data.length\n\n## The process's directories (\302\24716.6): `from io import path`, then `path.user()`. Each is\n## a `str` view of environment storage the system owns, or fresh storage from the current\n## allocator where one has to be built.\npub struct path:\n    var unused: u8\n\n    ## The user's home directory: USERPROFILE on Windows, HOME on POSIX.\n    pub static func user() -> str!:\n        let home = os.env(\"USERPROFILE\" if platform.windows else \"HOME\") else error(io_path_failed, \"no home directory\")\n        return home\n\n    ## The current user's home directory.\n    pub static func home() -> str!:\n        return try path.user()\n\n    ## Where temporary files go: `$TMPDIR`, else `/tmp`.\n    pub static func temp() -> str:\n        if platform.windows:\n            if let dir = os.env(\"TEMP\"):\n                if dir.length > 0: return dir\n            if let dir = os.env(\"TMP\"):\n                if dir.length > 0: return dir\n            return \".\"\n        let dir = os.env(\"TMPDIR\") else return \"/tmp\"\n        return dir\n\n    ## Where configuration lives: `$XDG_CONFIG_HOME`, else `$HOME/.config`.\n    pub static func config() -> str!:\n        if platform.windows:\n            if let set = os.env(\"APPDATA\"):\n                if set.length > 0: return set\n            let home = try path.user()\n            let buffer = try new u8[home.length + 17] ---\n            return try strings.format(buffer, f\"{home}/AppData/Roaming\")\n        if let set = os.env(\"XDG_CONFIG_HOME\"):\n            return set\n        let home = try path.user()\n        let buffer = try new u8[home.length + 9] ---\n        return try strings.format(buffer, f\"{home}/.config\")\n\n## The home directory could not be determined.\npub let io_path_failed: ErrorCode = ErrorCode.package(13)\n", 17633};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_12 = {"#==============================================================================================\n#\n#   luce - The derived interface bounds\n#\n#   DESCRIPTION:\n#       The derived bounds of \302\24714.4: every type with `==` is Equatable, every hashable one\n#       Hashable, every ordered one Comparable. Nothing implements them by hand.\n#\n#==============================================================================================\n\nimport io\n\n## Implemented by every type with `==`.\npub interface Equatable:\n    func equals(other: void*) -> bool\n\n## Implemented by every hashable type: `value.hash()` (\302\2477.4).\npub interface Hashable:\n    func hash() -> u64\n\n## Implemented by every ordered type.\npub interface Comparable:\n    func compare(other: void*) -> i64\n\n## The protocols `for` consumes (\302\2478.3, \302\24714.4): a value iterator answers each element\n## until `none`; an iterable answers a fresh iterator of its own concrete type.\npub interface Iterator[T]:\n    func next() -> T\?\n\n## A type a `for` loop can walk: it yields an iterator of `T` (\302\24713.3).\npub interface Iterable[T, I: Iterator[T]]:\n    func iterator() -> I\n\n## A value that writes itself to a sink (\302\24714.4); formatted strings call it for each field.\npub interface Display:\n    func display(sink: io.Writer) -> !\n\n## The source file of the use site; the backend replaces it (\302\2479.1).\npub let file: str = \"\"\n## The source line of the use site; the backend replaces it (\302\2479.1).\npub let line: u32 = 0\n## The enclosing function of the use site; the backend replaces it (\302\2479.1).\npub let function: str = \"\"\n## The use site's file, line and function together (\302\2479.1).\npub let location: io.Location = io.Location(file = \"\", line = 0, function = \"\")\n", 1697};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_13 = {"#==============================================================================================\n#\n#   atomic - Memory orderings and fences for `@T` operations\n#\n#   DESCRIPTION:\n#       Memory orderings for the operations of `@T` (\302\24715.1).\n#\n#==============================================================================================\n\n## The memory ordering of an `@T` operation.\npub enum Ordering as u8:\n    relaxed = 1\n    acquire = 2\n    release = 3\n    acq_rel = 4\n    seq_cst = 5\n    ## A fence's alone: the compiler moves no memory access across it, and the processor is\n    ## told nothing, what a signal handler sharing data with the code it interrupts needs.\n    signal = 6\n\n## A standalone fence; the backend supplies the instruction.\npub func fence(order: Ordering):\n    _ = order\n", 796};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_14 = {"#==============================================================================================\n#\n#   time - Monotonic and wall-clock time\n#\n#   DESCRIPTION:\n#       A monotonic clock that never goes backwards, and the wall clock as seconds since the\n#       Unix epoch, over the host's `clock_gettime`.\n#\n#==============================================================================================\n\nimport c\nimport platform\nextern func clock_gettime(clock: i32, out_time: Stamp*) -> i32\nextern func c_time as \"time\"(out_time: void*\?) -> i64\n\n## `struct timespec`: `tv_nsec` is a C `long`, four bytes on Windows.\nextern struct Stamp:\n    seconds: i64\n    nanoseconds: c.long\n\n## `CLOCK_MONOTONIC`: 6 on macOS, 1 on Linux; `CLOCK_REALTIME` is 0 on both.\nlet monotonic: i32 = 6 if platform.macos else 1\nlet realtime: i32 = 0\n\n## The clock read into `stamp`: the monotonic one or the wall clock.\nfunc read_clock(monotonic_clock: bool, stamp: Stamp*) -> i32:\n    return clock_gettime(monotonic if monotonic_clock else realtime, stamp)\n\n## Nanoseconds from an arbitrary origin, never going backwards.\npub func now() -> u64:\n    var stamp = Stamp(seconds = 0, nanoseconds = 0)\n    _ = read_clock(true, &stamp)\n    return (u64)stamp.seconds * 1000000000 + (u64)stamp.nanoseconds\n\n## Seconds since the Unix epoch.\npub func unix() -> i64:\n    return c_time(none)\n\n## Nanoseconds elapsed since `start`, from `now()`.\npub func since(start: u64) -> u64:\n    let current = now()\n    return current - start if current > start else 0\n", 1522};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_15 = {"#==============================================================================================\n#\n#   thread - Native threads\n#\n#   DESCRIPTION:\n#       Spawning, joining and detaching host threads over pthreads (Windows through its own\n#       primitives), with the running thread's identity and yielding and sleeping.\n#\n#==============================================================================================\n\nfrom windows_abi import Sleep\nimport c\nimport core\nimport memory\nimport platform\nimport time\nextern func pthread_create(thread: void*\?*, attributes: void*\?, start: func(void*) -> void*\?, argument: void*) -> i32\nextern func pthread_join(thread: void*, result: void*\?*\?) -> i32\nextern func pthread_detach(thread: void*) -> i32\nextern func pthread_self() -> void*\nextern func pthread_main_np() -> i32\nextern func getpid() -> i32\nextern func gettid() -> i32\nextern func pthread_attr_init(attributes: void*) -> i32\nextern func pthread_attr_setstacksize(attributes: void*, size: usize) -> i32\nextern func pthread_attr_destroy(attributes: void*) -> i32\n## macOS names the calling thread; Linux names one by handle. Both cap a name at 15 bytes.\nextern func mac_setname as \"pthread_setname_np\"(name: c.str) -> i32\nextern func linux_setname as \"pthread_setname_np\"(thread: void*, name: c.str) -> i32\nextern func sched_yield() -> i32\nextern func nanosleep(request: const Duration*, remaining: Duration*\?) -> i32\n\n## `struct timespec`: `tv_nsec` is a C `long`, four bytes on Windows.\nextern struct Duration:\n    seconds: i64\n    nanoseconds: c.long\n\n## A thread operation the operating system refused.\n# mark: Threads ===============================================================================\n\n## A thread operation failed.\npub let failed: ErrorCode = ErrorCode.package(5)\n\n## `PTHREAD_STACK_MIN`: 16 KiB on macOS and x86-64 glibc; a smaller stack is raised to it.\nlet least_stack: usize = 16384\n## The stack of a thread spawned without a size: 8 MiB on every host, the main thread's\n## on Linux, where macOS gives a new thread 512 KiB and Windows 1 MiB. A program may set\n## it before it spawns; `spawn(..., stack = n)` overrides it for one thread.\npub var default_stack: usize = 8388608\n## The longest name a thread may carry, with its NUL.\nlet name_room: usize = 16\n## What gives a new thread's `local var`s their initialisers (\302\2476.3), run before its entry.\n## The native backend's startup sets it when the program has such initialisers, since its\n## thread-local storage starts zeroed; under C, `_Thread_local` storage starts initialised\n## and it stays none.\npub var locals_start: (func() -> unit)\?\n\n## A running thread; the zero value is no thread at all, so arrays of handles exist.\npub struct Handle:\n    var id: void*\?\n\n    ## Wait for the thread to finish.\n    pub func join() -> !:\n        let id = self.id else error(failed, \"no thread to join\")\n        if pthread_join(id, none) != 0:\n            error(failed, \"join\")\n\n    ## Let the thread run on its own; its resources are reclaimed at exit.\n    pub func detach():\n        let id = self.id else return\n        _ = pthread_detach(id)\n\n## What a new thread starts with: the entry, its context, its name in a heap block of\n## `name_room` bytes, NUL-terminated, and the allocator rule of \302\24715.3.\nstruct Start:\n    var entry: func(void*\?) -> unit\n    var context: void*\?\n    var name: u8[]\n    var name_length: usize\n\nfunc trampoline(raw: void*) -> void*\?:\n    let start = (Start*)raw\n    if let initialise = locals_start:\n        initialise()\n    memory.allocator = memory.heap\n    let entry = start.entry\n    let context = start.context\n    if start.name_length > 0:\n        let text = (c.str)(str)start.name[..<start.name_length]\n        if platform.macos:\n            _ = mac_setname(text)\n        else:\n            _ = linux_setname(pthread_self(), text)\n    release_start(start)\n    entry(context)\n    return none\n\n## Free what `spawn` handed the new thread: the start record and its copy of the name.\nfunc release_start(start: Start*):\n    free(start.name) in memory.heap\n    free(start) in memory.heap\n\n## Start a thread running `entry(context)`. `stack` is its stack in bytes, `default_stack`\n## when 0, at least `PTHREAD_STACK_MIN` and whole pages; `name` is what the host's tools\n## show for it, its first fifteen bytes.\npub func spawn(entry: func(void*\?) -> unit, context: void*\?, stack: usize = 0, name: str = \"\") -> Handle!:\n    let copy = try new u8[name_room] --- in memory.heap\n    # on success the thread owns both, and `trampoline` frees them\n    errdefer free(copy) in memory.heap\n    let kept = name.length if name.length < name_room - 1 else name_room - 1\n    memory.copy(copy, name.bytes, kept)\n    copy[kept] = 0\n    let start = new Start(entry = entry, context = context, name = copy, name_length = kept) in memory.heap catch failure:\n        error(memory.exhausted, \"memory.exhausted\")\n    errdefer free(start) in memory.heap\n    var attributes: u64[16]\n    if pthread_attr_init((void*)&attributes[0]) != 0:\n        error(failed, \"spawn\")\n    let wanted = stack if stack > 0 else default_stack\n    let page = memory.page_size()\n    var size = wanted if wanted > least_stack else least_stack\n    size = (size + page - 1) // page * page\n    if pthread_attr_setstacksize((void*)&attributes[0], size) != 0:\n        _ = pthread_attr_destroy((void*)&attributes[0])\n        error(failed, \"the stack size is refused\")\n    var id: void*\? = none\n    let created = pthread_create(&id, (void*)&attributes[0], trampoline, (void*)start)\n    _ = pthread_attr_destroy((void*)&attributes[0])\n    if created != 0:\n        error(failed, \"spawn\")\n    let thread = id else error(failed, \"spawn\")\n    return Handle(id = thread)\n\n## A handle to the calling thread.\npub func current() -> Handle:\n    return Handle(id = pthread_self())\n\n## Whether this is the process's initial thread, for main-thread native resources.\npub func is_main() -> bool:\n    if platform.windows:\n        return core.on_initial_thread()\n    if platform.macos:\n        return pthread_main_np() != 0\n    if platform.linux:\n        return gettid() == getpid()\n    return false\n\n## A hint to the processor inside a spin loop.\npub func pause():\n    asm arm64:\n        yield\n    asm x86_64:\n        pause\n\n## Yield the processor to another runnable thread.\npub func yield():\n    _ = sched_yield()\n\n## Sleep for at least `milliseconds`: a signal that interrupts the sleep leaves the time\n## remaining, which is slept again.\npub func sleep(milliseconds: u64):\n    if platform.windows:\n        sleep_windows(milliseconds)\n        return\n    var request = Duration(seconds = (i64)(milliseconds // 1000), nanoseconds = (c.long)((i64)(milliseconds % 1000) * 1000000))\n    var remaining = Duration(seconds = 0, nanoseconds = 0)\n    while nanosleep(&request, &remaining) != 0 and c.errno() == c.interrupted:\n        request = remaining\n\n## Windows rounds waits to clock ticks and may wake before the requested interval.\n## Recheck a monotonic deadline without changing system-wide timer resolution. A\n## finite chunk also avoids narrowing long durations to Sleep's INFINITE sentinel.\nfunc sleep_windows(milliseconds: u64):\n    if milliseconds == 0:\n        Sleep(0)\n        return\n    let longest_finite_wait: u64 = 0xFFFFFFFE\n    let start = time.now()\n    var elapsed: u64 = 0\n    while elapsed < milliseconds:\n        let remaining = milliseconds - elapsed\n        Sleep((u32)(remaining if remaining < longest_finite_wait else longest_finite_wait))\n        elapsed = time.since(start) // 1000000\n", 7535};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_16 = {"#==============================================================================================\n#\n#   sync - Locks, conditions, once and semaphores\n#\n#   DESCRIPTION:\n#       Blocking synchronisation over the host's futex-like wait and wake: a mutex, a condition\n#       variable, a run-once gate, and a counting semaphore.\n#\n#==============================================================================================\n\nimport platform\n\n## macOS: the `ulock` calls libSystem builds its own locks on.\nextern func __ulock_wait(operation: u32, address: void*, value: u64, timeout: u32) -> i32\nextern func __ulock_wake(operation: u32, address: void*, wake_value: u64) -> i32\n## Linux: the futex system call, through `syscall`; the number is the architecture's.\nextern func syscall(number: i64, ...) -> i64\nextern func WaitOnAddress(address: void*, comparison: u32*, size: usize, milliseconds: u32) -> i32\nextern func WakeByAddressSingle(address: void*)\nextern func WakeByAddressAll(address: void*)\n\nlet compare_and_wait: u32 = 1\nlet wake_all: u32 = 256\nlet futex_number: i64 = 98 if platform.arm64 else 202\nlet futex_wait_private: i32 = 128\nlet futex_wake_private: i32 = 129\n\n## Sleep in the kernel while the word at `address` still holds `value`; a change\n## or a wake returns, and so may nothing at all, so every caller loops.\nfunc sleep_on(address: void*, value: u32):\n    if platform.windows:\n        var expected = value\n        _ = WaitOnAddress(address, &expected, 4, 4294967295)\n    elif platform.macos:\n        _ = __ulock_wait(compare_and_wait, address, (u64)value, 0)\n    else:\n        let no_timeout: void*\? = none\n        _ = syscall(futex_number, address, futex_wait_private, value, no_timeout)\n\n## `sleep_on`, giving up after about `milliseconds`: a timeout, a change, a wake or nothing\n## at all return, so every caller loops against its own deadline.\nfunc sleep_on_for(address: void*, value: u32, milliseconds: u64):\n    if milliseconds == 0:\n        return\n    if platform.windows:\n        var expected = value\n        _ = WaitOnAddress(address, &expected, 4, (u32)(milliseconds if milliseconds < 4294967294 else 4294967294))\n    elif platform.macos:\n        # microseconds, where 0 would wait for ever\n        let micros = milliseconds *\? 1000 else 4294967295\n        _ = __ulock_wait(compare_and_wait, address, (u64)value, (u32)(micros if micros < 4294967295 else 4294967295))\n    else:\n        var timeout = Timeout(seconds = (i64)(milliseconds // 1000), nanoseconds = (i64)(milliseconds % 1000) * 1000000)\n        _ = syscall(futex_number, address, futex_wait_private, value, &timeout)\n\n## A relative `timespec` for the futex call.\nextern struct Timeout:\n    seconds: i64\n    nanoseconds: i64\n\nfunc wake_one(address: void*):\n    if platform.windows:\n        WakeByAddressSingle(address)\n    elif platform.macos:\n        _ = __ulock_wake(compare_and_wait, address, 0)\n    else:\n        _ = syscall(futex_number, address, futex_wake_private, 1)\n\nfunc wake_every(address: void*):\n    if platform.windows:\n        WakeByAddressAll(address)\n    elif platform.macos:\n        _ = __ulock_wake(compare_and_wait | wake_all, address, 0)\n    else:\n        _ = syscall(futex_number, address, futex_wake_private, 2147483647)\n\n## A lock whose waiters sleep: zero is unlocked, so `var lock: Mutex` is ready to\n## use; one is locked; two is locked with someone asleep on it.\n## A mutual-exclusion lock; a waiter sleeps until it is free.\npub struct Mutex:\n    var state: @u32\n\n    ## Acquire the lock, blocking until it is free.\n    pub func lock():\n        let (taken, seen) = self.state.cas(0, 1, .acquire, .relaxed)\n        if taken:\n            return\n        var current = seen\n        if current != 2:\n            current = self.state.swap(2, .acquire)\n        while current != 0:\n            sleep_on((void*)&self.state, 2)\n            current = self.state.swap(2, .acquire)\n\n    ## Release the lock and wake one waiter.\n    pub func unlock():\n        if self.state.swap(0, .release) == 2:\n            wake_one((void*)&self.state)\n\n    ## Acquire the lock without blocking; whether it was taken.\n    pub func try_lock() -> bool:\n        let (taken, seen) = self.state.cas(0, 1, .acquire, .relaxed)\n        _ = seen\n        return taken\n\n## A sequence number waiters watch; every signal advances it and wakes.\n## A condition variable: waiters sleep until signalled.\npub struct Condition:\n    var sequence: @u32\n\n    ## Release `mutex`, sleep until signalled, then reacquire it.\n    pub func wait(mutex: Mutex*):\n        let seen = self.sequence.load(.acquire)\n        mutex.unlock()\n        sleep_on((void*)&self.sequence, seen)\n        mutex.lock()\n\n    ## `wait`, giving up after about `milliseconds`; it may also return early, without a\n    ## signal, so a caller rechecks its condition against its own deadline.\n    pub func wait_for(mutex: Mutex*, milliseconds: u64):\n        let seen = self.sequence.load(.acquire)\n        mutex.unlock()\n        sleep_on_for((void*)&self.sequence, seen, milliseconds)\n        mutex.lock()\n\n    ## Wake one waiter.\n    pub func signal():\n        _ = self.sequence.add(1, .release)\n        wake_one((void*)&self.sequence)\n\n    ## Wake every waiter.\n    pub func broadcast():\n        _ = self.sequence.add(1, .release)\n        wake_every((void*)&self.sequence)\n\n## Runs its function exactly once; later callers wait for the first to finish.\n## Runs a function exactly once; later callers wait for the first.\npub struct Once:\n    var state: @u32\n\n    ## Run `function` on the first call; later calls wait for it to finish.\n    pub func run(function: func() -> unit):\n        let (first, seen) = self.state.cas(0, 1, .acq_rel, .acquire)\n        _ = seen\n        if first:\n            function()\n            self.state.store(2, .release)\n            wake_every((void*)&self.state)\n            return\n        while self.state.load(.acquire) != 2:\n            sleep_on((void*)&self.state, 1)\n\n## A counting semaphore whose waiters sleep.\n## A counting semaphore whose waiters sleep.\npub struct Semaphore:\n    var count: @u32\n\n    ## Take one permit, blocking until one is available.\n    pub func acquire():\n        while true:\n            let n = self.count.load(.acquire)\n            if n > 0:\n                let (taken, seen) = self.count.cas(n, n - 1, .acq_rel, .relaxed)\n                _ = seen\n                if taken:\n                    return\n            else:\n                sleep_on((void*)&self.count, 0)\n\n    ## Return one permit and wake one waiter.\n    pub func release():\n        _ = self.count.add(1, .release)\n        wake_one((void*)&self.count)\n\n# mark: Cancellation ========================================================================\n\n## A one-way cancellation signal shared by reference. Zero is not requested.\n## Keep this object alive until every waiting thread returns; do not copy or reset\n## it while shared. Requests use release/acquire synchronization.\npub struct Cancellation:\n    var requested: @u32\n\n    ## Request cancellation.\n    pub func request():\n        self.requested.store(1, .release)\n\n    ## Whether cancellation was requested.\n    pub func is_requested() -> bool:\n        return self.requested.load(.acquire) != 0\n", 7208};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_17 = {"#==============================================================================================\n#\n#   ownership - Intrusive ownership shared by Base and Luce\n#\n#   DESCRIPTION:\n#       Intrusive ownership shared by Base libraries and compiled Luce programs. Base callers\n#       retain and release explicitly; Luce inserts those operations. One header and trace\n#       protocol cover native/managed cycles on the owning thread. Runtime allocations use the\n#       system heap; an explicit allocator can be supplied to reserve when its lifetime is\n#       guaranteed by the native owner.\n#\n#==============================================================================================\n\nimport c\nimport io\nimport memory\nimport core\n\n# mark: Objects ================================================================================\n\nlet black: u8 = 0\nlet gray: u8 = 1\nlet white: u8 = 2\nlet purple: u8 = 3\nlet color_mask: u8 = 3\nlet buffered: u8 = 4\nlet dead: u8 = 8\nlet collecting: u8 = 16\n## A literal's text: never counted, never released, never alive at the end.\npub let immortal: u8 = 32\n## An object whose `init` failed, while `abandon` releases its fields: a release of it is\n## bookkeeping only and the collector never walks into it.\nlet abandoning: u8 = 64\n\n## The ownership header every managed object carries, before its fields.\npub struct Object:\n    ## The strong reference count; the object is finalized when it reaches zero.\n    pub var strong: u32\n    ## The number of weak references watching the object.\n    pub var weak: u32\n    ## The collector's color and state bits (\302\247the cycle collector).\n    pub var flags: u8\n    ## The object's class description.\n    pub var info: Info*\n    ## Allocation identity never repeats, even when an allocator reuses an address.\n    pub var generation: u64\n    ## The owning context the object belongs to.\n    pub var context: u64\n    ## The size of the object's allocation in bytes.\n    pub var allocation_size: usize\n    ## The allocator that made the object, when one was supplied explicitly.\n    pub var allocator: memory.Allocator\?\n\n## What the collector and the destructor need to know about a class.\npub struct Info:\n    ## The class name, for diagnostics and the collector.\n    pub var name: str\n    ## The object's size in bytes, its fields included.\n    pub var size: usize\n    ## `deinit`, when the class declares one.\n    pub var finish: (func(Object*) -> unit)\?\n    ## Releases the fields in reverse declaration order, tolerating unassigned ones.\n    pub var drop: func(Object*) -> unit\n    ## Visits every strong reference the object holds, fields in declaration order.\n    pub var trace: func(Object*, func(Object*, void*) -> unit, void*) -> unit\n    ## An interface adapter preserves the identity of its concrete owner.\n    pub var identity: (func(Object*) -> u64)\? = none\n    ## No object of this type can be part of a reference cycle (text, a list of numbers, a\n    ## class whose fields are all such): the collector never takes one as a candidate nor\n    ## walks into one, so large acyclic data costs it nothing.\n    pub var acyclic: bool = false\n\n## Objects alive: allocated and not yet destroyed.\nlocal var live: usize = 0\n\n## Allocated objects not yet finalized on the calling runtime thread.\npub func live_count() -> usize:\n    return live\n\n## Where the thread's program is: `file:line:column` of the Luce statement running, set by\n## the compiled code before each statement and restored when a function returns; what a\n## trap names (\302\24712.4).\npub local var site: str\n\n## The caller's site again, deferred by every function the compiler writes.\npub func restore_site(saved: str):\n    site = saved\n\n## Stop the program with `trap: file:line:column: message` on standard error and status 1.\npub func stop(message: str) -> never:\n    core.trap_located(site, message)\n\nfunc color_of(o: Object*) -> u8:\n    return o.flags & color_mask\n\nfunc set_color(o: Object*, color: u8):\n    o.flags = (o.flags & ~color_mask) | color\n\nfunc has(o: Object*, flag: u8) -> bool:\n    return (o.flags & flag) != 0\n\nvar next_context: @u64 = 1\nvar next_generation: @u64 = 1\nlocal var thread_context: u64 = 0\nlocal var runtime_depth: u32 = 0\n\n## A unique runtime identity for this thread, independent of recycled OS thread IDs.\npub func context_id() -> u64:\n    if thread_context == 0:\n        thread_context = next_context.add(1, .relaxed)\n        if thread_context == 0:\n            stop(\"runtime context identity exhausted\")\n    return thread_context\n\n## Application runtime entry is separate from ordinary manual Base ownership.\n## Generated callbacks require entry; native worker adapters establish it internally.\npub func enter():\n    _ = context_id()\n    runtime_depth += 1\n\n## Trap when no owning context has been entered.\npub func require_context():\n    if runtime_depth == 0:\n        stop(\"a managed callback needs a runtime entry on this thread\")\n\n## Trap when `o` is touched from a thread other than its owner.\npub func check_thread(o: Object*):\n    if not has(o, immortal) and o.context != context_id():\n        stop(\"an object belongs to another runtime thread\")\n\n## Trap when `o` has already been finalized.\npub func check_alive(o: Object*):\n    check_thread(o)\n    if has(o, dead) or o.strong == 0:\n        stop(\"an object has already been destroyed\")\n\n## Reserve unpublished storage. The caller supplies a stable descriptor before\n## publishing the object and abandons the storage if native initialization fails.\npub func reserve(info: Info*, size: usize, allocator: memory.Allocator\? = none) -> Object*!:\n    if size < memory.size_of(Object):\n        stop(\"an object allocation is smaller than its header\")\n    let selected = allocator else memory.heap\n    let block = selected.allocate(size, 16) else error(memory.exhausted, \"memory.exhausted\")\n    memory.set(block, 0)\n    let o = (Object*)block.data\n    o.strong = 1\n    o.info = info\n    o.context = context_id()\n    o.generation = next_generation.add(1, .relaxed)\n    if o.generation == 0:\n        stop(\"object allocation identity exhausted\")\n    o.allocation_size = block.length\n    o.allocator = selected\n    live += 1\n    return o\n\n## Allocate an object of class `info` and its header.\npub func allocate(info: Info*) -> Object*:\n    return allocate_sized(info, info.size)\n\n## Runtime wrapper/text allocation retains Luce's trap-on-exhaustion policy.\npub func allocate_sized(info: Info*, size: usize) -> Object*:\n    return reserve(info, size) catch failure:\n        trap(\"out of memory\")\n\n## Add a strong reference to `o` and return it.\npub func retain(o: Object*) -> Object*:\n    check_alive(o)\n    if has(o, immortal):\n        return o\n    o.strong += 1\n    set_color(o, black)\n    return o\n\n## Drop a strong reference to `o`, finalizing it when the count reaches zero.\npub func release(o: Object*):\n    check_thread(o)\n    if has(o, immortal):\n        return\n    if has(o, collecting) or has(o, abandoning):\n        # a white object's field, released while the collector drops it, or a reference\n        # back to an object `abandon` is dropping: the count is bookkeeping only, the\n        # collector or `abandon` frees the object\n        if o.strong > 0:\n            o.strong -= 1\n        return\n    check_alive(o)\n    o.strong -= 1\n    if o.strong == 0:\n        destroy(o)\n    elif not o.info.acyclic:\n        possible_root(o)\n\n## `deinit`, then the fields, then the storage unless a weak reference keeps the shell.\nfunc destroy(o: Object*):\n    set_color(o, black)\n    if let f = o.info.finish:\n        o.strong = 1\n        f(o)\n        if o.strong != 1:\n            trap(\"`deinit` published `self`\")\n        o.strong = 0\n    o.info.drop(o)\n    live -= 1\n    o.flags |= dead\n    if not has(o, buffered):\n        release_shell(o)\n\n## The storage goes when nothing, strong or weak or the candidate buffer, refers to it.\nfunc release_shell(o: Object*):\n    if o.weak == 0 and has(o, dead) and not has(o, buffered):\n        let allocator = o.allocator else stop(\"an object has no allocation owner\")\n        let block = u8[]((u8*)o, o.allocation_size)\n        free(block) in allocator\n\n## Free unpublished storage without invoking the successful object's cleanup.\n## The native initializer owns cleanup of its partially acquired resources.\npub func discard_unpublished(o: Object*):\n    check_alive(o)\n    if o.strong != 1 or o.weak != 0 or has(o, buffered):\n        stop(\"an incomplete object was published\")\n    live -= 1\n    o.strong = 0\n    o.flags |= dead\n    release_shell(o)\n\n## An `init` that failed: the fields assigned so far go, no `deinit` runs. Like `destroy`,\n## the object leaves the collector's candidates first, so a collection the drop sets off\n## never walks fields already released. What the fields held that refers back to the\n## object, a closure over `self` or a child holding its parent, lets go of it in the drop;\n## a reference still held after that was published by the failed `init`, which stops the\n## program rather than leave it pointing at freed storage.\npub func abandon(o: Object*):\n    check_alive(o)\n    set_color(o, black)\n    o.flags |= abandoning\n    o.info.drop(o)\n    o.flags &= ~abandoning\n    if o.strong != 1:\n        stop(\"a failed `init` published `self`\")\n    live -= 1\n    o.strong = 0\n    o.flags |= dead\n    if not has(o, buffered):\n        release_shell(o)\n\n## The allocation identity, or the concrete owner's identity through an adapter.\npub func identity(object: Object*) -> u64:\n    check_alive(object)\n    if let resolve = object.info.identity:\n        return resolve(object)\n    return object.generation\n", 9584};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_18 = {"#==============================================================================================\n#\n#   pool - The temporaries pool\n#\n#   DESCRIPTION:\n#       Owned values handed on as temporaries, released together by the next `drain`; the\n#       generators emit `mark`/`drain` pairs around a statement's operands.\n#\n#==============================================================================================\n\n# mark: The temporaries pool ===================================================================\n\nstruct Pending:\n    var object: Object*\?\n    var cell: void*\?\n    var drop: (func(void*) -> unit)\?\n    var size: usize\n\nlocal var pending: Pending[]\nlocal var pending_count: usize = 0\n\n## The current pool position, to `drain` back to later.\npub func mark() -> usize:\n    return pending_count\n\nfunc push_pending(p: Pending):\n    if pending_count == pending.length:\n        pending = grow(pending, pending_count, 64)\n    pending[pending_count] = p\n    pending_count += 1\n\n## An owned object handed on as a temporary: released by the next `drain`.\npub func pool_object(o: Object*) -> Object*:\n    push_pending(Pending(object = o, cell = none, drop = none, size = 0))\n    return o\n\n## An owned value of any type handed on as a temporary; `drop` releases what it holds.\npub func pool_value[T](v: T, drop: func(void*) -> unit) -> T:\n    let block = memory.heap.allocate(memory.size_of(T), memory.align_of(T)) else trap(\"out of memory\")\n    memory.write[T](block.data, v)\n    push_pending(Pending(object = none, cell = block.data, drop = drop, size = memory.size_of(T)))\n    return v\n\n## Releases every temporary pooled since `mark`, in the order they were pooled.\npub func drain(since: usize):\n    if pending_count <= since:\n        return\n    let count = pending_count\n    var i = since\n    while i < count:\n        let p = pending[i]\n        if let o = p.object:\n            release(o)\n        elif let cell = p.cell:\n            if let d = p.drop:\n                d(cell)\n            release_cell(cell, p.size)\n        i += 1\n    # a release pools nothing of its own, so nothing was added above `count`\n    pending_count = since\n\n## Free a pooled value's block of `size` bytes, which `pool_value` took from the heap.\nfunc release_cell(cell: void*, size: usize):\n    free(u8[]((u8*)cell, size)) in memory.heap\n\n## `items` in heap storage with room for twice as many (`least` when it had none), its\n## first `count` kept and its old storage freed: the growth of the runtime's own lists.\n## Out of memory traps, as the bookkeeping has no failure to report into.\nfunc grow[T](items: T[], count: usize, least: usize) -> T[]:\n    let grown = new T[items.length * 2 if items.length > 0 else least] --- in memory.heap catch failure:\n        trap(\"out of memory\")\n    for i in 0..<count:\n        grown[i] = items[i]\n    if items.length > 0:\n        free(items) in memory.heap\n    return grown\n", 2893};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_19 = {"#==============================================================================================\n#\n#   cycles - The cycle collector\n#\n#   DESCRIPTION:\n#       A synchronous trial-deletion collector for reference cycles on the owning thread,\n#       run when the candidate set fills or at the end of a run. An object whose type is\n#       acyclic is never a candidate and never walked into: it cannot be part of a cycle,\n#       and every visitor skipping it keeps the trial counts balanced.\n#\n#==============================================================================================\n\n# mark: The cycle collector ====================================================================\npub let candidate_limit: usize = 1024\nlocal var roots: Object*[]\nlocal var root_count: usize = 0\nlocal var whites: Object*[]\nlocal var white_count: usize = 0\nlocal var collector_running: bool = false\n## `LUCE_CYCLE_STRESS` in the environment: 0 not read yet, 1 absent, 2 present.\nvar stress_state: @u8\nextern func stress_getenv as \"getenv\"(name: c.str) -> c.str\?\n\n## Whether `LUCE_CYCLE_STRESS` is set: the collector then runs at every new candidate, so a\n## collection happens at every release that could leave a cycle, in `clear`, `remove`, a\n## `deinit` and a failed `init` too (the stress mode of luce's tools/cycles_fuzz.py). The\n## environment is read once; every thread reads the same answer.\nfunc stressed() -> bool:\n    var state = stress_state.load(.relaxed)\n    if state == 0:\n        state = 2 if stress_getenv(\"LUCE_CYCLE_STRESS\") != none else 1\n        stress_state.store(state, .relaxed)\n    return state == 2\n\nfunc push_root(o: Object*):\n    if root_count == roots.length:\n        roots = grow(roots, root_count, candidate_limit)\n    roots[root_count] = o\n    root_count += 1\n\nfunc push_white(o: Object*):\n    if white_count == whites.length:\n        whites = grow(whites, white_count, 256)\n    whites[white_count] = o\n    white_count += 1\n\nfunc possible_root(o: Object*):\n    if color_of(o) != purple:\n        set_color(o, purple)\n        if not has(o, buffered):\n            o.flags |= buffered\n            push_root(o)\n            if (root_count >= candidate_limit or stressed()) and not collector_running:\n                collect()\n\n## An object no walk enters: a literal, an acyclic one, or one `abandon` is dropping.\nfunc skipped(child: Object*) -> bool:\n    return has(child, immortal) or child.info.acyclic or has(child, abandoning)\n\nfunc visit_mark_gray(child: Object*, context: void*):\n    if skipped(child):\n        return\n    check_thread(child)\n    child.strong -= 1\n    mark_gray(child)\n\nfunc mark_gray(o: Object*):\n    if color_of(o) != gray:\n        set_color(o, gray)\n        o.info.trace(o, visit_mark_gray, (void*)o)\n\nfunc visit_scan(child: Object*, context: void*):\n    if skipped(child):\n        return\n    check_thread(child)\n    scan(child)\n\nfunc visit_scan_black(child: Object*, context: void*):\n    if skipped(child):\n        return\n    check_thread(child)\n    child.strong += 1\n    if color_of(child) != black:\n        scan_black(child)\n\nfunc scan(o: Object*):\n    if color_of(o) == gray:\n        if o.strong > 0:\n            scan_black(o)\n        else:\n            set_color(o, white)\n            o.info.trace(o, visit_scan, (void*)o)\n\nfunc scan_black(o: Object*):\n    set_color(o, black)\n    o.info.trace(o, visit_scan_black, (void*)o)\n\nfunc visit_gather(child: Object*, context: void*):\n    if skipped(child):\n        return\n    check_thread(child)\n    gather(child)\n\n## The white objects, each once, flagged as being collected (`sort_whites` orders them).\nfunc gather(o: Object*):\n    if color_of(o) == white and not has(o, collecting):\n        o.flags |= collecting\n        push_white(o)\n        o.info.trace(o, visit_gather, (void*)o)\n\n## Undo the trial deletion of one edge out of a garbage object. `mark_gray` took one count\n## for every edge it walked; `scan_black` gave back those out of objects found reachable, but\n## an edge out of garbage is still missing, whether it points at more garbage or at a live\n## object. Restoring every one lets each field release below be an ordinary release: a live\n## object loses exactly the reference the garbage held, where it once lost two.\nfunc visit_restore(child: Object*, context: void*):\n    if skipped(child):\n        return\n    check_thread(child)\n    child.strong += 1\n\n## The garbage in the order its objects were made, oldest first (their generations): what a\n## cycle's deinits and the releases of its fields follow, the same in a compiled program and\n## Luce's interpreter whatever let go of what when (a heap sort, in place).\nfunc sort_whites():\n    var start = white_count // 2\n    while start > 0:\n        start -= 1\n        sift_white(start, white_count)\n    var end = white_count\n    while end > 1:\n        end -= 1\n        let top = whites[0]\n        whites[0] = whites[end]\n        whites[end] = top\n        sift_white(0, end)\n\nfunc sift_white(first: usize, end: usize):\n    var root = first\n    while root * 2 + 1 < end:\n        var child = root * 2 + 1\n        if child + 1 < end and whites[child + 1].generation > whites[child].generation:\n            child += 1\n        if whites[root].generation >= whites[child].generation:\n            return\n        let held = whites[root]\n        whites[root] = whites[child]\n        whites[child] = held\n        root = child\n\n## Free the garbage: deinits first, then every object's fields, then the storage.\npub func collect():\n    if collector_running:\n        return\n    collector_running = true\n    # candidates still purple and alive stay; the rest leave the buffer\n    var kept: usize = 0\n    var i: usize = 0\n    while i < root_count:\n        let o = roots[i]\n        if color_of(o) == purple and o.strong > 0 and not has(o, dead):\n            roots[kept] = o\n            kept += 1\n        else:\n            o.flags &= ~buffered\n            release_shell(o)\n        i += 1\n    root_count = kept\n    i = 0\n    while i < root_count:\n        mark_gray(roots[i])\n        i += 1\n    i = 0\n    while i < root_count:\n        scan(roots[i])\n        i += 1\n    white_count = 0\n    i = 0\n    while i < root_count:\n        gather(roots[i])\n        i += 1\n    i = 0\n    while i < root_count:\n        roots[i].flags &= ~buffered\n        i += 1\n    root_count = 0\n    sort_whites()\n    # the counts the trial deletion took for the garbage's edges are restored, to garbage and\n    # to live objects alike, so that every field release below is an ordinary one; a release\n    # of a white object then only lowers its count\n    i = 0\n    while i < white_count:\n        whites[i].info.trace(whites[i], visit_restore, (void*)whites[i])\n        i += 1\n    i = 0\n    while i < white_count:\n        let o = whites[i]\n        if let f = o.info.finish:\n            let before = o.strong\n            o.strong += 1\n            f(o)\n            if o.strong > before + 1:\n                trap(\"`deinit` published `self`\")\n            # Native disposal may release edges, including an edge to itself.\n            # Remove only the temporary finalizer reference, preserving those drops.\n            o.strong -= 1\n        i += 1\n    i = 0\n    while i < white_count:\n        whites[i].info.drop(whites[i])\n        i += 1\n    i = 0\n    while i < white_count:\n        let o = whites[i]\n        live -= 1\n        o.strong = 0\n        o.flags = dead\n        release_shell(o)\n        i += 1\n    white_count = 0\n    collector_running = false\n", 7448};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_20 = {"#==============================================================================================\n#\n#   weak - Weak references\n#\n#   DESCRIPTION:\n#       A weak reference watches an object without keeping it alive, and yields it again only\n#       while it is still alive.\n#\n#==============================================================================================\n\n# mark: Weak references ========================================================================\n## A weak reference: it watches an object without keeping it alive.\npub struct Weak:\n    ## The watched object, or none once it is gone.\n    pub var target: Object*\?\n\n## A weak reference watching `o`.\npub func weak_make(o: Object*) -> Weak:\n    check_alive(o)\n    if not has(o, immortal):\n        o.weak += 1\n    return Weak(target = o)\n\n## A copy of `w`, counting one more watcher of its object.\npub func weak_copy(w: Weak) -> Weak:\n    if let o = w.target:\n        check_thread(o)\n        if not has(o, immortal):\n            o.weak += 1\n    return w\n\n## Drop `w`; the object's shell is freed when its last watcher goes.\npub func weak_drop(w: Weak):\n    if let o = w.target:\n        check_thread(o)\n        if not has(o, immortal):\n            o.weak -= 1\n            release_shell(o)\n\n## The object with a fresh strong reference, or none once it is dead.\npub func weak_get(w: Weak) -> Object*\?:\n    if let o = w.target:\n        check_thread(o)\n        if not has(o, dead):\n            return retain(o)\n    return none\n", 1488};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_21 = {"#==============================================================================================\n#\n#   lifecycle - The end of a run\n#\n#   DESCRIPTION:\n#       After `main` and after each worker, the collector runs and anything still alive is a\n#       defect that stops the program.\n#\n#==============================================================================================\n\n# mark: The end of a run =======================================================================\n\nimport strings\n\n## After `main`: the collector runs, and anything still alive is a defect. The exit status.\npub func finish_run(status: i32) -> i32:\n    drain(0)\n    settle()\n    if live != 0:\n        var room: u8[96]\n        let text = strings.format(room, f\"runtime: {live} objects alive at exit\\n\") catch failure:\n            recover \"runtime: objects alive at exit\\n\"\n        var e = io.stderr()\n        _ = e.write(text.bytes) catch failure: recover 0\n        return 3\n    release_buffers()\n    runtime_depth = 0\n    thread_context = 0\n    return status\n\n## A worker's end (\302\24714): its heap is its own, and it too must leave nothing alive once\n## its arguments and result are released; what it does leave stops the program.\npub func finish_task():\n    drain(0)\n    settle()\n    if live != 0:\n        var room: u8[96]\n        let text = strings.format(room, f\"runtime: {live} objects alive when a task ended\\n\") catch failure:\n            recover \"runtime: objects alive when a task ended\\n\"\n        var e = io.stderr()\n        _ = e.write(text.bytes) catch failure: recover 0\n        core.exit(3)\n    release_buffers()\n    runtime_depth = 0\n    thread_context = 0\n\n## Collecting a cycle drops its members' fields, which can release shared objects the cycle\n## held: that buffers fresh candidates and may pool temporaries. During a run the next\n## collection absorbs them, but at the end of a run there is no next, so repeat until the\n## collector's buffers settle. A bound guards against a fixpoint that never empties.\nfunc settle():\n    collect()\n    var guard: usize = 0\n    while (pending_count > 0 or root_count > 0) and guard < 1000:\n        drain(0)\n        collect()\n        guard += 1\n\n## Empty object counts do not include the collector's and temporaries pool's\n## backing allocations. A finished thread must release those too: its TLS roots\n## disappear at thread exit, so retaining capacity would leak on every spawn.\nfunc release_buffers():\n    assert(pending_count == 0 and root_count == 0 and white_count == 0)\n    if pending.length > 0:\n        free(pending) in memory.heap\n    if roots.length > 0:\n        free(roots) in memory.heap\n    if whites.length > 0:\n        free(whites) in memory.heap\n    var empty_pending: Pending[]\n    var empty_objects: Object*[]\n    pending = empty_pending\n    roots = empty_objects\n    whites = empty_objects\n", 2841};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_22 = {"#==============================================================================================\n#\n#   strings - Text operations over `str` views\n#\n#   DESCRIPTION:\n#       Text operations over `str` views; what allocates says so and uses the current allocator,\n#       and says how the allocation is given back: `release` for a text made here, `free` for\n#       the borrowed-field arrays returned by split and split_by.\n#\n#==============================================================================================\n\nimport float_text\nimport io\nimport memory\nimport numerals\n## An empty separator or needle where one is required.\npub let invalid_separator: ErrorCode = ErrorCode.package(48)\n## A result exceeds the caller's byte limit.\npub let output_too_large: ErrorCode = ErrorCode.package(49)\n## A radix outside 2 through 36.\npub let invalid_radix: ErrorCode = ErrorCode.package(50)\n## The text is not a number in the given radix.\npub let invalid_number: ErrorCode = ErrorCode.package(51)\n## The parsed value does not fit its type.\npub let number_out_of_range: ErrorCode = ErrorCode.package(52)\n", 1101};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_23 = {"#==============================================================================================\n#\n#   search - Substring search over `str`\n#\n#   DESCRIPTION:\n#       Prefix, suffix, and forward or reverse substring search, all byte-exact and\n#       allocation-free.\n#\n#==============================================================================================\n\n## Whether `text` begins with `prefix`.\npub func starts_with(text: str, prefix: str) -> bool:\n    if prefix.length > text.length:\n        return false\n    return (str)text.bytes[..<prefix.length] == prefix\n\n## Whether `text` ends with `suffix`.\npub func ends_with(text: str, suffix: str) -> bool:\n    if suffix.length > text.length:\n        return false\n    return (str)text.bytes[text.length - suffix.length..] == suffix\n\n## The byte offset of the first exact needle, or none. Empty needles match at\n## zero. No allocation or UTF-8 validation occurs; embedded NUL bytes are ordinary\n## data. The search takes linear time and constant auxiliary space.\npub func find(text: str, needle: str) -> usize\?:\n    return search_bytes(text.bytes, needle.bytes, false)\n\n## Search at or after a byte offset. An offset past the end returns none, including\n## for an empty needle. This does not require a Unicode scalar boundary.\npub func find_from(text: str, needle: str, start: usize) -> usize\?:\n    if start > text.length:\n        return none\n    let offset = search_bytes(text.bytes[start..], needle.bytes, false) else return none\n    return start + offset\n\n## The last exact occurrence, including overlaps. Empty needles match at the end.\n## Like find, this uses byte offsets, linear time, constant space and no allocation.\npub func find_last(text: str, needle: str) -> usize\?:\n    let offset = search_bytes(text.bytes, needle.bytes, true) else return none\n    return text.length - needle.length - offset\n\n## The byte offset of the last `byte` in `text`.\npub func last(text: str, byte: u8) -> usize\?:\n    var i = text.length\n    while i > 0:\n        i -= 1\n        if text.bytes[i] == byte:\n            return i\n    return none\n\n## Whether `needle` occurs anywhere in `text`.\npub func contains(text: str, needle: str) -> bool:\n    return find(text, needle) != none\n\n## Two-way matching splits the needle at a critical factorization. Match its right\n## part first, then the left; the period lets repeated prefixes be skipped without\n## comparing them again. Reversed indexing gives the same bound for find_last.\nfunc search_bytes(text: const u8[], needle: const u8[], reversed: bool) -> usize\?:\n    if needle.length == 0:\n        return 0\n    if needle.length > text.length:\n        return none\n    let (forward_split, forward_period) = maximal_suffix(needle, reversed, false)\n    let (backward_split, backward_period) = maximal_suffix(needle, reversed, true)\n    var critical = forward_split\n    var period = forward_period\n    if backward_split > critical:\n        critical = backward_split\n        period = backward_period\n    var periodic = critical <= needle.length - period\n    var index: usize = 0\n    while periodic and index < critical:\n        if search_byte(needle, index, reversed) != search_byte(needle, period + index, reversed):\n            periodic = false\n        index += 1\n    var remembered: usize = 0\n    if periodic:\n        remembered = needle.length - period\n    else:\n        let right = needle.length - critical + 1\n        period = critical if critical > right else right\n    var position: usize = 0\n    var matched_prefix: usize = 0\n    while needle.length <= text.length - position:\n        var right = critical if critical > matched_prefix else matched_prefix\n        while right < needle.length and search_byte(needle, right, reversed) == search_byte(text, position + right, reversed):\n            right += 1\n        if right < needle.length:\n            position += right - critical + 1\n            matched_prefix = 0\n            continue\n        var left = critical\n        while left > matched_prefix and search_byte(needle, left - 1, reversed) == search_byte(text, position + left - 1, reversed):\n            left -= 1\n        if left <= matched_prefix:\n            return position\n        position += period\n        matched_prefix = remembered\n    return none\n\n## Positions represent suffix starts rather than signed -1 sentinels. Every\n## advance stays within the needle; no index arithmetic wraps at usize maximum.\nfunc maximal_suffix(needle: const u8[], reversed: bool, opposite_order: bool) -> (usize, usize):\n    var left: usize = 0\n    var right: usize = 1\n    var offset: usize = 0\n    var period: usize = 1\n    while right < needle.length and offset < needle.length - right:\n        let a = search_byte(needle, right + offset, reversed)\n        let b = search_byte(needle, left + offset, reversed)\n        if a == b:\n            if offset + 1 == period:\n                right += period\n                offset = 0\n            else:\n                offset += 1\n        elif (a < b) != opposite_order:\n            right += offset + 1\n            offset = 0\n            period = right - left\n        else:\n            left = right\n            right = left + 1\n            offset = 0\n            period = 1\n    return (left, period)\n\nfunc search_byte(bytes: const u8[], index: usize, reversed: bool) -> u8:\n    return bytes[bytes.length - index - 1] if reversed else bytes[index]\n", 5375};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_24 = {"#==============================================================================================\n#\n#   split - Splitting text into views\n#\n#   DESCRIPTION:\n#       Split `str` at a byte or a substring into views over the input, once, last, or every\n#       occurrence.\n#\n#==============================================================================================\n\n## `text` split at every `separator`, as views into it; the array is an allocation of the\n## current allocator, given back with `free`.\npub func split(text: str, separator: u8) -> str[]!:\n    var count: usize = 1\n    for b in text.bytes:\n        if b == separator:\n            count = count +\? 1 else error(memory.exhausted, \"the split result is too large\")\n    let parts = try new str[count] ---\n    var n: usize = 0\n    var start: usize = 0\n    var i: usize = 0\n    let b = text.bytes\n    while i < b.length:\n        if b[i] == separator:\n            parts[n] = (str)b[start..<i]\n            n += 1\n            start = i + 1\n        i += 1\n    parts[n] = (str)b[start..]\n    return parts\n\n## Split a borrowed text at a nonempty byte substring. Empty fields, including the\n## final one after a trailing separator, are preserved. Zero is an exhausted\n## iterator. Keep text and separator storage alive and unchanged while iterating.\npub struct SplitIterator:\n    var text: str\n    var separator: str\n    var position: usize\n    var remaining: usize\n    var active: bool\n\n    ## max_parts=0 has no limit; one returns the entire input as a single field.\n    ## No allocation occurs. An empty separator reports invalid_separator.\n    pub static func over(text: str, separator: str, max_parts: usize = 0) -> SplitIterator!:\n        if separator.length == 0:\n            error(invalid_separator, \"a split iterator requires a nonempty separator\")\n        return SplitIterator(text = text, separator = separator, remaining = max_parts, active = true)\n\n    ## The next borrowed field. An empty field is present; none means exhausted.\n    pub func next() -> str\?:\n        if not self.active:\n            return none\n        if self.remaining == 1:\n            self.active = false\n            return (str)self.text.bytes[self.position..]\n        let found = find_from(self.text, self.separator, self.position)\n        if let end = found:\n            let start = self.position\n            self.position = end + self.separator.length\n            if self.remaining > 1:\n                self.remaining -= 1\n            return (str)self.text.bytes[start..<end]\n        self.active = false\n        return (str)self.text.bytes[self.position..]\n\n## An allocated array of borrowed fields with SplitIterator semantics. Free the\n## array through the allocator current on entry; its field bytes still borrow text.\n## max_parts=0 has no limit. An empty separator reports invalid_separator.\npub func split_by(text: str, separator: str, max_parts: usize = 0) -> str[]!:\n    let initial = try SplitIterator.over(text, separator, max_parts)\n    var counter = initial\n    var count: usize = 0\n    while counter.next() != none:\n        count = count +\? 1 else error(memory.exhausted, \"the split result is too large\")\n    let fields = try new str[count] ---\n    var iterator = initial\n    var index: usize = 0\n    while let field = iterator.next():\n        fields[index] = field\n        index += 1\n    return fields\n\n## Borrow the text before and after the first separator, or none if absent. The\n## separator is omitted. An empty separator splits at the start: (empty, text).\npub func split_once(text: str, separator: str) -> (str, str)\?:\n    let position = find(text, separator) else return none\n    return ((str)text.bytes[..<position], (str)text.bytes[position + separator.length..])\n\n## Borrow the text before and after the last separator, including overlapping\n## candidates. An empty separator splits at the end: (text, empty).\npub func split_last(text: str, separator: str) -> (str, str)\?:\n    let position = find_last(text, separator) else return none\n    return ((str)text.bytes[..<position], (str)text.bytes[position + separator.length..])\n", 4088};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_25 = {"#==============================================================================================\n#\n#   transform - Trimming, joining and case\n#\n#   DESCRIPTION:\n#       Trim, join, copy and ASCII case changes over `str`, returning fresh owned text.\n#\n#==============================================================================================\n\nfunc is_space(byte: u8) -> bool:\n    return byte == ' ' or byte == '\\n' or byte == '\\t' or byte == '\\r'\n\n## `text` without leading and trailing spaces, tabs, and line ends: a view.\npub func trim(text: str) -> str:\n    var start: usize = 0\n    var end = text.length\n    let b = text.bytes\n    while start < end and is_space(b[start]):\n        start += 1\n    while end > start and is_space(b[end - 1]):\n        end -= 1\n    return (str)b[start..<end]\n\n## The pieces joined with `separator` between them, NUL-terminated in the current\n## allocator; `release` gives it back.\npub func join(pieces: const str[], separator: str) -> str!:\n    var total: usize = 0\n    var i: usize = 0\n    while i < pieces.length:\n        total = total +\? pieces[i].length else error(memory.exhausted, \"the joined text is too large\")\n        if i + 1 < pieces.length:\n            total = total +\? separator.length else error(memory.exhausted, \"the joined text is too large\")\n        i += 1\n    let out = try terminated_buffer(total)\n    var n: usize = 0\n    i = 0\n    while i < pieces.length:\n        memory.copy(out[n..], pieces[i].bytes, pieces[i].length)\n        n += pieces[i].length\n        if i + 1 < pieces.length:\n            memory.copy(out[n..], separator.bytes, separator.length)\n            n += separator.length\n        i += 1\n    out[n] = 0\n    return (str)out[..<n]\n\n## A copy of `text` in the current allocator, NUL-terminated so it may be a `c.str`;\n## `release` gives it back.\npub func copy(text: str) -> str!:\n    let out = try terminated_buffer(text.length)\n    memory.copy(out, text.bytes, text.length)\n    out[text.length] = 0\n    return (str)out[..<text.length]\n\n## As much of `text` as fits in `buffer`, copied there and cut at a character's start; the\n## result views `buffer`. A caught failure's message is kept past its handler so, or with\n## `copy` (\302\24711.3).\npub func copy_into(buffer: u8[], text: str) -> str:\n    var n = text.length\n    if n > buffer.length:\n        n = buffer.length\n        while n > 0 and (text.bytes[n] & 0xC0) == 0x80:\n            n -= 1\n    memory.copy(buffer, text.bytes, n)\n    return (str)buffer[..<n]\n\n## ASCII case folding; other bytes pass through. NUL-terminated in the current\n## allocator; `release` gives the text back.\npub func to_upper(text: str) -> str!:\n    let out = try terminated_buffer(text.length)\n    var i: usize = 0\n    for b in text.bytes:\n        out[i] = b - 32 if b >= 'a' and b <= 'z' else b\n        i += 1\n    out[i] = 0\n    return (str)out[..<i]\n\n## ASCII lowercase; other bytes pass through unchanged. The result is a\n## NUL-terminated current-allocator allocation released with release.\npub func to_lower(text: str) -> str!:\n    let out = try terminated_buffer(text.length)\n    var i: usize = 0\n    for b in text.bytes:\n        out[i] = b + 32 if b >= 'A' and b <= 'Z' else b\n        i += 1\n    out[i] = 0\n    return (str)out[..<i]\n\n## Give back text from join, copy, replace, to_upper or to_lower: the allocation is\n## one byte longer than the text, its NUL.\npub func release(text: str):\n    free(u8[]((u8*)text.bytes.data, text.length + 1))\n\n## Allocate text storage including its terminator, reporting size overflow as the\n## same fallible outcome as an allocation refusal. Callers initialize every byte.\nfunc terminated_buffer(length: usize) -> u8[]!:\n    let size = length +\? 1 else error(memory.exhausted, \"the text is too large\")\n    return try new u8[size] ---\n", 3775};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_26 = {"#==============================================================================================\n#\n#   replace - Substring replacement\n#\n#   DESCRIPTION:\n#       Replace nonoverlapping byte substrings left to right into fresh owned text, with\n#       optional caps on the count and the result size.\n#\n#==============================================================================================\n\n## Replace nonoverlapping byte substrings from left to right. Empty needles report\n## invalid_separator. max_replacements=0 replaces all matches; max_bytes optionally\n## limits result bytes excluding its terminator, reporting output_too_large before\n## allocation. A result is always a fresh NUL-terminated current-allocator allocation,\n## including unchanged or empty results; release gives it back. Inputs remain borrowed\n## and unchanged and may overlap each other. No UTF-8 validation occurs.\npub func replace(text: str, needle: str, replacement: str, max_replacements: usize = 0, max_bytes: usize\? = none) -> str!:\n    if needle.length == 0:\n        error(invalid_separator, \"replacement requires a nonempty needle\")\n    var size = text.length\n    var count: usize = 0\n    var position: usize = 0\n    while max_replacements == 0 or count < max_replacements:\n        let found = find_from(text, needle, position) else break\n        if replacement.length >= needle.length:\n            size = size +\? (replacement.length - needle.length) else error(memory.exhausted, \"the replacement result is too large\")\n        else:\n            size -= needle.length - replacement.length\n        position = found + needle.length\n        count += 1\n    if let maximum = max_bytes:\n        if size > maximum:\n            error(output_too_large, \"the replacement result exceeds its byte limit\")\n    let output = try terminated_buffer(size)\n    var used: usize = 0\n    var copied: usize = 0\n    position = 0\n    while copied < count:\n        let found = find_from(text, needle, position) else trap(\"replacement input changed between scans\")\n        let prefix = found - position\n        memory.copy(output[used..], text.bytes[position..<found], prefix)\n        used += prefix\n        memory.copy(output[used..], replacement.bytes, replacement.length)\n        used += replacement.length\n        position = found + needle.length\n        copied += 1\n    let tail = text.length - position\n    memory.copy(output[used..], text.bytes[position..], tail)\n    used += tail\n    output[used] = 0\n    return (str)output[..<used]\n", 2499};
static __attribute__((unused)) lb_str lb_21sema_standard_sources_7text_27 = {"#==============================================================================================\n#\n#   numbers - Integer formatting and parsing\n#\n#   DESCRIPTION:\n#       Signed and unsigned integers in radix 2 through 36, ASCII digits only, over borrowed or\n#       caller-provided storage.\n#\n#==============================================================================================\n\n## A signed integer in radix 2 through 36. ASCII letters are case-insensitive\n## digits; prefixes are not interpreted. Optional +/- and leading zeroes are\n## accepted. None reports an invalid radix, invalid byte, missing digit or overflow.\npub func parse_i64(text: str, radix: u32 = 10) -> i64\?:\n    if radix < 2 or radix > 36 or text.length == 0:\n        return none\n    var position: usize = 0\n    var negative = false\n    if text.bytes[0] == '-' or text.bytes[0] == '+':\n        negative = text.bytes[0] == '-'\n        position = 1\n    if position == text.length:\n        return none\n    # Accumulate on the sign's side so the negative endpoint fits without abs.\n    var value: i64 = 0\n    while position < text.length:\n        let digit = integer_digit(text.bytes[position]) else return none\n        if digit >= radix:\n            return none\n        let scaled = value *\? (i64)radix else return none\n        value = (scaled -\? (i64)digit if negative else scaled +\? (i64)digit) else return none\n        position += 1\n    return value\n\n## Unsigned counterpart of parse_i64. A leading plus is accepted; every minus,\n## including -0, is rejected. The entire input must fit u64 in the requested radix.\npub func parse_u64(text: str, radix: u32 = 10) -> u64\?:\n    if radix < 2 or radix > 36 or text.length == 0:\n        return none\n    var position: usize = 1 if text.bytes[0] == '+' else 0\n    if position == text.length:\n        return none\n    var value: u64 = 0\n    while position < text.length:\n        let digit = integer_digit(text.bytes[position]) else return none\n        if digit >= radix:\n            return none\n        let scaled = value *\? (u64)radix else return none\n        value = scaled +\? (u64)digit else return none\n        position += 1\n    return value\n\n## Canonical lowercase digits, with a minus only for negative values, no prefix,\n## padding or terminator. Return a borrowed view of buffer. A 65-byte buffer always\n## suffices. Invalid radix or insufficient capacity leaves buffer unchanged.\npub func format_i64(value: i64, buffer: u8[], radix: u32 = 10) -> str!:\n    let magnitude = (u64)(-(value + 1)) + 1 if value < 0 else (u64)value\n    return try format_integer(magnitude, value < 0, buffer, radix)\n\n## Unsigned counterpart of format_i64; at most 64 bytes are needed. io.full reports\n## insufficient capacity and invalid_radix reports a radix outside 2 through 36.\npub func format_u64(value: u64, buffer: u8[], radix: u32 = 10) -> str!:\n    return try format_integer(value, false, buffer, radix)\n\nfunc integer_digit(byte: u8) -> u32\?:\n    if byte >= '0' and byte <= '9':\n        return (u32)(byte - '0')\n    if byte >= 'a' and byte <= 'z':\n        return (u32)(byte - 'a') + 10\n    if byte >= 'A' and byte <= 'Z':\n        return (u32)(byte - 'A') + 10\n    return none\n\nfunc format_integer(value: u64, negative: bool, buffer: u8[], radix: u32) -> str!:\n    if radix < 2 or radix > 36:\n        error(invalid_radix, \"an integer radix must be between 2 and 36\")\n    let digits = \"0123456789abcdefghijklmnopqrstuvwxyz\"\n    var reversed: u8[65]\n    var count: usize = 0\n    var remaining = value\n    while true:\n        reversed[count] = digits.bytes[(usize)(remaining % (u64)radix)]\n        count += 1\n        remaining //= (u64)radix\n        if remaining == 0:\n            break\n    if negative:\n        reversed[count] = '-'\n        count += 1\n    if buffer.length < count:\n        error(io.full, \"the destination cannot hold the formatted integer\")\n    var position: usize = 0\n    while position < count:\n        buffer[position] = reversed[count - position - 1]\n        position += 1\n    return (str)buffer[..<count]\n", 4035};
